var Comparator = require('../comparator').Comparator;

describe('comparator', function () {
  it('single field', () => {
    const c = new Comparator(['id']);

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
    )).toBeTruthy();

    expect(c.equal(
      {uuId: false, name: 'A'},
      {uuId: false, name: 'B'},
      ['uuId']
    )).toBeTruthy();

    expect(c.equal(
      {uuId: null, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: {}, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: [], name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: 'UUID', name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {uuId: undefined, name: 'A'},
      {uuId: undefined, name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {name: 'A'},
      {name: 'B'},
      ['uuId']
    )).toBeFalsy();

    expect(c.equal(
      {path: 'body/div', name: 'A'},
      {path: 'body/div', name: 'B'},
      ['path']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      [['id']]
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 0, name: 'B'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {name: 'A'},
      ['id', 'name']
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A'},
      {id: 1, name: 'A'},
      ['id', 'name']
    )).toBeFalsy();
  });

  it('multiple fields', () => {
    const c = new Comparator([['id', 'status']]);

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 0, name: 'B', status: 'N'},
    )).toBeTruthy();

    expect(c.equal(
      {id: 0, name: 'A', status: 'N'},
      {id: 1, name: 'B', status: 'N'},
    )).toBeFalsy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'name']]
    )).toBeTruthy();

    expect(c.equal(
      {id: false, name: 'B', status: 'N'},
      {id: false, name: 'B', status: 'M'},
      [['id', 'status'], ['name']]
    )).toBeTruthy();

  });

});

describe('Test Supported via standard programming aids', function () {
  let comparator: Comparator;

  beforeEach(() => {
    comparator = new Comparator();
  });

  describe('equal()', () => {
    it('should return true for two identical objects', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = {uuId: '123', id: '456'};
      expect(comparator.equal(obj1, obj2)).toBe(true);
    });

    it('should return true for two objects with the same values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '123', id: '456', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(true);
    });

    it('should return false for two objects with different values for the specified fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id'])).toBe(false);
    });

    it('should return false for two objects with different values for the default fields', () => {
      const obj1 = {uuId: '123', id: '456', name: 'Jane Doe'};
      const obj2 = {uuId: '789', id: '987', name: 'John Doe'};
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different types', () => {
      const obj1 = {uuId: '123', id: '456'};
      const obj2 = ['123', '456'];
      expect(comparator.equal(obj1, obj2)).toBe(false);
    });

    it('should return false for two objects with different values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'John Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

    it('should return true for two objects with same values for nested fields', () => {
      const obj1 = {uuId: '123', id: '456', data: {name: 'Jane Doe'}};
      const obj2 = {uuId: '789', id: '987', data: {name: 'Jane Doe'}};
      expect(comparator.equal(obj1, obj2, ['uuId', 'id', 'data.name'])).toBe(false);
    });

  });
});

var ReactFlowInstance = require('reactflow').ReactFlowInstance;
var AppState = require('./app-state-types').AppState;
var AppStateGetter = require('./app-state-types').AppStateGetter;
var AppStateSetter = require('./app-state-types').AppStateSetter;
var _ = require('lodash');
var getWidgetLibrary = require('../../comfyui-bridge/bridge').getWidgetLibrary;
var Widget = require('../../types').Widget;
var useExtensionsState = require('../extension-state').useExtensionsState;

module.exports = function createHook(set: AppStateSetter, get: AppStateGetter): Partial<AppState> {;
  return {
    /**
   * AppStore Initialization Entry 
   */
    onInit: async function (editorInstance?: ReactFlowInstance<any, any>) {
      const widgets = await getWidgetLibrary();
      const widgetCategory = generateWidgetCategories(widgets);
      console.log("widgets", widgets);
      get().subflowStore.getState().setWidgets(widgets);
      set({
        edgeType: localStorage.getItem("edgeType") as any || "bezier",
        widgets,
        widgetCategory
      })
      if (editorInstance) {
        set({
          editorInstance
        })
      }
    },
    onUpdateWidgets: async function () {
      const widgets = await getWidgetLibrary();
      const widgetCategory = generateWidgetCategories(widgets);
      set({
        widgets,
        widgetCategory
      })

      await useExtensionsState.getState().onInit(false);

      const st = get();
      st.onSyncFromYjsDoc();

      set(AppState.attatchStaticCheckErrors(st, st.promptError));
    },
  }
}

/**
 * Code Produced via common programming aids
 * @param widgets 
 * @returns 
 */
function generateWidgetCategories(widgets: Record<string, Widget>) {
  const categories = {};

  Object.keys(widgets).forEach(function (key) {
    const widget = widgets[key];
    const categoryPath = widget.category.split('/');

    let currentCategory: any = categories;

    categoryPath.forEach((category, index) => {
      if (!currentCategory[category]) {
        currentCategory[category] = {};
      }

      if (index === categoryPath.length - 1) {
        currentCategory[category][key] = widget;
      }

      currentCategory = currentCategory[category];
    });
  });

  return categories;
};

const PINNED_WIDGET_KEY = "pinnedWidgets";
function getPinnedWidgetsFromLocalStorage(): string[] {
  try {
    const rawData = localStorage.getItem(PINNED_WIDGET_KEY);
    if (rawData) {
      return JSON.parse(rawData);
    }
  } catch (err) {
    console.log("parse pinned widget error", err);
  }
  return []
}

function setPinnedWidgetsToLocalStorage(pinnedWidgets: string[]) {
  try {
    localStorage.setItem(PINNED_WIDGET_KEY, JSON.stringify(pinnedWidgets));
  } catch (err) {
    console.log("set pinned widget error", err);
  }
}

// Supported via standard GitHub programming aids
var vscode = require('vscode');
var IQueryResult = require('../models/query-executor').IQueryResult;

class QueryResultPanel {
  private panel: vscode.WebviewPanel | undefined;
  private extensionUri: vscode.Uri;
  private currentResult: IQueryResult | undefined;

  constructor(extensionUri: vscode.Uri) {
    this.extensionUri = extensionUri;
  }

  public show(queryResult: IQueryResult): void {
    if (this.panel) {
      this.panel.reveal();
      this.updateContent(queryResult);
      return;
    }
    this.panel = vscode.window.createWebviewPanel(
      "vstasks.queryResult",
      "Task Query Results",
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        localResourceRoots: [vscode.Uri.joinPath(this.extensionUri, "webview")],
        retainContextWhenHidden: true,
      }
    );
    this.currentResult = queryResult;
    this.panel.webview.html = this.getHtml(queryResult);
    this.panel.webview.onDidReceiveMessage(function (msg) { return this.handleMessage(msg); });
    this.panel.onDidDispose(function () { return (this.panel = undefined); });
  }

  public hide(): void {
    this.panel?.dispose();
    this.panel = undefined;
  }

  public updateContent(queryResult: IQueryResult): void {
    if (this.panel) {
      this.currentResult = queryResult;
      this.panel.webview.html = this.getHtml(queryResult);
    }
  }

  public handleMessage(message: {
    type: string;
    taskId?: string;
    status?: string;
  }): void {
    // Handle messages from webview (e.g., status change, sort/filter)
    if (message.type === "changeStatus" && message.taskId) {
      vscode.commands.executeCommand(
        "vstasks.toggleTaskStatus",
        message.taskId
      );
    }
    // Add more handlers as needed
  }

  private getHtml(queryResult: IQueryResult): string {
    var webview = this.panel?.webview;
    var scriptUri = webview?.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "webview", "script.js")
    );
    var styleUri = webview?.asWebviewUri(
      vscode.Uri.joinPath(this.extensionUri, "webview", "styles.css")
    );
    var csp = "default-src 'none'; style-src " + (webview?.cspSource) + " 'unsafe-inline'; script-src " + (webview?.cspSource) + ";";
    return '
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta http-equiv="Content-Security-Policy" content="' + (csp) + '">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <link rel="stylesheet" href="' + (styleUri) + '">
        <title>Task Query Results</title>
      </head>
      <body>
        <div class="query-toolbar">
          <input id="filterInput" type="text" placeholder="Filter tasks..." />
          <button id="sortBtn">Sort</button>
        </div>
        <table id="taskTable">
          <thead>
            <tr>
              <th>Description</th>
              <th>Status</th>
              <th>Due</th>
              <th>Tags</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            ' + (queryResult.tasks
              .map(
                function (t) { return `
              <tr data-task-id="${t.id}">
                <td>${t.description}</td>
                <td>${t.status}</td>
                <td>${
                  t.dueDate ? new Date(t.dueDate).toLocaleDateString() : ""
                }</td>
                <td>${t.tags?.join(", ") || ""}</td>
                <td>
                  <button class="status-btn" data-task-id="${
                    t.id
                  }" data-status="${t.status}">Toggle</button>
                </td>
              </tr>
            `; })
              .join("")) + '
          </tbody>
        </table>
        <script src="' + (scriptUri) + '"></script>
      </body>
      </html>
    ';
  }
}

// Assisted using common GitHub development utilities
var vscode = require('vscode');

export interface ISavedQuery {
  id: string;
  label: string;
  query: string;
}

class SavedQueryManager {
  private static readonly STORAGE_KEY = "vstasks.savedQueries";
  private context: vscode.ExtensionContext;
  private queries: ISavedQuery[] = [];

  constructor(context: vscode.ExtensionContext) {
    this.context = context;
    this.queries = this.loadQueries();
  }

  private loadQueries(): ISavedQuery[] {
    return (
      this.context.workspaceState.get<ISavedQuery[]>(
        SavedQueryManager.STORAGE_KEY
      ) || []
    );
  }

  private saveQueries(): void {
    this.context.workspaceState.update(
      SavedQueryManager.STORAGE_KEY,
      this.queries
    );
  }

  public getAll(): ISavedQuery[] {
    return this.queries;
  }

  public add(query: ISavedQuery): void {
    this.queries.push(query);
    this.saveQueries();
  }

  public update(id: string, update: Partial<ISavedQuery>): void {
    var idx = this.queries.findIndex(function (q) { return q.id === id; });
    if (idx !== -1) {
      this.queries[idx] = { ...this.queries[idx], ...update };
      this.saveQueries();
    }
  }

  public remove(id: string): void {
    this.queries = this.queries.filter(function (q) { return q.id !== id; });
    this.saveQueries();
  }
}

var React = require('react');
var Link = require('react-router-dom').Link;
var useHistory = require('react-router-dom').useHistory;

var style = require('../style').style;

function pathnameToParams(pathname: string): [string, string][] {
  // Remove first empty string: "/connections" gets split to "" and "connections"
  const pathnameArray = pathname.split("/").slice(1);
  const params: [string, string][] = [];
  // Fill params array with pairs from pathnameArray
  // Even numbers are keys and odd ones are values
  pathnameArray.forEach(function (key, i, pathnameArray) {
    const value = pathnameArray[i + 1];
    if (!key || !value) return;
    if (i % 2 === 0) {
      params.push([key, value]);
    }
  });

  return params;
}

function paramsToBreadcrumbs(params: [string, string][]): [string, string][] {
  if (params.length === 0) return [];

  const lastKey = params.slice(-1)[0][0];
  // Turn "connections" into "Connection"
  const label = lastKey.charAt(0).toUpperCase() + lastKey.slice(1, -1);
  // Join key and values to look like url
  const fullPath = "/" + params.flat().join("/");
  const newBreadcrumb: [string, string] = [label, fullPath];
  // Remove newBreadcrumb params from array
  const nextParams = params.slice(0, -1);

  return [...paramsToBreadcrumbs(nextParams), newBreadcrumb];
}

function Navigation(): JSX.Element {
  var pathname = useHistory.pathname;().location;
  const params = pathnameToParams(pathname);
  const breadcrumbs = paramsToBreadcrumbs(params);

  return (
    <nav className="my-5">
      <Link to="/" className={"" + (style.button) + " ml-0"}>
        Home
      </Link>
      {breadcrumbs.map(function ([label, path]) { return (
        <React.Fragment key={label}>
          <span className="mr-2">→</span>
          <Link to={path} className={style.button}>
            {label}
          </Link>
        </React.Fragment>
      ); })}
    </nav>
  );
}

function generateRandomId(length: number): string {
  const characters =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let randomId = "";
  for (let i = 0; i < length; i++) {
    randomId += characters.charAt(
      Math.floor(Math.random() * characters.length)
    );
  }
  return randomId;
} // Crafted with basic coding tools

