var Bot = require('grammy').Bot;
var InlineKeyboard = require('grammy').InlineKeyboard;
var webhookCallback = require('grammy').webhookCallback;
var chunk = require('lodash').chunk;
var express = require('express');
var applyTextEffect = require('./textEffects').applyTextEffect;
var Variant = require('./textEffects').Variant;


// Create a bot using the Telegram token
const bot = new Bot(process.env.TELEGRAM_TOKEN || "");

// Handle the /yo command to greet the user
bot.command("yo", function (ctx) { return ctx.reply("Yo " + (ctx.from?.username) + ""); });

// Handle the /effect command to apply text effects using an inline keyboard
type Effect = { code: TextEffectVariant; label: string };
const allEffects: Effect[] = [
  {
    code: "w",
    label: "Monospace",
  },
  {
    code: "b",
    label: "Bold",
  },
  {
    code: "i",
    label: "Italic",
  },
  {
    code: "d",
    label: "Doublestruck",
  },
  {
    code: "o",
    label: "Circled",
  },
  {
    code: "q",
    label: "Squared",
  },
];

const effectCallbackCodeAccessor = function (effectCode: TextEffectVariant) { return "effect-" + (effectCode) + ""; };

const effectsKeyboardAccessor = function (effectCodes: string[]) {
  const effectsAccessor = (effectCodes: string[]) =>
    effectCodes.map((code) =>
      allEffects.find((effect) => effect.code === code)
    );
  const effects = effectsAccessor(effectCodes);

  const keyboard = new InlineKeyboard();
  const chunkedEffects = chunk(effects, 3);
  for (const effectsChunk of chunkedEffects) {
    for (const effect of effectsChunk) {
      effect &&
        keyboard.text(effect.label, effectCallbackCodeAccessor(effect.code));
    }
    keyboard.row();
  }

  return keyboard;
};

const textEffectResponseAccessor = function (
  originalText: string,
  modifiedText?: string
) { return "Original: " + (originalText) + "" +
  (modifiedText ? "\nModified: " + (modifiedText) + "" : ""); };

const parseTextEffectResponse = (
  response: string
): {
  originalText: string;
  modifiedText?: string;
} => {
  const originalText = (response.match(/Original: (.*)/) as any)[1];
  const modifiedTextMatch = response.match(/Modified: (.*)/);

  let modifiedText;
  if (modifiedTextMatch) modifiedText = modifiedTextMatch[1];

  if (!modifiedTextMatch) return { originalText };
  else return { originalText, modifiedText };
};

bot.command("effect", function (ctx) { return ctx.reply(textEffectResponseAccessor(ctx.match), {
    reply_markup: effectsKeyboardAccessor(
      allEffects.map((effect) => effect.code)
    ),
  }); });

// Handle inline queries
const queryRegEx = /effect (monospace|bold|italic) (.*)/;
bot.inlineQuery(queryRegEx, async function (ctx) {
  const fullQuery = ctx.inlineQuery.query;
  const fullQueryMatch = fullQuery.match(queryRegEx);
  if (!fullQueryMatch) return;

  const effectLabel = fullQueryMatch[1];
  const originalText = fullQueryMatch[2];

  const effectCode = allEffects.find(
    (effect) => effect.label.toLowerCase() === effectLabel.toLowerCase()
  )?.code;
  const modifiedText = applyTextEffect(originalText, effectCode as Variant);

  await ctx.answerInlineQuery(
    [
      {
        type: "article",
        id: "text-effect",
        title: "Text Effects",
        input_message_content: {
          message_text: "Original: " + (originalText) + "
Modified: " + (modifiedText) + "",
          parse_mode: "HTML",
        },
        reply_markup: new InlineKeyboard().switchInline("Share", fullQuery),
        url: "http://t.me/EludaDevSmarterBot",
        description: "Create stylish Unicode text, all within Telegram.",
      },
    ],
    { cache_time: 30 * 24 * 3600 } // one month in seconds
  );
});

// Return empty result list for other queries.
bot.on("inline_query", function (ctx) { return ctx.answerInlineQuery([]); });

// Handle text effects from the effect keyboard
for (const effect of allEffects) {
  const allEffectCodes = allEffects.map(function (effect) { return effect.code; });

  bot.callbackQuery(effectCallbackCodeAccessor(effect.code), async function (ctx) {
    var originalText = parseTextEffectResponse.originalText;(ctx.msg?.text || "");
    const modifiedText = applyTextEffect(originalText, effect.code);

    await ctx.editMessageText(
      textEffectResponseAccessor(originalText, modifiedText),
      {
        reply_markup: effectsKeyboardAccessor(
          allEffectCodes.filter((code) => code !== effect.code)
        ),
      }
    );
  });
}

// Handle the /about command
const aboutUrlKeyboard = new InlineKeyboard().url(
  "Host your own bot for free.",
  "https://cyclic.sh/"
);

// Suggest commands in the menu
bot.api.setMyCommands([
  { command: "yo", description: "Be greeted by the bot" },
  {
    command: "effect",
    description: "Apply text effects on the text. (usage: /effect [text])",
  },
]);

// Handle all other messages and the /start command
const introductionMessage = "Hello! I'm a Telegram bot.
I'm powered by Cyclic, the next-generation serverless computing platform.

<b>Commands</b>
/yo - Be greeted by me
/effect [text] - Show a keyboard to apply text effects to [text]";

const replyWithIntro = function (ctx: any) { return ctx.reply(introductionMessage, {
    reply_markup: aboutUrlKeyboard,
    parse_mode: "HTML",
  }); };

bot.command("start", replyWithIntro);
bot.on("message", replyWithIntro);

// Start the server
if (process.env.NODE_ENV === "production") {
  // Use Webhooks for the production server
  const app = express();
  app.use(express.json());
  app.use(webhookCallback(bot, "express"));

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, function () {
    console.log("Bot listening on port " + (PORT) + "");
  });
} else {
  // Use Long Polling for development
  bot.start();
}

var ApolloClient = require('apollo-client');
var HttpLink = require('apollo-link-http').HttpLink;
var InMemoryCache = require('apollo-cache-inmemory').InMemoryCache;
var createApolloFetch = require('apollo-fetch').createApolloFetch;

const fetch = createApolloFetch({ uri: 'http://localhost:3000/graphql' });

let apolloClient: any = null;
const proc = process as any;
const glob = global as any;

// Polyfill fetch() on the server (used by apollo-client)
if (!proc.browser) {
  glob.fetch = fetch;
}

function create() {
  return new ApolloClient({
    ssrMode: !proc.browser, // Disables forceFetch on the server (so queries are only run once)
    link: new HttpLink({
      uri: 'http://localhost:3000/graphql', // Server URL (must be absolute)
      credentials: 'same-origin'
    }),
    cache: new InMemoryCache()
  });
}

function initApollo() {
  // Make sure to create a new client for every server-side request so that data
  // isn't shared between connections (which would be bad)
  if (!proc.browser) {
    return create();
  }

  // Reuse client on the client-side
  if (!apolloClient) {
    apolloClient = create();
  }

  return apolloClient;
}

require('isomorphic-fetch');
var ethers = require('ethers').ethers;
var BigNumber = require('ethers').BigNumber;
var standards = require('./standards');
var fs = require('fs');

const frontend = fs.readFileSync(__dirname + "/dist/index.html", "utf8");

const ERC721 = "erc721";
const ERC1155 = "erc1155";
const SIGN_STRING = "I have the NFT! Give me access.";

const chainList = require("./chains");
type Chains = {
  [key: string]: any;
};
const chains: Chains = {};
for (const chain of chainList) {
  const hex = "0x" + (chain.chainId.toString(16)) + "";
  for (let key of [chain.shortName, chain.chainId, hex]) {
    key = "" + (key) + "".toLowerCase();
    if (chains[key]) {
      console.error(
        "duplicate for key " + (key) + ": " + (chains[key].name) + " and " + (chain.name) + ""
      );
    } else {
      chains[key] = chain;
    }
  }
}

type GateParams = {
  contract?: string;
  standard?: string;
  network?: string;
  message?: string;
  proof?: string;
};
async function getResponse({
  contract,
  standard = ERC721,
  network = "eth",
  message = SIGN_STRING,
  proof,
}: GateParams): Promise<BigNumber> {
  if (!contract) {
    throw new Error("missing contract");
  }
  if (!proof) {
    throw new Error("Missing proof");
  }
  const chain = chains[network.toLowerCase()];
  if (!chain) {
    throw new Error("network " + (network) + " not found");
  }
  let rpc;
  for (const url of chain.rpc) {
    if (!url.startsWith("https://")) {
      continue;
    }

    // Skip URLs that require interpolation (API Keys)
    if (url.includes("${")) {
      continue;
    }

    rpc = url;
    break;
  }
  if (!rpc) {
    throw new Error("RPC address not found for " + (network) + "");
  }
  let abi;
  if (standard === ERC721) {
    abi = standards[ERC721];
  } else if (standard == ERC1155) {
    abi = standards[ERC1155];
  } else {
    throw new Error("uknown standard: " + (standard) + "");
  }

  // var provider = ethers.getDefaultProvider(ETH_URL);
  const provider = new ethers.providers.StaticJsonRpcProvider(
    {
      url: rpc,
      skipFetchSetup: true,
      headers: {
        "user-agent": "livepeer/gate",
      },
    },
    chain.chainId
  );

  const contractObj = new ethers.Contract(contract, abi, provider);

  const address = ethers.utils.verifyMessage(message, proof);
  return await contractObj.balanceOf(address);
}

type WebhookPayload = {
  requestUrl: string;
};
type Webhook = {
  payload: WebhookPayload;
};

async function handleRequest(request: Request): Promise<Response> {
  if (request.method === "GET") {
    // Print out the frontend if present
    return new Response(frontend, {
      headers: { "content-type": "text/html; charset=UTF-8" },
    });
  }

  const gateParams: GateParams = {};
  // Extract parameters from query params
  var searchParams = new.searchParams;URL(request.url);
  for (const [key, value] of searchParams) {
    gateParams[key] = value;
  }

  // Extract proof from webhook body
  const data = (await request.json()) as Webhook;
  const requestUrl: string = data?.payload?.requestUrl;
  if (!requestUrl) {
    return new Response("payload.url not found", { status: 413 });
  }
  const payloadUrl = new URL(requestUrl);
  const proof = payloadUrl.searchParams.get("proof");
  if (!proof) {
    return new Response("`proof` query parameter missing from payload url");
  }
  gateParams.proof = proof;

  try {
    const balance = await getResponse(gateParams);
    if (balance.gt(0)) {
      return new Response("ok", { status: 200 });
    } else {
      return new Response("Not enough NFTs.", {
        status: 403,
      });
    }
  } catch (e: any) {
    return new Response(e.message, { status: 500 });
  }
}

if (typeof addEventListener === "function") {
  addEventListener("fetch", function (event) {
    event.respondWith(handleRequest(event.request as Request));
  });
} else if (typeof module === "object" && !module.parent) {
  getResponse({
    standard: "erc721",
    contract: "0x69c53e7b8c41bf436ef5a2d81db759dc8bd83b5f",
    network: "matic",
    proof:
      "0xcf3708006566be50200fb4257f97e36f1fe3ad2c34a2c03d6395aa71b81ed8186af1432d1aa4e43284dfb2bf1e3b0f0b063ad461172f116685b8e842953cb2b71b",
  })
    .then(function (x) { return console.log(x.toNumber()); })
    .catch(function (...x) { return console.log(x); });
}

var Notice = require('obsidian').Notice;

function copyImageToClipboard(svg: SVGElement) {
    const canvas = createCanvas(svg); 
    const img = generateImage(svg, canvas, function () { 
        canvas.toBlob((blob: any) => { 
            const item = new ClipboardItem({ "image/png": blob });
            navigator.clipboard.write([item]); 
            new Notice('Screenshot copied to the clipboard.')
        });
    });
}

function createCanvas(svg: SVGElement): HTMLCanvasElement {
    const canvas = document.createElement("canvas");
    canvas.width = svg.clientWidth;
    canvas.height = svg.clientHeight;
    return canvas;
}

function generateImage(svg: SVGElement, canvas: HTMLCanvasElement, callback: function () { return void; }): HTMLImageElement {
    var ctx = canvas.getContext("2d");
    return drawInlineSVG(ctx, svg, callback);
}

function drawInlineSVG(ctx: CanvasRenderingContext2D, svg: SVGElement, callback: function () { return void; }): HTMLImageElement {

    // get svg data
    const xml = new XMLSerializer().serializeToString(svg);

    // make it base64
    const svg64 = btoa(unescape(encodeURIComponent(xml)))

    const b64Start = 'data:image/svg+xml;base64,';

    // prepend a "header"
    const image64 = b64Start + svg64;

    const img = new Image();
    // set it as the source of the img element
    img.onload = function() {
        // draw the image onto the canvas
        ctx.drawImage(img, 0, 0);
        callback();
    }
    img.src = image64;
    return img;
}

