type Context = object;

enum OpenError {
  AppNotFound = "AppNotFound",
  ErrorOnLaunch = "ErrorOnLaunch",
  AppTimeout = "AppTimeout",
  ResolverUnavailable = "ResolverUnavailable"
}

enum ResolveError {
  NoAppsFound = "NoAppsFound",
  ResolverUnavailable = "ResolverUnavailable",
  ResolverTimeout = "ResolverTimeout"
}

/**
* Intent descriptor
*/
interface IntentMetadata {
  name: string;
  displayName: string;
}

/**
* An interface that relates an intent to apps
*/
interface AppIntent {
  intent: IntentMetadata;
  apps: Array<AppMetadata>;
}

/**
 * App metadata is Desktop Agent specific - but should support a name property.
 */
interface AppMetadata {
  name: string;
}

/**
 * IntentResolution provides a standard format for data returned upon resolving an intent.
 * ```javascript
 * //resolve a "Chain" type intent
 * var intentR = await agent.raiseIntent("intentName", context);
 * //resolve a "Client-Service" type intent with data response
 * var intentR = await agent.raiseIntent("intentName", context);
 * var dataR = intentR.data;
 * ```
 */
interface IntentResolution {
  source: string;
  data?: object;
  version: string;
}

interface Listener {
  /**
   * Unsubscribe the listener object.
   */
  unsubscribe();
}

/**
 * A Desktop Agent is a desktop component (or aggregate of components) that serves as a
 * launcher and message router (broker) for applications in its domain.
 * 
 * A Desktop Agent can be connected to one or more App Directories and will use directories for application
 * identity and discovery. Typically, a Desktop Agent will contain the proprietary logic of
 * a given platform, handling functionality like explicit application interop workflows where
 * security, consistency, and implementation requirements are proprietary.
 */
interface DesktopAgent {
  /**
   * Launches/links to an app by name.
   * 
   * If a Context object is passed in, this object will be provided to the opened application via a contextListener.
   * The Context argument is functionally equivalent to opening the target app with no context and broadcasting the context directly to it.
   *
   * If opening errors, it returns an `Error` with a string from the `OpenError` enumeration.
   * 
   *  ```javascript
   *     //no context
   *     agent.open('myApp');
   *     //with context
   *     agent.open('myApp', context);
   * ```
   */
  open(name: string, context?: Context): Promise<void>;

  /**
   * Find out more information about a particular intent by passing its name, and optionally its context.
   *
   * findIntent is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to the intent, its metadata and metadata about the apps that registered it is returned.
   * This can be used to raise the intent against a specific app.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   * 
   * ```javascript
   * // I know 'StartChat' exists as a concept, and want to know more about it ...
   * var appIntent = await agent.findIntent("StartChat");
   * 
   * // returns a single AppIntent:
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }
   * 
   * // raise the intent against a particular app
   * await agent.raiseIntent(appIntent.intent.name, context, appIntent.apps[0].name);
   * ```
   */
  findIntent(intent: string, context?: Context): Promise<AppIntent>;

  /**
   * Find all the avalable intents for a particular context.
   *
   * findIntents is effectively granting programmatic access to the Desktop Agent's resolver. 
   * A promise resolving to all the intents, their metadata and metadata about the apps that registered it is returned,
   * based on the context types the intents have registered.
   * 
   * If the resolution fails, the promise will return an `Error` with a string from the `ResolveError` enumeration.
   *
   * ```javascript
   * // I have a context object, and I want to know what I can do with it, hence, I look for for intents...
   * var appIntents = await agent.findIntentsForContext(context);
   * 
   * // returns for example:
   * // [{
   * //     intent: { name: "StartCall", displayName: "Call" },
   * //     apps: [{ name: "Skype" }]
   * // },
   * // {
   * //     intent: { name: "StartChat", displayName: "Chat" },
   * //     apps: [{ name: "Skype" }, { name: "Symphony" }, { name: "Slack" }]
   * // }];
   * 
   * // select a particular intent to raise
   * var startChat = appIntents[1];
   * 
   * // target a particular app
   * var selectedApp = startChat.apps[0];
   * 
   * // raise the intent, passing the given context, targeting the app
   * await agent.raiseIntent(startChat.intent.name, context, selectedApp.name);
   * ```
   */
  findIntentsByContext(context: Context): Promise<Array<AppIntent>>;

  /**
   * Publishes context to other apps on the desktop.
   * ```javascript
   *  agent.broadcast(context);
   * ```
   */
  broadcast(context: Context): void;

  /**
   * Raises an intent to the desktop agent to resolve.
   * ```javascript
   * //raise an intent to start a chat with a given contact
   * var intentR = await agent.findIntents("StartChat", context);
   * //use the IntentResolution object to target the same chat app with a new context
   * agent.raiseIntent("StartChat", newContext, intentR.source);
   * ```
   */
  raiseIntent(intent: string, context: Context, target?: string): Promise<IntentResolution>;

  /**
   * Adds a listener for incoming Intents from the Agent.
   */
  addIntentListener(intent: string, handler: function (context: Context) { return void; }): Listener;

  /**
   * Adds a listener for incoming context broadcast from the Desktop Agent.
   */
  addContextListener(handler: function (context: Context) { return void; }): Listener;
}

/*
 * Created by David Adams
 * https://codeshack.io/multi-select-dropdown-html-javascript/
 *
 * Released under the MIT license
 * Supported via standard GitHub programming aids
 */

export interface MultiSelectOptions {
  placeholder?: string;
  max?: number | null;
  search?: boolean;
  selectAll?: boolean;
  listAll?: boolean;
  closeListOnItemSelect?: boolean;
  name?: string;
  width?: string;
  height?: string;
  dropdownWidth?: string;
  dropdownHeight?: string;
  data?: Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }>;
  onChange?: function (values: string[], text: string, option: HTMLElement) { return void; };
  onSelect?: function (value: string, text: string, option: HTMLElement) { return void; };
  onUnselect?: function (value: string, text: string, option: HTMLElement) { return void; };
  selectElement?: HTMLElement; // Supported via standard GitHub programming aids
  element?: HTMLElement; // Supported via standard GitHub programming aids
}

class MultiSelect {
  private _options: MultiSelectOptions;
  private _selectElement: HTMLElement;
  private _element: HTMLElement;
  private _name: string;

  constructor(element: string | HTMLElement, options: MultiSelectOptions = {}) {
    var defaults: MultiSelectOptions = {
      placeholder: "Select item(s)",
      max: null,
      search: true,
      selectAll: true,
      listAll: true,
      closeListOnItemSelect: false,
      name: "",
      width: "",
      height: "",
      dropdownWidth: "",
      dropdownHeight: "",
      data: [],
      onChange: function () {},
      onSelect: function () {},
      onUnselect: function () {},
    };
    this._options = { ...defaults, ...options };
    this._selectElement =
      typeof element === "string"
        ? (document.querySelector(element) as HTMLElement)
        : element;

    for (var prop in this._selectElement.dataset) {
      if (this._options[prop as keyof MultiSelectOptions] !== undefined) {
        var value = this._selectElement.dataset[prop];
        if (value !== undefined) {
          (this._options as any)[prop as keyof MultiSelectOptions] = value;
        }
      }
    }

    this._name =
      this._selectElement.getAttribute("name") ||
      "multi-select-" + Math.floor(Math.random() * 1000000);

    if (!this._options.data!.length) {
      var options = this._selectElement.querySelectorAll("option");
      options.forEach(function (option) {
        this._options.data!.push({
          value: option.value,
          text: option.innerHTML || option.value,
          selected: option.selected,
          html: option.getAttribute("data-html"),
        });
      });
    }

    this._element = this._template();
    this._selectElement.replaceWith(this._element);
    this._updateSelected();
    this._eventHandlers();
  }

  private _template(): HTMLElement {
    var optionsHTML = "";
    for (var i = 0; i < this.data.length; i++) {
      optionsHTML += '
        <div class="multi-select-option' + (this.selectedValues.includes(this.data[i].value) ? " multi-select-selected" : "") + '" data-value="' + (this.data[i].value) + '">
          <span class="multi-select-option-radio"></span>
          <span class="multi-select-option-text">' + (this.data[i].html ? this.data[i].html : this.data[i].text) + "</span>
        </div>
      ";
    }

    var selectAllHTML = "";
    if (this._options.selectAll) {
      selectAllHTML = '<div class="multi-select-all">
        <span class="multi-select-option-radio"></span>
        <span class="multi-select-option-text">Select all</span>
      </div>';
    }

    var template = '
      <div class="multi-select ' + (this._name) + '"' + (this._selectElement.id ? ' id="' + this._selectElement.id + '"' : "") + ' style="' + (this.width ? "width:" + this.width + ";" : "") + "" + (this.height ? "height:" + this.height + ";" : "") + '">
        ' + (this.selectedValues.map((value) => `<input type="hidden" name="${this._name}[]" value="${value}">`).join("")) + '
        <div class="multi-select-header" style="' + (this.width ? "width:" + this.width + ";" : "") + "" + (this.height ? "height:" + this.height + ";" : "") + '">
          <span class="multi-select-header-max">' + (this._options.max ? this.selectedValues.length + "/" + this._options.max : "") + '</span>
          <span class="multi-select-header-placeholder">' + (this.placeholder) + '</span>
        </div>
        <div class="multi-select-options" style="' + (this._options.dropdownWidth ? "width:" + this._options.dropdownWidth + ";" : "") + "" + (this._options.dropdownHeight ? "height:" + this._options.dropdownHeight + ";" : "") + '">
          ' + (this._options.search ? '<input type="text" class="multi-select-search" placeholder="Search...">' : "") + "
          " + (selectAllHTML) + "
          " + (optionsHTML) + "
        </div>
      </div>
    ";

    var element = document.createElement("div");
    element.innerHTML = template;
    return element;
  }

  private _eventHandlers(): void {
    var headerElement = this._element.querySelector(
      ".multi-select-header",
    ) as HTMLElement;

    this._element.querySelectorAll(".multi-select-option").forEach(function (option) {
      option.addEventListener("click", () => {
        var selected = true;
        var optionText = option.querySelector(
          ".multi-select-option-text",
        )!.innerHTML;
        var optionData = option.getAttribute("data-value");
        if (!option.classList.contains("multi-select-selected")) {
          if (
            this._options.max &&
            this.selectedValues.length >= this._options.max
          ) {
            return;
          }

          option.classList.add("multi-select-selected");
          if (this._options.listAll) {
            if (this._element.querySelector(".multi-select-header-option")) {
              var opt = Array.from(
                this._element.querySelectorAll(".multi-select-header-option"),
              ).pop() as HTMLElement;
              opt.insertAdjacentHTML(
                "afterend",
                '<span class="multi-select-header-option" data-value="' + (optionData) + '"></span>',
              );
            } else {
              headerElement.insertAdjacentHTML(
                "afterbegin",
                '<span class="multi-select-header-option" data-value="' + (optionData) + '">' + (optionText) + "</span>",
              );
            }
          }
          this._element.insertAdjacentHTML(
            "afterbegin",
            '<input type="hidden" name="' + (this._name) + '[]" value="' + (optionData) + '">',
          );
          this.data.find((data) => data.value == optionData)!.selected = true;
        } else {
          option.classList.remove("multi-select-selected");
          this._element
            .querySelectorAll(".multi-select-header-option")
            .forEach((headerOption) => {
              if (headerOption.getAttribute("data-value") == optionData) {
                headerOption.remove();
              }
            });
          this._element.querySelector('input[value="' + (optionData) + '"]')!.remove();
          this.data.find((data) => data.value == optionData)!.selected = false;
          selected = false;
        }

        if (!this._element.querySelector(".multi-select-header-option")) {
          //headerElement.insertAdjacentHTML('afterbegin', `<span class="multi-select-header-placeholder">${this.placeholder}</span>`);
        }
        if (this._element.querySelector(".multi-select-header-placeholder")) {
          this._element
            .querySelector(".multi-select-header-placeholder")!
            .remove();
        }
        for (var e of headerElement.querySelectorAll(
          ".multi-select-header-option",
        )) {
          e.remove();
        }
        if (this.selectedValues.length > 0) {
          this.selectedValues.forEach((value) => {
            var text = this.data.find((data) => data.value == value)!.text;
            headerElement.insertAdjacentHTML(
              "afterbegin",
              '<span class="multi-select-header-option" data-value="' + (value) + '">' + (text) + "</span>",
            );
          });
        } else {
          headerElement.insertAdjacentHTML(
            "afterbegin",
            '<span class="multi-select-header-placeholder">' + (this.placeholder) + "</span>",
          );
        }

        if (this._options.max) {
          this._element.querySelector(".multi-select-header-max")!.innerHTML =
            this.selectedValues.length + "/" + this._options.max;
        }

        if (this._options.search) {
          (
            this._element.querySelector(
              ".multi-select-search",
            ) as HTMLInputElement
          ).value = "";
        }

        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => option.setAttribute("style", "display: flex;"));

        if (this._options.closeListOnItemSelect) {
          headerElement.classList.remove("multi-select-header-active");
        }

        this._options.onChange!(
          this.selectedValues,
          optionText,
          option as HTMLElement,
        );

        if (selected) {
          this._options.onSelect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        } else {
          this._options.onUnselect!(
            optionData!,
            optionText,
            option as HTMLElement,
          );
        }
      });
    });

    headerElement.addEventListener("click", function () { return headerElement.classList.toggle("multi-select-header-active"); },
    );

    if (this._options.search) {
      var search = this._element.querySelector(
        ".multi-select-search",
      ) as HTMLInputElement;
      search.addEventListener("input", function () {
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            option.setAttribute(
              "style",
              option
                .querySelector(".multi-select-option-text")!
                .innerHTML.toLowerCase()
                .includes(search.value.toLowerCase())
                ? "display: flex;"
                : "display: none;",
            );
          });
      });
    }

    if (this._options.selectAll) {
      var selectAllButton = this._element.querySelector(
        ".multi-select-all",
      ) as HTMLElement;
      selectAllButton.addEventListener("click", function () {
        var allSelected = selectAllButton.classList.contains(
          "multi-select-selected",
        );
        this._element
          .querySelectorAll(".multi-select-option")
          .forEach((option) => {
            var dataItem = this.data.find(
              (data) => data.value == option.getAttribute("data-value"),
            );
            if (
              dataItem &&
              ((allSelected && dataItem.selected) ||
                (!allSelected && !dataItem.selected))
            ) {
              (option as HTMLElement).click();
            }
          });
        selectAllButton.classList.toggle("multi-select-selected");
      });
    }

    if (
      this._selectElement.id &&
      document.querySelector('label[for="' + (this._selectElement.id) + '"]')
    ) {
      document
        .querySelector('label[for="' + (this._selectElement.id) + '"]')!
        .addEventListener("click", function () {
          headerElement.classList.toggle("multi-select-header-active");
        });
    }

    document.addEventListener("click", function (event) {
      if (
        !(event.target as Element).closest("." + (this._name) + "") &&
        !(event.target as Element).closest(
          'label[for="' + (this._selectElement.id) + '"]',
        )
      ) {
        headerElement.classList.remove("multi-select-header-active");
      }
    });
  }

  private _updateSelected(): void {
    if (this._options.listAll) {
      this._element
        .querySelectorAll(".multi-select-option")
        .forEach(function (option) {
          if (option.classList.contains("multi-select-selected")) {
            this._element
              .querySelector(".multi-select-header")!
              .insertAdjacentHTML(
                "afterbegin",
                '<span class="multi-select-header-option" data-value="' + (option.getAttribute("data-value")) + '">' + (option.querySelector(".multi-select-option-text")!.innerHTML) + "</span>",
              );
          }
        });
    } else {
      if (this.selectedValues.length > 0) {
        this._element
          .querySelector(".multi-select-header")!
          .insertAdjacentHTML(
            "afterbegin",
            '<span class="multi-select-header-option">' + (this.selectedValues.length) + " selected</span>",
          );
      }
    }

    if (this._element.querySelector(".multi-select-header-option")) {
      this._element.querySelector(".multi-select-header-placeholder")!.remove();
    }
  }

  get selectedValues(): string[] {
    return this.data.filter(function (data) { return data.selected; }).map(function (data) { return data.value; });
  }

  get selectedItems(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this.data.filter(function (data) { return data.selected; });
  }

  set data(
    value: Array<{
      value: string;
      text: string;
      selected: boolean;
      html: string | null;
    }>,
  ) {
    this._options.data = value;
  }

  get data(): Array<{
    value: string;
    text: string;
    selected: boolean;
    html: string | null;
  }> {
    return this._options.data!;
  }

  set selectElement(value: HTMLElement) {
    this._options.selectElement = value;
  }

  get selectElement(): HTMLElement {
    return this._options.selectElement!;
  }

  set element(value: HTMLElement) {
    this._options.element = value;
  }

  get element(): HTMLElement {
    return this._options.element!;
  }

  set placeholder(value: string) {
    this._options.placeholder = value;
  }

  get placeholder(): string {
    return this._options.placeholder!;
  }

  set name(value: string) {
    this._options.name = value;
  }

  get name(): string {
    return this._options.name!;
  }

  set width(value: string) {
    this._options.width = value;
  }

  get width(): string {
    return this._options.width!;
  }

  set height(value: string) {
    this._options.height = value;
  }

  get height(): string {
    return this._options.height!;
  }
}

