export interface Config {
  port: string;
  staticPath: string;
  googleCloudApiKey: string;
  toxicityAttribute: string;
  cloudProjectId: string;
  isProduction: boolean;
  recaptchaConfig?: {
    // The reCAPTCHA secret key for the site issuing requests to this server.
