var createServerClient = require('@supabase/ssr').createServerClient;
var type = require('@supabase/ssr').type;
var CookieOptions = require('@supabase/ssr').CookieOptions;
var NextResponse = require('next/server').NextResponse;
var type = require('next/server').type;
var NextRequest = require('next/server').NextRequest;

export async function middleware(request: NextRequest) {
  var response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  var supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return request.cookies.get(name)?.value
        },
        set(name: string, value: string, options: CookieOptions) {
          request.cookies.set({
            name,
            value,
            ...options,
          })
          response = NextResponse.next({
            request: {
              headers: request.headers,
            },
          })
          response.cookies.set({
            name,
            value,
            ...options,
          })
        },
        remove(name: string, options: CookieOptions) {
          request.cookies.set({
            name,
            value: '',
            ...options,
          })
          response = NextResponse.next({
            request: {
              headers: request.headers,
            },
          })
          response.cookies.set({
            name,
            value: '',
            ...options,
          })
        },
      },
    }
  )

  await supabase.auth.getUser()

  return response
}

