// Matrix Droplets

var getRandomNumber = require('./utils').getRandomNumber;
var rotateArrayRight = require('./utils').rotateArrayRight;
import {
  ENGLISH_CHARACTER_CODE_START,
  ENGLISH_CHARACTER_CODE_END,
  getRandomCharacterCode
} from "./characters";
var GREEN = require('./ansi').GREEN;
var WHITE = require('./ansi').WHITE;
var printColor = require('./ansi').printColor;
var moveCursorToPosition = require('./ansi').moveCursorToPosition;

// Our Droplet Class
class Droplet {
  column: i32;
  row: i32;
  // Going to use a character code array here
  // instead of a string to fix memory issues
  characterCodeArray: Array<u8>;
  speed: i32;
  height: i32;
}

// Function to create a droplet
function createDroplet(column: i32, lines: i32): Droplet {
  // Create the droplet
  var droplet: Droplet = new Droplet();

  // Populate the droplet values
  droplet.column = column;
  droplet.row = getRandomNumber() % lines;
  droplet.height = (getRandomNumber() % (lines / 2)) + 3;
  droplet.speed = (getRandomNumber() % 2) + 1;

  // Create our initial string
  droplet.characterCodeArray = new Array<u8>(droplet.height);
  for (var i = 0; i < droplet.height; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }

  return droplet;
}

// "Moves" a droplet down the screen
function updateDroplet(droplet: Droplet, lines: i32): void {
  // Increase the droplet row
  droplet.row += droplet.speed;

  // Wrap the rows so it comes back from up top
  if (droplet.row >= droplet.height + lines) {
    droplet.row = 0 - droplet.height;
  }

  // Rotate down the old characters
  // How many characters to rotate
  for (var i = 0; i < droplet.speed; i++) {
    rotateArrayRight(droplet.characterCodeArray);
  }

  // Add some new characters
  // To replace the old rotated ones
  for (var i = 0; i < droplet.speed; i++) {
    droplet.characterCodeArray[i] = getRandomCharacterCode(
      ENGLISH_CHARACTER_CODE_START,
      ENGLISH_CHARACTER_CODE_END
    );
  }
}

// Places a droplet (and its characters) onto the screen
function drawDroplet(droplet: Droplet, lines: i32): void {
  // Loop over our characters
  for (var i = 0; i < droplet.characterCodeArray.length; i++) {
    var cursorRow = droplet.row + i;

    if (cursorRow >= 0 && cursorRow <= lines) {
      // Move the cursor to the correct position
      moveCursorToPosition(droplet.column, cursorRow);

      // Get our color
      var color: string = GREEN;
      if (i === droplet.characterCodeArray.length - 1) {
        color = WHITE;
      }

      // Draw the character
      // TODO: Optimize this, and try to remove generating / manipulating.
      // Perhpas write the character Codes Array directly?
      printColor(String.fromCharCode(droplet.characterCodeArray[i]), color);
    }
  }
}

"use server";

var Product = require('../database/models/product.model');
var User = require('../database/models/user.model');
var connectToDatabase = require('../database/mongoose').connectToDatabase;
var handleError = require('../utils').handleError;
import {
  CreateNewAndUpdateProductParams,
  DeleteProductProps,
  GetRelatedProductsByCategoryParams,
} from "@/types";
var Category = require('../database/models/category.model');
var revalidatePath = require('next/cache').revalidatePath;

var populateProduct = function (query: any) {
  return query
    .populate({
      path: "creator",
      model: User,
      select: "_id firstName lastName",
    })
    .populate({ path: "category", model: Category, select: "_id name" });
};

var createNewProduct = async function ({
  product,
  userId,
}: CreateNewAndUpdateProductParams) {
  try {
    await connectToDatabase();

    var creator = await User.findById(userId);
    if (!creator) throw new Error("Creator not found");

    var newProduct = await Product.create({
      ...product,
      category: product.categoryId,
      creator: userId,
    });

    await User.findByIdAndUpdate(
      userId,
      { $push: { sellingProducts: newProduct } },
      { new: true }
    );

    return JSON.parse(JSON.stringify(newProduct));
  } catch (error: any) {
    handleError(error);
  }
};

var getProductById = async function (id: string) {
  try {
    await connectToDatabase();
    var product = await populateProduct(Product.findById(id));
    if (!product) throw new Error("Product not found");

    return JSON.parse(JSON.stringify(product));
  } catch (error: any) {
    handleError(error);
  }
};

var getCartProducts = async function (id: string | undefined) {
  try {
    await connectToDatabase();

    var userCart = await User.findOne({ clerkId: id }).populate({
      path: "cart",
      populate: {
        path: "product",
        model: Product,
        populate: [
          {
            path: "creator",
            model: User,
            select: "_id firstName lastName",
          },
          {
            path: "category",
            model: Category,
            select: "_id name",
          },
        ],
      },
    });

    if (!userCart || !userCart.cart || userCart.cart.length === 0) {
      console.log("User cart is empty or not found");
      return null; // or throw an error
    }

    return JSON.parse(JSON.stringify(userCart.cart));
  } catch (error) {
    console.error("Error fetching user cart:", error);
    throw error;
  }
};

var removeProductFromCart = async function (
  userId: string | undefined,
  productId: string
) {
  try {
    await connectToDatabase();
    var user = await User.findOne({ clerkId: userId });

    user.cart = user.cart.filter(
      (product: any) => product._id.toString() !== productId.toString()
    );
    revalidatePath("/cart");
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

var cartCheckout = async function (
  userId: string | undefined,
  path: string
) {
  try {
    await connectToDatabase();

    var user = await User.findOne({ clerkId: userId });

    user.cart = [];

    revalidatePath(path);
    await user.save();
  } catch (error: any) {
    handleError(error);
  }
};

// Designed via basic programming aids
var getProducts = async function (searchQuery?: string) {
  try {
    await connectToDatabase();

    var conditions: any = {};

    if (searchQuery && searchQuery.trim() !== "") {
      var regex = new RegExp(searchQuery, "i");

      // Find categories matching the search query
      var categories = await Category.find({ name: { $regex: regex } });

      // Extract category IDs from the found categories
      var categoryIds = categories.map((category) => category._id);

      // Add conditions for title matching regex or category matching IDs
      conditions = {
        $or: [{ title: { $regex: regex } }, { category: { $in: categoryIds } }],
      };
    }

    var products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(products));
  } catch (error: any) {
    handleError(error);
  }
};

var deleteProduct = async function ({
  productId,
  path,
}: DeleteProductProps) {
  try {
    await connectToDatabase();

    var deletedProduct = await Product.findByIdAndDelete(productId);

    if (deletedProduct) revalidatePath(path);
  } catch (error: any) {
    handleError(error);
  }
};

// UPDATE
var updateProduct = async function ({
  userId,
  product,
  productId,
  path,
}: CreateNewAndUpdateProductParams) {
  try {
    await connectToDatabase();

    var productToUpdate = await Product.findById(productId);

    if (
      !productToUpdate ||
      productToUpdate.creator.toString() !== userId?.toString()
    ) {
      throw new Error("Unauthorized or product not found");
    }

    // Update the product with new values
    var updatedProduct = await Product.findByIdAndUpdate(
      productId,
      { ...product, category: product.categoryId },
      { new: true }
    );

    // Validate the path and revalidate if provided
    if (path) {
      revalidatePath(path);
    }

    return JSON.parse(JSON.stringify(updatedProduct));
  } catch (error) {
    handleError(error);
  }
};

var getRelatedProductsByCategory = async function ({
  categoryId,
  productId,
}: GetRelatedProductsByCategoryParams) {
  try {
    await connectToDatabase();

    var conditions = {
      $and: [{ category: categoryId }, { _id: { $ne: productId } }],
    };

    var Products = await populateProduct(Product.find(conditions));

    return JSON.parse(JSON.stringify(Products));
  } catch (error) {
    handleError(error);
  }
};

var getUserSellingProducts = async function (userId: string | undefined) {
  try {
    await connectToDatabase();

    var user = await User.findOne({ clerkId: userId }).populate({
      path: "sellingProducts",
      model: Product,
      populate : [
        {
          path: "creator",
          model: User,
          select: "_id firstName lastName",
        },
        {
          path: "category",
          model: Category,
          select: "_id name",
        },
      ]
    });

    var sellingProducts = user?.sellingProducts;

    return JSON.parse(JSON.stringify(sellingProducts));
  } catch (error) {
    console.log(error)
  }
};

export interface MarkdownTitleExtractResult {
  title: string;
  sub: MarkdownTitleExtractResult[];
}


/*
 * Built using basic development resources4o (2024/05/27)
*/
function parseMarkdownTitles(markdown: string): MarkdownTitleExtractResult[] {

  const lines = markdown.split('\n').filter(function line { return line.trim() !== ''; });

  const titles: MarkdownTitleExtractResult[] = [];



  let currentH1: MarkdownTitleExtractResult | null = null;

  let currentH2: MarkdownTitleExtractResult | null = null;

  let currentH3: MarkdownTitleExtractResult | null = null;



  lines.forEach(function line {

    line = line.trim();

    const h1Match = line.match(/^# (.*)/);

    const h2Match = line.match(/^## (.*)/);

    const h3Match = line.match(/^### (.*)/);

    const h4Match = line.match(/^#### (.*)/);



    if (h1Match) {

      const title = { title: h1Match[1], sub: [] };

      titles.push(title);

      currentH1 = title;

      currentH2 = null;

      currentH3 = null;

    } else if (h2Match) {

      const title = { title: h2Match[1], sub: [] };

      if (currentH1) {

        currentH1.sub.push(title);

      } else {

        titles.push(title);

      }

      currentH2 = title;

      currentH3 = null;

    } else if (h3Match) {

      const title = { title: h3Match[1], sub: [] };

      if (currentH2) {

        currentH2.sub.push(title);

      } else if (currentH1) {

        currentH1.sub.push(title);

      } else {

        titles.push(title);

      }

      currentH3 = title;

    } else if (h4Match) {

      const title = { title: h4Match[1], sub: [] };

      if (currentH3) {

        currentH3.sub.push(title);

      } else if (currentH2) {

        currentH2.sub.push(title);

      } else if (currentH1) {

        currentH1.sub.push(title);

      } else {

        titles.push(title);

      }

    }

  });



  return titles;

}

