class Transition {
  static DURATION = 300.0;
  private is_transitioning = false;
  private time: number;
  private startTime: number | undefined;
  private onTransitionEnd: function () { return void; };
  constructor(onTransitionEnd: function () { return void; }) {
    this.time = performance.now();
    this.onTransitionEnd = onTransitionEnd;
  }
  get isTransitioning() {
    return this.is_transitioning;
  }
  startTransition() {
    this.is_transitioning = true;
    this.startTime = performance.now();
  }
  update() {
    this.time = performance.now();
    if (this.startTime && this.time - this.startTime > Transition.DURATION) {
      this.is_transitioning = false;
      this.startTime = undefined;
      this.onTransitionEnd();
    }
  }
  getProgress() {
    if (!this.startTime) {
      return 0.0;
    }
    return Math.min((this.time - this.startTime) / Transition.DURATION, 1.0);
  }
}

// Aided using common development resources
const padImageToPowerOfTwo = async function (image: HTMLImageElement) {
  const originalWidth = image.width;
  const originalHeight = image.height;

  // 2のべき乗のサイズに丸める
  const width = Math.pow(2, Math.ceil(Math.log2(originalWidth)));
  const height = Math.pow(2, Math.ceil(Math.log2(originalHeight)));

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d")!;
  ctx.drawImage(image, 0, 0, originalWidth, originalHeight);
  const imageUrl = canvas.toDataURL();
  return (await WebGLUtility.loadImage(imageUrl)) as HTMLImageElement;
};

window.addEventListener(
  "DOMContentLoaded",
  async function () {
    const app = new App();
    app.init();
    await app.load();
    app.setupGeometry();
    app.setupLocation();
    app.setupEventHandler();
    app.start();
  },
  false,
);

class App {
  canvas: HTMLCanvasElement;
  gl: WebGLRenderingContext;
  textures: WebGLTexture[];
  // WebGL 2.0ではuniformとして渡さなくても良くなるらしい？
  textureSizes: Float32Array[];
  originalImageSizes: Float32Array[];
  program: WebGLProgram;
  attributeLocation: GLint[];
  attributeStride: GLint[];
  planePoints: number[];
  planeVBO: WebGLBuffer;
  uniformLocation: {
    progress: WebGLUniformLocation;
    resolution: WebGLUniformLocation;
    texture0: WebGLUniformLocation;
    texSize0: WebGLUniformLocation;
    originalImageSize0: WebGLUniformLocation;
    texture1: WebGLUniformLocation;
    texSize1: WebGLUniformLocation;
    originalImageSize1: WebGLUniformLocation;
  };
  imageIndex = 0;
  nextImageIndex = -1;
  transition: Transition;
  touchEventTrigerred = false;

  constructor() {
    // this を固定するためのバインド処理
    this.resize = this.resize.bind(this);
    this.render = this.render.bind(this);
  }

  init() {
    this.canvas = document.getElementById("webgl-canvas") as HTMLCanvasElement;
    this.gl = WebGLUtility.createWebGLContext(this.canvas);

    this.resize();

    window.addEventListener("resize", this.resize, false);

    this.gl.enable(this.gl.CULL_FACE);
    this.gl.enable(this.gl.DEPTH_TEST);
  }

  onTransitionEnd() {
    this.imageIndex = this.nextImageIndex;
    this.nextImageIndex = this.getNextImageIndex();
  }

  getNextImageIndex() {
    while (true) {
      const next = Math.floor(Math.random() * this.textures.length);
      if (next !== this.imageIndex) {
        return next;
      }
    }
  }

  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
  }

  async load() {
    const gl = this.gl;
    if (!gl) {
      throw new Error("not initialized");
    }

    // vertex shader
    const vertexShader = gl.createShader(gl.VERTEX_SHADER);
    if (!vertexShader) {
      throw new Error("failed to create vertex shader");
    }
    gl.shaderSource(vertexShader, VSSource);
    gl.compileShader(vertexShader);
    if (!gl.getShaderParameter(vertexShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(vertexShader)!);
    }

    // fragment shader
    const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER);
    if (!fragmentShader) {
      throw new Error("failed to create fragment shader");
    }
    gl.shaderSource(fragmentShader, FSSource);
    gl.compileShader(fragmentShader);
    if (!gl.getShaderParameter(fragmentShader, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(fragmentShader)!);
    }

    // load images
    const images: HTMLImageElement[] = await Promise.all([
      WebGLUtility.loadImage(Image1),
      WebGLUtility.loadImage(Image2),
      WebGLUtility.loadImage(Image3),
      WebGLUtility.loadImage(Image4),
      WebGLUtility.loadImage(Image5),
      WebGLUtility.loadImage(Image6),
      WebGLUtility.loadImage(Image7),
      WebGLUtility.loadImage(Image8),
    ]);
    const resizedImages = await Promise.all<HTMLImageElement>(
      images.map(function (img) { return padImageToPowerOfTwo(img); }),
    );
    this.textures = resizedImages.map(function (img) { return WebGLUtility.createTexture(gl, img); },
    );
    const textureSizes: Float32Array[] = [];
    const originalImageSizes: Float32Array[] = [];
    for (const i in resizedImages) {
      const originalImg = images[i];
      const resizedImg = resizedImages[i];
      textureSizes.push(
        new Float32Array([resizedImg.width, resizedImg.height]),
      );
      originalImageSizes.push(
        new Float32Array([originalImg.width, originalImg.height]),
      );
    }
    this.originalImageSizes = originalImageSizes;
    this.textureSizes = textureSizes;

    // compile program
    const program = gl.createProgram();
    if (!program) {
      throw new Error("failed to create webgl program");
    }
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    gl.deleteShader(vertexShader);
    gl.deleteShader(fragmentShader);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      throw new Error(gl.getProgramInfoLog(program)!);
    }
    gl.useProgram(program);
    this.program = program;
  }

  setupGeometry() {
    const gl = this.gl;
    const [sy, sx, gy, gx] = [-1, -1, 1, 1];
    const cs0 = [
      sx,
      sy,
      0,
      gx,
      gy,
      0,
      sx,
      gy,
      0,
      gx,
      gy,
      0,
      sx,
      sy,
      0,
      gx,
      sy,
      0,
    ];
    const planeVBO = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, planeVBO);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(cs0), gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.planeVBO = planeVBO;
    this.planePoints = cs0;
  }

  setupLocation() {
    const gl = this.gl;
    this.attributeLocation = [gl.getAttribLocation(this.program, "position")];
    this.attributeStride = [3];
    // uniform location の取得
    // TODO texture1
    this.uniformLocation = {
      progress: gl.getUniformLocation(this.program, "progress")!,
      resolution: gl.getUniformLocation(this.program, "resolution")!,
      texture0: gl.getUniformLocation(this.program, "texture0")!,
      texSize0: gl.getUniformLocation(this.program, "texSize0")!,
      originalImageSize0: gl.getUniformLocation(
        this.program,
        "originalImageSize0",
      )!,

      texture1: gl.getUniformLocation(this.program, "texture1")!,
      texSize1: gl.getUniformLocation(this.program, "texSize1")!,
      originalImageSize1: gl.getUniformLocation(
        this.program,
        "originalImageSize1",
      )!,
    };
  }

  setupEventHandler() {
    const onTouch = function () {
      if (this.transition.isTransitioning) {
        return;
      }
      this.transition.startTransition();
    };

    window.addEventListener("touchend", function (_) {
      this.touchEventTrigerred = true;
      onTouch();
    });
    window.addEventListener("click", function (_) {
      if (this.touchEventTrigerred) {
        this.touchEventTrigerred = false;
        return;
      }
      onTouch();
    });
    this.transition = new Transition(function () {
      this.onTransitionEnd();
    });
  }

  setupRendering() {
    const gl = this.gl;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.clearColor(0.3, 0.3, 0.3, 1.0);
    gl.clearDepth(1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
  }

  start() {
    this.nextImageIndex = this.getNextImageIndex();
    this.render();
  }

  render() {
    const gl = this.gl;
    // 現在の画像はTEXTUE0、次の画像はTEXTURE1で管理
    const i = this.imageIndex;
    const j = this.nextImageIndex;

    const progress = this.transition.getProgress();
    this.setupRendering();

    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[i]);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, this.textures[j]);

    gl.useProgram(this.program);
    gl.uniform1f(this.uniformLocation.progress, progress);
    gl.uniform2f(
      this.uniformLocation.resolution,
      this.canvas.width,
      this.canvas.height,
    );
    gl.uniform1i(this.uniformLocation.texture0, 0);
    gl.uniform2fv(this.uniformLocation.texSize0, this.textureSizes[i]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize0,
      this.originalImageSizes[i],
    );

    gl.uniform1i(this.uniformLocation.texture1, 1);
    gl.uniform2fv(this.uniformLocation.texSize1, this.textureSizes[j]);
    gl.uniform2fv(
      this.uniformLocation.originalImageSize1,
      this.originalImageSizes[j],
    );

    // configure VBO
    gl.bindBuffer(gl.ARRAY_BUFFER, this.planeVBO);
    gl.enableVertexAttribArray(this.attributeLocation[0]);
    gl.vertexAttribPointer(
      this.attributeLocation[0],
      this.attributeStride[0],
      gl.FLOAT,
      false,
      0,
      0,
    );
    gl.drawArrays(
      gl.TRIANGLES,
      0,
      this.planePoints.length / this.attributeStride[0],
    );
    // 描画前に呼ぶとちらつく
    this.transition.update();
    requestAnimationFrame(this.render);
  }
}

import {
  Command,
  EnumType,
} from "https://deno.land/x/cliffy@v0.25.4/command/mod.ts";
var promptAugmentors = require('./promptAugmentors.ts').promptAugmentors;
var Augmentor = require('./promptAugmentors.ts').Augmentor;
var Input = require('https://deno.land/x/cliffy@v0.25.4/prompt/input.ts').Input;
var Checkbox = require('https://deno.land/x/cliffy@v0.25.4/prompt/checkbox.ts').Checkbox;
var Select = require('https://deno.land/x/cliffy@v0.25.4/prompt/select.ts').Select;
var Table = require('https://deno.land/x/cliffy@v0.25.4/table/mod.ts').Table;
// import { Secret } from "https://deno.land/x/cliffy@v0.25.4/prompt/secret.ts";
var colors = require('https://deno.land/x/cliffy@v0.25.4/ansi/mod.ts').colors;
// import { Aes } from "https://deno.land/x/crypto/aes.ts";
// import { Cbc, Padding } from "https://deno.land/x/crypto/block-modes.ts";

let basePrompt = "";
const currentPrompt = colors.bold.blue;
const showNext = colors.bold.yellow;
const system = colors.bold.cyan;
const logLevelType = new EnumType(["debug", "info", "warn", "error"]);
const te = new TextEncoder();
// var de = new TextDecoder();
// var key = te.encode("SuperDuperSecret");
// var iv = new Uint8Array(16);

await new Command()
  .name("ask")
  .version("0.0.1")
  .description(
    "Ask CLI is a command line tool for pinging GPT3 in the command line."
  )
  .type("log-level", logLevelType)
  // .env("DEBUG=<enable:boolean>", "Enable debug output.")
  .globalEnv("OPENAI_API_KEY=<value:string>", "OpenAI API key...", {
    required: true,
  })
  .option("-d, --debug", "Enable debug output.")
  // .option("-k, --key <key:string>", "Set OpenAI API key.")
  // .option("-l, --log-level <level:log-level>", "Set log level.", {
  //   default: "info",
  // })
  .arguments("<prompt:string>")
  // .arguments("<input:string> [output:string]")
  .action(async function (options, ...args) {
    if (options.debug) {
      console.log(system("Debug mode enabled."));
      console.log({ options });
      console.log(system("End debug mode."));
    }
    async function pingGPT3(
      prompt: string,
      openaiApiKey: string,
      gpt3options: Object
    ) {
      if (options.debug) console.log("log pingGPT3", { prompt });
      const res = await fetch("https://api.openai.com/v1/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${openaiApiKey}',
        },
        body: JSON.stringify({
          prompt: prompt,
          // defaults
          model: "text-davinci-002",
          max_tokens: 256,
          temperature: 0.3,
          top_p: 0.9,
          n: 1,
          frequency_penalty: 0,
          presence_penalty: 0,
          stop: ["'``output"],
          // override defaults
          ...gpt3options,
        }),
      });
      var x = await res.json();
      x = x.choices[0].text.trim();
      // https://replit.com/@amasad/gptpy?v=1#main.py
      if (options.debug) {
        console.log("------GPT3 response------------");
        console.log(x);
        console.log("------GPT3 response------------");
      }
      if (x.startsWith("```javascript")) {
        const code = x.slice(13, -3);
        console.log("------Executing...------------");
        console.log(code);
        console.log("------Done!-------------------");
        // https://stackoverflow.com/questions/46417440/how-to-get-console-log-output-from-eval
        const str = `
        (function() {
          console.oldLog = console.log;
          var output = "";
          console.log = function(value){
              output += value
          };
          ${code}
          console.log = console.oldLog;
          return output.trim();
        }())
        ";
        var result = eval(str);
        x = "Eval Answer: ${result}';
        // var response = await exec(code, {output: OutputMode.Capture});
      }
      return x;
    }
    basePrompt = args[0];
    var promptStack = [] as Augmentor[];
    var nextPrompt = null as Augmentor | null;
    function compilePrompt(pStack: Augmentor[], candidate: Augmentor) {
      var result = "";
      result += candidate.prefix ?? "";
      for (var augmentor of pStack) {
        result += augmentor.prefix ?? "";
      }
      result += basePrompt;
      for (var augmentor of pStack) {
        result += augmentor.postfix ?? "";
      }
      result += candidate.postfix ?? "";
      return result;
    }

    console.log(currentPrompt(basePrompt));
    while (true) {
      if (options.debug) {
        console.log("start cycle", { promptStack, nextPrompt });
      }
      nextPrompt = nextPrompt ?? { postfix: "" };
      var answer = await pingGPT3(
        compilePrompt(promptStack, nextPrompt),
        options.openaiApiKey,
        {}
      );
      if (options.debug) console.log("log1", { answer });
      if (answer === "") {
        console.log(
          system(
            "GPT3 returned an empty string. We reached a stop sequence. Pop the stack or Ctrl+C exit."
          )
        );
      } else {
        console.log(showNext("GPT3 response: "));
        console.log(answer);
      }
      console.log("\n ---------- \n");
      var choices: string[] = await Checkbox.prompt({
        message: "What do you want to do with this response?",
        options: [
          Checkbox.separator("---Run Prompt candidates in Parallel!-----"),
          { name: "Display progress so far", value: "$display" },
          { name: "Rewrite current prompt", value: "$rewrite" },
          ...Object.entries(promptAugmentors).map(([augName, augData]) => {
            return { name: 'Add "${augName.trim()}"`, value: augName };
          }),
          Checkbox.separator(
            "---Interrupts (choosing one of these overrides all others). Use Ctrl+C to exit-----"
          ),
          { name: "Pop previous candidate off prompt stack", value: "$back" },
          {
            name: "Add to prompt stack, get GPT3 to continue",
            value: "$continue",
          },
        ],
      });
      if (choices.length === 0) {
        continue;
      }
      if (choices.includes("$display")) {
        console.log(system("---- Prompt Progress: ----"));
        console.log(currentPrompt(basePrompt));
        console.log(showNext("prompt Stack:"));
        console.log(promptStack.join("\n"));
        console.log(showNext("current candidate:"));
        console.log(JSON.stringify(nextPrompt));
        console.log(system("---- End of Progress Print ----"));
        console.log(" ");
      }
      if (choices.includes("$back")) {
        if (promptStack.length > 1) {
          nextPrompt = promptStack.pop() || {};
          continue; // next iteration
        } else {
          console.log(system("Can't go back any further."));
          continue; // next iteration
        }
      }
      if (choices.includes("$continue")) {
        promptStack.push(nextPrompt);
        continue;
      }

      // run searches in parallel from here
      const values = await Promise.all(
        choices.map(async (choice) => {
          let value;
          let rewriteMsg = "";
          let augData = {} as Augmentor;
          if (choice === "$rewrite") {
            console.log(system(`[extra info needed for rewriting prompt]`));
            rewriteMsg = await Input.prompt({
              message:
                "What do you want to rewrite the prompt to? (press up for suggestion)",
              minLength: 1,
              // info: true,
              suggestions: [answer],
            });
            augData = { postfix: rewriteMsg } as Augmentor;
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          } else if (choice in promptAugmentors) {
            augData = promptAugmentors[choice as keyof typeof promptAugmentors];
            value = await pingGPT3(
              compilePrompt(promptStack, augData),
              options.openaiApiKey,
              {}
            );
          }
          return {
            name: choice === "$rewrite" ? rewriteMsg : choice,
            value: value,
            augData,
          };
        })
      );
      if (values.length === 1) {
        // just immediately print out the value and carry on
        if (options.debug) console.log("log2", { values });
        if (values[0].value === "") {
          console.log(
            showNext(
              "Null response from GPT3. We may have reached a natural stop sequence. Pop the stack or Ctrl+C to exit."
            )
          );
        }
        console.log(currentPrompt(values[0].value));
        nextPrompt = values[0].augData;
      } else {
        values.push({
          name: "accept current candidate without rewrite",
          value: answer,
          augData: { postfix: answer },
        });
        if (options.debug) console.log("table", { values });
        // var table: Table =
        new Table()
          .header(["Candidate", "GPT3 Response"])
          .body(values.map(({ value, name }) => [name, value]))
          .padding(1)
          .indent(2)
          .maxColWidth(60)
          .border(true)
          .render();

        const selectedCandidate = await Select.prompt({
          message: "Pick a candidate you like to add onto the prompt stack.",
          options: values,
        });
        console.log(showNext(selectedCandidate));
        if (options.debug) console.log("log3", { selectedCandidate });
        nextPrompt = values.find((x) => x.value === selectedCandidate)!.augData;
      }
    }
  })
  // // Child command 1.
  // .command("clear", "Foo sub-command.")
  // .option("-f, --foo", "Foo option.")
  // // .arguments("<value:string>")
  // .action((options, ...args) => localStorage.clear())
  .parse(Deno.args);


