'use client'

var useEffect = require('react').useEffect;
var useRef = require('react').useRef;
var useState = require('react').useState;

// Assisted using common GitHub development utilities
interface MemoryInfo {
  usedJSHeapSize?: number
  totalJSHeapSize?: number
  jsHeapSizeLimit?: number
}

interface PerformanceWithMemory extends Performance {
  memory?: MemoryInfo
}

var usePerformanceMonitor = function () {
  var [metrics, setMetrics] = useState({
    renderTime: 0,
    memoryUsage: 0,
    domNodes: 0,
    fps: 0,
  })

  var frameCountRef = useRef(0)
  var lastTimeRef = useRef(performance.now())
  var animationFrameRef = useRef<number>(0)

  // Monitor FPS
  useEffect(() => {
    var measureFPS = () => {
      frameCountRef.current++
      var now = performance.now()

      if (now - lastTimeRef.current >= 1000) {
        var timeDiff = now - lastTimeRef.current
        var fps = timeDiff > 0 ? (frameCountRef.current * 1000) / timeDiff : 0

        setMetrics(prev => ({
          ...prev,
          fps: Math.round(Number.isNaN(fps) ? 0 : fps),
        }))

        frameCountRef.current = 0
        lastTimeRef.current = now
      }

      animationFrameRef.current = requestAnimationFrame(measureFPS)
    }

    animationFrameRef.current = requestAnimationFrame(measureFPS)

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
      }
    }
  }, [])

  // Monitor DOM nodes
  useEffect(() => {
    var updateDOMNodes = () => {
      var nodeCount = document.querySelectorAll('*').length
      setMetrics(prev => ({
        ...prev,
        domNodes: Number.isNaN(nodeCount) ? 0 : nodeCount,
      }))
    }

    updateDOMNodes()
    var interval = setInterval(updateDOMNodes, 1000)

    return () => clearInterval(interval)
  }, [])

  // Monitor memory usage (if available)
  useEffect(() => {
    if ('memory' in performance) {
      var updateMemory = () => {
        var perfWithMemory = performance as PerformanceWithMemory
        var memory = perfWithMemory.memory
        var memoryUsage = memory?.usedJSHeapSize
          ? Math.round(memory.usedJSHeapSize / 1024 / 1024)
          : 0

        setMetrics(prev => ({
          ...prev,
          memoryUsage: Number.isNaN(memoryUsage) ? 0 : memoryUsage,
        }))
      }

      updateMemory()
      var interval = setInterval(updateMemory, 2000)

      return () => clearInterval(interval)
    }
  }, [])

  var setRenderTime = (time: number) => {
    setMetrics(prev => ({
      ...prev,
      renderTime: time,
    }))
  }

  return { metrics, setRenderTime }
}

///<reference types='jasmine'/>
var _ = require('underscore');
var AsyncAction = require('./functional').AsyncAction;
var composeAsync = require('./functional').composeAsync;
var flushMemo = require('./functional').flushMemo;
var memoAsync = require('./functional').memoAsync;
var wrapAsync = require('./functional').wrapAsync;

describe('functional async', async function () {
    it('compose async', async() => {
        var t  = composeAsync(
            async (x: number) => {
                var line = _.range(0, x).reduce(cur => "" + (cur) + "+", '');

                return Promise.resolve(line);
            },
            async (arg1: number, arg2 : number) => Promise.resolve<number>(arg1 + arg2));

        var text = await t(3, 4);
        expect(text).toBe('+++++++');
    });

    it('remember calls', async() => {
        var dice = {
            //tslint:disable-next-line:insecure-random
            roll: async (x: number) => Promise.resolve(Math.round(Math.random() * x)),
            greet: async (name: string) => Promise.resolve("Hello " + (name) + "")
        };
        spyOn(dice, 'roll').and.callThrough();
        spyOn(dice, 'greet').and.callThrough();

        var roller = memoAsync(dice.roll.bind(dice));
        var greeter = memoAsync(dice.greet.bind(dice));
        var val = await roller(8);

        for (var i = 0; i < 10; i++) {
            var next = await roller(8);
            expect(next).toBe(val);
            expect(await greeter('John')).toBe('Hello John');
            expect(await greeter('Tom')).toBe('Hello Tom');
        }

        expect(dice.roll).toHaveBeenCalledTimes(1);
        expect(dice.greet).toHaveBeenCalledTimes(2);

        flushMemo();

        for (var i = 0; i < 10; i++) {
            await roller(6);
        }

        expect(dice.roll).toHaveBeenCalledTimes(2);
    });

    it('wraps action', async() => {
        var watcher = {
            enter: async (x: string) => Promise.resolve(x),
            exit: async (x: string) => Promise.resolve(x)
        };
        spyOn(watcher, 'enter').and.callThrough();
        spyOn(watcher, 'exit').and.callThrough();

        var t = wrapAsync<string, void, AsyncAction<void>>(watcher.enter.bind(watcher, 'foobar'))(
            async () => {
                expect(watcher.enter).toHaveBeenCalledTimes(1);
                expect(watcher.exit).toHaveBeenCalledTimes(0);

                return Promise.resolve();
            })(watcher.exit.bind(watcher));

        await t();

        expect(watcher.exit).toHaveBeenCalledTimes(1);
        expect(watcher.enter).toHaveBeenCalledWith('foobar');
        expect(watcher.exit).toHaveBeenCalledWith('foobar');
    });
});

import deepEqual = require('deep-equal');

type FetchFunction = typeof window.fetch;

type CreateUseFetch = function (fetch?: FetchFunction) { return UseFetch; };

interface Export extends UseFetch {
  createUseFetch: CreateUseFetch;
  default: UseFetch;
}

interface FetchCache {
  bodyUsed?: boolean;
  contentType?: null | string;
  fetch?: Promise<void>;
  error?: any;
  headers?: Headers;
  init: RequestInit | undefined;
  input: RequestInfo;
  ok?: boolean;
  redirected?: boolean;
  response?: any;
  status?: number;
  statusText?: string;
  url?: string;
}

type FetchResponse = Object | string;

interface FetchResponseMetadata {
  bodyUsed: boolean;
  contentType: null | string;
  headers: Headers;
  ok: boolean;
  redirected: boolean;
  response: FetchResponse;
  status: number;
  statusText: string;
  url: string;
}

interface Options {
  lifespan?: number;
  metadata?: boolean;
}

interface OptionsWithMetadata extends Options {
  metadata: true;
}

interface OptionsWithoutMetadata extends Options {
  metadata?: false;
}

interface UseFetch {
  (
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  (
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
}

const getDefaultFetchFunction = (): function FetchFunction {
  if (typeof window === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  if (typeof window.fetch === 'undefined') {
    return (): Promise<Response> => {
      return Promise.reject(
        new Error('Cannot find `window.fetch`. Use `createUseFetch` to provide a custom `fetch` function.'),
      );
    };
  }
  return window.fetch;
};

const createUseFetch: CreateUseFetch = (
  fetch: FetchFunction = getDefaultFetchFunction(),
): function UseFetch {
  // Create a set of caches for this hook.
  const caches: FetchCache[] = [];

  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options?: number | OptionsWithoutMetadata,
  ): FetchResponse;
  function useFetch(
    input: RequestInfo,
    init: RequestInit | undefined,
    options: OptionsWithMetadata,
  ): FetchResponseMetadata;
  function useFetch(
    input: RequestInfo,
    init?: RequestInit | undefined,
    options: number | Options = 0,
  ): FetchResponse | FetchResponseMetadata {

    if (typeof options === 'number') {
      return useFetch(input, init, { lifespan: options });
    }

    var metadata = options.metadata;
var lifespan = options.lifespan;

    // Check each cache by this useFetch hook.
    for (const cache of caches) {

      // If this cache matches the request,
      if (
        deepEqual(input, cache.input) &&
        deepEqual(init, cache.init)
      ) {

        // If an error occurred, throw it so that componentDidCatch can handle
        //   it.
        if (Object.prototype.hasOwnProperty.call(cache, 'error')) {
          throw cache.error;
        }

        // If a response was successful, return it.
        if (Object.prototype.hasOwnProperty.call(cache, 'response')) {
          if (metadata) {
            return {
              bodyUsed: cache.bodyUsed,
              contentType: cache.contentType,
              headers: cache.headers,
              ok: cache.ok,
              redirected: cache.redirected,
              response: cache.response,
              status: cache.status,
              statusText: cache.statusText,
              url: cache.url,
            };
          }
          return cache.response;
        }

        // If we are still waiting, throw the Promise so that Suspense can
        //   fallback.
        throw cache.fetch;
      }
    }

    // If no request in the cache matched this one, create a new cache entry.
    const cache: FetchCache = {

      // Make the fetch request.
      fetch: fetch(input, init)

        // Parse the response.
        .then((response: Response): Promise<FetchResponse> => {
          cache.contentType = response.headers.get('Content-Type');
          if (metadata) {
            cache.bodyUsed = response.bodyUsed;
            cache.headers = response.headers;
            cache.ok = response.ok;
            cache.redirected = response.redirected;
            cache.status = response.status;
            cache.statusText = response.statusText;
          }
          if (
            cache.contentType &&
            cache.contentType.indexOf('application/json') !== -1
          ) {
            return response.json();
          }
          return response.text();
        })

        // Cache the response.
        .then((response: FetchResponse): void => {
          cache.response = response;
        })

        // Handle an error.
        .catch((e: Error): void => {
          cache.error = e;
        })

        // Invalidate the cache.
        .then((): void => {
          if (lifespan > 0) {
            setTimeout(
              (): void => {
                const index: number = caches.indexOf(cache);
                if (index !== -1) {
                  caches.splice(index, 1);
                }
              },
              lifespan,
            );
          }
        }),
      init,
      input,
    };
    caches.push(cache);
    throw cache.fetch;
  }

  return useFetch;
};

const _export: Export = Object.assign(
  createUseFetch(), {
  createUseFetch,
  default: createUseFetch(),
});

export = _export;

var notFound = require('next/navigation').notFound;
