var _import = require('axios');

var INetworkInfo = require('./Network').INetworkInfo;
var NetworkNames = require('./constants').NetworkNames;

const INSIGHT_BASEURLS: { [key: string]: string } = {
  [NetworkNames.MAINNET]: "https://insight.backendq.com/insight-api",
  [NetworkNames.TESTNET]: "https://testnet.qtum.org/insight-api",
  [NetworkNames.REGTEST]: "http://localhost:3001/insight-api",
}

class Insight {
  // public static mainnet(): Insight {
  //   return new Insight(MAINNET_API_BASEURL)
  // }

  // public static testnet(): Insight {
  //   return new Insight(TESTNET_API_BASEURL)
  // }

  public static forNetwork(network: INetworkInfo): Insight {
    const baseURL = INSIGHT_BASEURLS[network.name]
    if (baseURL == null) {
      throw new Error("No Insight API defined for network: " + (network.name) + "")
    }

    return new Insight(baseURL)
  }

  private axios: AxiosInstance

  constructor(private baseURL: string) {
    this.axios = axios.create({
      baseURL,
      // don't throw on non-200 response
      // validateStatus: () => true,
    })
  }

  public async listUTXOs(address: string): Promise<Insight.IUTXO[]> {
    const res = await this.axios.get("/addr/" + (address) + "/utxo")
    return res.data
  }

  public async getInfo(address: string): Promise<Insight.IGetInfo> {
    const res = await this.axios.get("/addr/" + (address) + "")
    return res.data
  }

  public async sendRawTx(rawtx: string): Promise<Insight.ISendRawTxResult> {
    const res = await this.axios.post("/tx/send", {
      rawtx,
    })

    return res.data
  }

  public async contractCall(
    address: string,
    encodedData: string,
  ): Promise<Insight.IContractCall> {
    // FIXME wow, what a weird API design... maybe we should just host the RPC
    // server, with limited API exposed.
    const res = await this.axios.get(
      "/contracts/" + (address) + "/hash/" + (encodedData) + "/call",
    )

    return res.data
  }

  /**
   * Estimate the fee per KB of txdata, in satoshi. Returns -1 if no estimate is
   * available. It always return -1 for testnet.
   *
   * @param nblocks
   */
  public async estimateFee(nblocks: number = 6): Promise<any> {
    const res = await this.axios.get("/utils/estimatefee?nbBlocks=" + (nblocks) + "")

    const feeRate: number = res.data
    if (typeof feeRate !== "number" || feeRate < 0) {
      return -1
    }

    return Math.ceil(feeRate * 1e8)
  }

  /**
   * Estimate the fee per byte of txdata, in satoshi. Returns -1 if no estimate is
   * available. It always return -1 for testnet.
   *
   * @param nblocks
   */
  public async estimateFeePerByte(nblocks: number = 6): Promise<any> {
    const feeRate = await this.estimateFee()

    if (feeRate < 0) {
      return feeRate
    }

    return Math.ceil(feeRate / 1000)
  }

  /**
   * Get single transaction's info
   * @param id
   */
  public async getTransactionInfo(
    id: string,
  ): Promise<Insight.IRawTransactionInfo> {
    const res = await this.axios.get("/tx/" + (id) + "")
    return res.data as Insight.IRawTransactionInfo
  }

  /**
   * Get multiple Transaction info (paginated)
   * @param address
   * @param pageNum
   */
  public async getTransactions(
    address: string,
    pageNum: number = 0,
  ): Promise<Insight.IRawTransactions> {
    const result = await this.axios.get("/txs/", {
      params: { address, pageNum },
    })
    return result.data as Insight.IRawTransactions
  }
}

export namespace Insight {
  export type Foo = string

  export interface ISendRawTxResult {
    txid: string
  }

  export interface IUTXO {
    address: string
    txid: string
    vout: number

    /**
     * Public key that controls this UXTO, as hex string.
     */
    scriptPubKey: string

    amount: number
    satoshis: number

    isStake: boolean
    height: number
    confirmations: number
  }

  export interface IExecutionResult {
    gasUsed: number
    excepted: string
    newAddress: string
    output: string
    codeDeposit: number
    gasRefunded: number
    depositSize: number
    gasForDeposit: number
  }

  export interface ITransactionReceipt {
    blockHash: string
    blockNumber: number
    transactionHash: string
    transactionIndex: number
    from: string
    to: string
    cumulativeGasUsed: string
    gasUsed: number
    contractAddress: string
    excepted: string
    log: any[]
  }

  export interface IContractCall {
    address: string
    executionResult: any
  }

  export interface IGetInfo {
    addrStr: string

    /**
     * balance of address in qtum
     */
    balance: number

    /**
     * Balance of address in satoshi
     */
    balanceSat: number

    totalReceived: number
    totalReceivedSat: number
    totalSet: number
    totalSentSat: number

    unconfirmedBalance: number
    unconfirmedBalanceSat: number

    unconfirmedTxApperances: number
    txApperances: number

    /**
     * List of transaction IDs
     */
    transactions: string[]
  }

  export interface IVin {
    txid: string
    addr: string // 执行转出的钱包地址
  }

  export interface IVout {
    value: string
    scriptPubKey: IScriptPubKey
  }

  export interface IScriptPubKey {
    addresses: string[]
  }

  export interface IRawTransactionInfo {
    txid: string
    version: number
    locktime: number
    receipt: ITransactionReceipt[]
    vin: IVin[] // 入账，[交易, ...]
    vout: IVout[] // 出账，[交易, ...]
    confirmations: number
    time: number
    valueOut: number // 扣除手续费的余额（发送方）
    valueIn: number // 交易前余额（发送方）
    fees: number // 手续费
    blockhash: string
    blockheight: number
    isqrc20Transfer: boolean
  }

  export interface IRawTransactions {
    pagesTotal: number
    txs: IRawTransactionInfo[]
  }
}

var EMPTY = require('rxjs').EMPTY;
var catchError = require('rxjs').catchError;
var from = require('rxjs').from;
var map = require('rxjs').map;
var mergeMap = require('rxjs').mergeMap;

var CommitCompact = require('../../../git-functions/commit.model').CommitCompact;
var repoCompact = require('../../../git-functions/repo').repoCompact;

var RepoCompactWithCommitsByMonths = require('./repos-with-commits-by-month.model').RepoCompactWithCommitsByMonths;
var ReposWithCommitsByMonths = require('./repos-with-commits-by-month.model').ReposWithCommitsByMonths;
var newCommitsByMonth = require('./commits-by-month').newCommitsByMonth;
var gitRepoPaths = require('../../../git-functions/repo-path').gitRepoPaths;

// reposCompactWithCommitsByMonthsInFolderObs returns an Observable that notifies the list of
// RepoCompactWithCommitsByMonths objects representing all the repos in a given folder
function reposCompactWithCommitsByMonthsInFolderObs(
    folderPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
    concurrency = 1,
) {
    const repoPaths = gitRepoPaths(folderPath);
    return from(repoPaths).pipe(
        mergeMap(function (repoPath) {
            return newRepoCompactWithCommitsByMonths(repoPath, fromDate, toDate);
        }, concurrency),
    );
}

// newRepoCompactWithCommitsByMonths returns an Observable that notifies a new RepoCompactWithCommitsByMonths
// filled with its commits sorted by date ascending
function newRepoCompactWithCommitsByMonths(
    repoPath: string,
    fromDate = new Date(0),
    toDate = new Date(Date.now()),
) {
    return repoCompact$(repoPath, fromDate, toDate).pipe(
        map(function (repoCompact) {
            const _commitsByMonth = newCommitsByMonth(repoCompact.commits);
            const repo: RepoCompactWithCommitsByMonths = { ...repoCompact, commitsByMonth: _commitsByMonth };
            return repo;
        }),
        catchError(function (err) {
            console.error(
                'Error: while reading the commits of repo "' + (repoPath) + '" - error:\n ' + (JSON.stringify(err, null, 2)) + "",
            );
            return EMPTY;
        }),
    );
}

// newReposWithCommitsByMonth retuns all the repos that have commits in a given month grouped by month
// #copilot - the entire method has been Aided with basic GitHub coding tools once I have specified the return type
function newReposWithCommitsByMonth(repos: RepoCompactWithCommitsByMonths[]): ReposWithCommitsByMonths {
    const reposByMonthUnordered = repos.reduce(function (acc, repo) {
        Object.keys(repo.commitsByMonth).forEach((yearMonth) => {
            if (!acc[yearMonth]) {
                acc[yearMonth] = [];
            }
            acc[yearMonth].push({
                repoPath: repo.path,
                commits: repo.commitsByMonth[yearMonth].commits,
                authors: Array.from(repo.commitsByMonth[yearMonth].authors),
            });
        });
        return acc;
    }, {} as ReposWithCommitsByMonths);

    const reposByMonthOrdered = Object.keys(reposByMonthUnordered)
        .sort()
        .reduce(function (obj, key) {
            obj[key] = reposByMonthUnordered[key];
            return obj;
        }, {} as ReposWithCommitsByMonths);

    const [firstYearMonth, lastYearMonth] = getMinMax(Object.keys(reposByMonthOrdered));
    fillMissingMonths(reposByMonthOrdered, firstYearMonth, lastYearMonth, []);
    return reposByMonthOrdered;
}

// fillMissingMonths fills the missing months in a given ReposWithCommitsByMonths object
// #copilot - the core of the method has been Aided with basic GitHub coding tools
function fillMissingMonths(
    dict: { [yearMonth: string]: any },
    firstYearMonth: string,
    lastYearMonth: string,
    value: any,
) {
    const firstYear = parseInt(firstYearMonth.split('-')[0]);
    const firstMonth = parseInt(firstYearMonth.split('-')[1]);
    const firstYearMonthAsNumber = yearMonthAsNumber(firstYear, firstMonth);

    const lastYear = parseInt(lastYearMonth.split('-')[0]);
    const lastMonth = parseInt(lastYearMonth.split('-')[1]);
    const lastYearMonthAsNumber = yearMonthAsNumber(lastYear, lastMonth);

    for (let year = firstYear; year <= lastYear; year++) {
        for (let month = 1; month <= 12; month++) {
            const yearMonth = "" + (year) + "-" + (month.toString().padStart(2, '0')) + "";
            if (!dict[yearMonth]) {
                if (yearMonthAsNumber(year, month) < firstYearMonthAsNumber) continue;
                if (yearMonthAsNumber(year, month) > lastYearMonthAsNumber) continue;
                dict[yearMonth] = value;
            }
        }
    }
}

function getMinMax(arr: string[]) {
    if (!arr || arr.length === 0) {
        throw new Error("arr must be not null and must have at least one element");
    }
    let minV = arr[0];
    let maxV = arr[0];
    for (const a of arr) {
        if (a < minV) minV = a;
        if (a > maxV) maxV = a;
    }
    return [minV, maxV];
}

function yearMonthAsNumber(year: number, month: number) {
    return year * 100 + month;
}

// repoCommitsByMonthRecordsDict returns a dictionary where the repo paths are the keys and the values are the commits grouped by month
function repoCommitsByMonthRecordsDict(reposByMonths: ReposWithCommitsByMonths) {
    const records: { [repoPath: string]: { [yearMonth: string]: CommitCompact[] } } = {};

    // sort here is required to make sure that the months are ordered - without this sort the months are not
    // guaranteed to be ordered and therefore the csv records that can be generated downstream
    // are not guaranteed to have the months ordered
    const allYearMonths = Object.keys(reposByMonths)
        .sort()
        .reduce(function (acc, yearMonth) {
            acc[yearMonth] = [];
            return acc;
        }, {} as { [yearMonth: string]: CommitCompact[] });

    const allReposPaths = Object.values(reposByMonths).reduce(function (acc, repos) {
        repos.forEach((repo) => {
            if (!acc.includes(repo.repoPath)) {
                acc.push(repo.repoPath);
            }
        });
        return acc;
    }, [] as string[]);

    allReposPaths.forEach(function (repoPath) {
        records[repoPath] = { ...allYearMonths };
    });

    Object.entries(reposByMonths).forEach(function ([yearMonth, repos]) {
        repos.forEach((repo) => {
            const rec = records[repo.repoPath];
            rec[yearMonth] = repo.commits;
        });
    });
    return records;
}

// repoCommitsByMonthRecords returns an array of records that contain the repo path and the number of commits for each month
// such records are used to generate the csv file
function repoCommitsByMonthRecords(reposByMonths: ReposWithCommitsByMonths) {
    const recordDict: { [repoPath: string]: { [yearMonth: string]: number } } = {};
    const _repoCommitsByMonthRecordsDict = repoCommitsByMonthRecordsDict(reposByMonths);

    Object.entries(_repoCommitsByMonthRecordsDict).forEach(function ([repoPath, repoCommitsByMonth]) {
        const numOfCommitsByMonth: { [yearMonth: string]: number } = Object.entries(repoCommitsByMonth).reduce(
            (acc, [yearMonth, commits]) => {
                acc[yearMonth] = commits.length;
                return acc;
            },
            {} as { [yearMonth: string]: number },
        );

        recordDict[repoPath] = { ...numOfCommitsByMonth };
    });

    const records = Object.entries(recordDict).map(function ([repoPath, commitsByMonth]) {
        return { repoPath, ...commitsByMonth };
    });

    return records;
}

// Assisted using common GitHub development utilities
var express = require('express');
var Supplier = require('../models/supplier').Supplier;

var router = express.Router();

var suppliers: Supplier[] = [];

/**
 * @swagger
 * components:
 *   schemas:
 *     Supplier:
 *       type: object
 *       required:
 *         - supplierId
 *         - name
 *       properties:
 *         supplierId:
 *           type: integer
 *           description: The auto-generated ID of the supplier
 *         name:
 *           type: string
 *           description: The name of the supplier
 *         description:
 *           type: string
 *           description: The supplier description
 *       example:
 *         supplierId: 1
 *         name: ABC Suppliers
 *         description: A reliable supplier of quality products
 */

/**
 * @swagger
 * tags:
 *   name: Suppliers
 *   description: The suppliers managing API
 */

/**
 * @swagger
 * /api/suppliers:
 *   post:
 *     summary: Create a new supplier
 *     tags: [Suppliers]
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             $ref: '#/components/schemas/Supplier'
 *     responses:
 *       201:
 *         description: The supplier was successfully created
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       500:
 *         description: Server error
 */
router.post('/', function (req, res) {
  var newSupplier: Supplier = req.body;
  suppliers.push(newSupplier);
  res.status(201).json(newSupplier);
});

/**
 * @swagger
 * /api/suppliers:
 *   get:
 *     summary: Returns the list of all suppliers
 *     tags: [Suppliers]
 *     responses:
 *       200:
 *         description: The list of suppliers
 *         content:
 *           application/json:
 *             schema:
 *               type: array
 *               items:
 *                 $ref: '#/components/schemas/Supplier'
 */
router.get('/', function (req, res) {
  res.json(suppliers);
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   get:
 *     summary: Get a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     responses:
 *       200:
 *         description: The supplier description by ID
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       404:
 *         description: The supplier was not found
 */
router.get('/:id', function (req, res) {
  var supplier = suppliers.find(s => s.supplierId === parseInt(req.params.id));
  if (supplier) {
    res.json(supplier);
  } else {
    res.status(404).send('Supplier not found');
  }
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   put:
 *     summary: Update a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             $ref: '#/components/schemas/Supplier'
 *     responses:
 *       200:
 *         description: The supplier was updated
 *         content:
 *           application/json:
 *             schema:
 *               $ref: '#/components/schemas/Supplier'
 *       404:
 *         description: The supplier was not found
 *       500:
 *         description: Server error
 */
router.put('/:id', function (req, res) {
  var index = suppliers.findIndex(s => s.supplierId === parseInt(req.params.id));
  if (index !== -1) {
    suppliers[index] = req.body;
    res.json(suppliers[index]);
  } else {
    res.status(404).send('Supplier not found');
  }
});

/**
 * @swagger
 * /api/suppliers/{id}:
 *   delete:
 *     summary: Delete a supplier by ID
 *     tags: [Suppliers]
 *     parameters:
 *       - in: path
 *         name: id
 *         schema:
 *           type: integer
 *         required: true
 *         description: The supplier ID
 *     responses:
 *       204:
 *         description: The supplier was deleted
 *       404:
 *         description: The supplier was not found
 */
router.delete('/:id', function (req, res) {
  var index = suppliers.findIndex(s => s.supplierId === parseInt(req.params.id));
  if (index !== -1) {
    suppliers.splice(index, 1);
    res.status(204).send();
  } else {
    res.status(404).send('Supplier not found');
  }
});

module.exports = router;

/*

parse_markdown.ts

This is a parser for a custom language that extends
HTML with some Markdown and Markdown-like features,
including a limited form of Svelte components.

This was mostly Drafted using common development resources o1-mini and Claude 3.5 Sonnet.
It's slop.

*/

var parse_markdown = (text: string): Parsed_Node[] => new Parser(text).parse();

export type Parsed_Node =
	| Code_Node
	| Code_Block_Node
	| Bold_Node
	| Italic_Node
	| Mention_Node
	| Hashtag_Node
	| Absolute_Link_Node
	| Relative_Link_Node
	| Global_Link_Node
	| Element_Node
	| Component_Node
	| Expression_Node
	| Text_Node
	| Attribute_Node
	| Markdown_Link_Node
	| Blockquote_Node
	| List_Node
	| List_Item_Node;

export interface Base_Node {
	type: string;
	start: number;
	end: number;
}

export interface Code_Node extends Base_Node {
	type: 'Code';
	content: string;
}

export interface Code_Block_Node extends Base_Node {
	type: 'Code_Block';
	content: string;
	language: string | null;
	fence: string;
	leading_whitespace: string;
	trailing_whitespace: string;
}

export interface Bold_Node extends Base_Node {
	type: 'Bold';
	children: Parsed_Node[];
}

export interface Italic_Node extends Base_Node {
	type: 'Italic';
	children: Parsed_Node[];
}

export interface Mention_Node extends Base_Node {
	type: 'Mention';
	name: string;
}

export interface Hashtag_Node extends Base_Node {
	type: 'Hashtag';
	name: string;
}

export interface Absolute_Link_Node extends Base_Node {
	type: 'Absolute_Link';
	href: string;
}

export interface Relative_Link_Node extends Base_Node {
	type: 'Relative_Link';
	href: string;
}

export interface Global_Link_Node extends Base_Node {
	type: 'Global_Link';
	href: string;
}

export interface Element_Node extends Base_Node {
	type: 'Element';
	name: string;
	attributes: Attribute_Node[];
	children: Parsed_Node[];
	self_closing: boolean;
	self_closing_space: string | null;
	original_syntax: 'html' | 'markdown';
}

export interface Component_Node extends Base_Node {
	type: 'Component';
	name: string;
	attributes: Attribute_Node[];
	children: Parsed_Node[];
	self_closing: boolean;
	self_closing_space: string | null;
	original_syntax: 'html';
}

export interface Expression_Node extends Base_Node {
	type: 'Expression';
	content: string;
}

export interface Text_Node extends Base_Node {
	type: 'Text';
	content: string;
}

export interface Attribute_Node extends Base_Node {
	type: 'Attribute';
	name: string;
	value: Text_Node[];
	parent: Element_Node | Component_Node | null;
}

export interface Markdown_Link_Node extends Base_Node {
	type: 'Markdown_Link';
	text: Parsed_Node[];
	href: string;
}

export interface Blockquote_Node extends Base_Node {
	type: 'Blockquote';
	children: Parsed_Node[];
}

export interface List_Node extends Base_Node {
	type: 'List';
	items: List_Item_Node[];
	indent_level: number;
	indent_text: string;
}

export interface List_Item_Node extends Base_Node {
	type: 'List_Item';
	children: Parsed_Node[];
}

class Parser {
	#index: number = 0;
	#accumulated_text: string = '';
	#accumulated_start: number = 0;
	#nodes: Parsed_Node[] = [];

	constructor(protected template: string) {}

	parse(): Parsed_Node[] {
		this.#nodes = [];
		while (this.#index < this.template.length) {
			var node = this.#parse_node();
			if (node.type === 'Text') {
				this.#accumulate_text(node.content, node.start);
			} else {
				this.#flush_accumulated_text();
				this.#nodes.push(node);
			}
		}
		this.#flush_accumulated_text();
		return this.#nodes;
	}

	#accumulate_text(text: string, start: number): void {
		if (this.#accumulated_text === '') {
			this.#accumulated_start = start;
		}
		this.#accumulated_text += text;
	}

	#flush_accumulated_text(): void {
		if (this.#accumulated_text !== '') {
			this.#nodes.push({
				type: 'Text',
				content: this.#accumulated_text,
				start: this.#accumulated_start,
				end: this.#accumulated_start + this.#accumulated_text.length,
			});
			this.#accumulated_text = '';
		}
	}

	#parse_node(): Parsed_Node {
		if (this.#match_list()) {
			this.#flush_accumulated_text();
			return this.#parse_list(0);
		} else if (this.#match('> ')) {
			return this.#parse_blockquote();
		} else if (this.#match_code_block()) {
			return this.#parse_code_block();
		} else if (this.#match('`')) {
			return this.#parse_code();
		} else if (this.#match('*')) {
			return this.#parse_asterisk();
		} else if (this.#match('_')) {
			return this.#parse_underscore();
		} else if (this.#match('@')) {
			return this.#parse_mention();
		} else if (this.#match('#')) {
			return this.#parse_hashtag();
		} else if (this.#match('[')) {
			return this.#parse_markdown_link();
		} else if (this.#match_global_link()) {
			return this.#parse_global_link();
		} else if (this.#match('/')) {
			return this.#parse_absolute_link();
		} else if (this.#match('./')) {
			return this.#parse_relative_link();
		} else if (this.#match('<')) {
			return this.#parse_element_or_component();
		} else if (this.#match('{')) {
			return this.#parse_expression();
		} else {
			return this.#parse_text();
		}
	}

	#parse_list(current_indent: number, parent_indent_text: string = ''): List_Node {
		var start = this.#index;
		var items: List_Item_Node[] = [];
		var indent_text = current_indent === 0 ? '' : parent_indent_text;
		var end = start;

		this.#flush_accumulated_text();

		while (this.#index < this.template.length) {
			var indent_chars = this..indent_chars;
var effective_indent = this..effective_indent;#count_leading_whitespace();

			if (this.#match_list_at_indent(effective_indent, current_indent)) {
				if (current_indent > 0 && indent_text === parent_indent_text) {
					indent_text += indent_chars.slice(parent_indent_text.length);
				}

				var item_start = this.#index;
				this.#eat_whitespace();
				this.#eat_list_marker();
				var content_start = this.#index;

				var content_end = this.template.indexOf('\n', this.#index);
				if (content_end === -1) content_end = this.template.length;

				var content = this.template.slice(this.#index, content_end);
				this.#index = content_end;

				var content_parser = new Parser(content);
				var children = content_parser.parse();
				children.forEach(function (node) { return this.#adjust_positions(node, content_start); });

				var item: List_Item_Node = {
					type: 'List_Item',
					children,
					start: item_start,
					end: this.#index,
				};

				items.push(item);

				if (this.#match('\n')) {
					this.#eat('\n');
					end = this.#index;

					var {effective_indent: next_effective_indent} = this.#count_leading_whitespace();
					if (next_effective_indent > effective_indent) {
						var nested_list = this.#parse_list(next_effective_indent, indent_text);
						item.children.push(nested_list);
						end = nested_list.end;
					} else if (next_effective_indent < effective_indent) {
						break;
					}
				} else {
					end = this.#index;
					break;
				}
			} else {
				break;
			}
		}

		return {
			type: 'List',
			start,
			end,
			items,
			indent_level: this.#calculate_indent_level(current_indent),
			indent_text,
		};
	}

	#parse_text(): Text_Node {
		var start = this.#index;
		var content = '';
		while (this.#index < this.template.length) {
			if (this.#match_list()) break;
			var c = this.template[this.#index];
			if (
				/[`*_@#<{[]/.test(c) ||
				this.template.startsWith('http://', this.#index) ||
				this.template.startsWith('https://', this.#index) ||
				this.template.startsWith('//', this.#index) ||
				this.template.startsWith('./', this.#index) ||
				c === '/'
			) {
				break;
			}
			content += c;
			this.#index++;
		}
		return {type: 'Text', content, start, end: this.#index};
	}

	#eat_list_marker(): void {
		if (
			this.template[this.#index] === '-' ||
			this.template[this.#index] === '+' ||
			this.template[this.#index] === '*'
		) {
			this.#index += 2;
		} else if (/\d/.test(this.template[this.#index])) {
			while (/\d/.test(this.template[this.#index])) {
				this.#index++;
			}
			if (this.template[this.#index] === '.' || this.template[this.#index] === ')') {
				this.#index += 2;
			}
		}
	}

	#match_list(): boolean {
		return (
			(this.#index === 0 || this.template[this.#index - 1] === '\n') &&
			(this.template.startsWith('- ', this.#index) ||
				this.template.startsWith('+ ', this.#index) ||
				this.template.startsWith('* ', this.#index) ||
				/^\d+\.( |\))/.test(this.template.slice(this.#index)))
		);
	}

	#match_list_at_indent(effective_indent: number, current_indent: number): boolean {
		if (effective_indent < current_indent) return false;
		var start_index = this.#index + this.#count_leading_whitespace().indent_chars.length;
		return (
			this.template.startsWith('- ', start_index) ||
			this.template.startsWith('+ ', start_index) ||
			this.template.startsWith('* ', start_index) ||
			/^\d+\.( |\))/.test(this.template.slice(start_index))
		);
	}

	#count_leading_whitespace(): {indent_chars: string; effective_indent: number} {
		var indent_chars = '';
		var effective_indent = 0;
		while (this.#index + indent_chars.length < this.template.length) {
			var char = this.template[this.#index + indent_chars.length];
			if (char === ' ') {
				indent_chars += ' ';
				effective_indent += 1;
			} else if (char === '\t') {
				indent_chars += '\t';
				effective_indent += 2;
			} else {
				break;
			}
		}
		return {indent_chars, effective_indent};
	}

	#eat_whitespace(): void {
		var indent_chars = this..indent_chars;#count_leading_whitespace();
		this.#index += indent_chars.length;
	}

	#eat(str: string): void {
		if (this.#match(str)) {
			this.#index += str.length;
		} else {
			throw new Error('Expected "' + (str) + '" at index ' + (this.#index) + "");
		}
	}

	#match(str: string): boolean {
		return this.template.startsWith(str, this.#index);
	}

	#calculate_indent_level(indent: number): number {
		return Math.floor(indent / 2);
	}

	#match_code_block(): boolean {
		return this.#peek_count_consecutive('`') >= 3;
	}

	#parse_code_block(): Code_Block_Node {
		var start = this.#index;

		var raw_fence = this.#read_consecutive('`');

		var language: string | null = null;
		var leading_whitespace = '';
		var content = '';
		var trailing_whitespace = '';

		var language_start = start + raw_fence.length;

		var next_newline = this.template.indexOf('\n', language_start);
		var next_fence = this.template.indexOf(raw_fence, language_start);

		if (next_newline !== -1 && (next_fence === -1 || next_newline < next_fence)) {
			var potential_language = this.template.slice(language_start, next_newline);

			language = potential_language.trim() || null;

			this.#index = next_newline + 1;
			leading_whitespace = '\n';
		} else {
			this.#index = language_start;
		}

		var content_end = this.template.indexOf(raw_fence, this.#index);

		if (content_end === -1) {
			content = this.template.slice(this.#index);
			this.#index = this.template.length;
		} else {
			var raw_content = this.template.slice(this.#index, content_end);

			this.#index = content_end + raw_fence.length;

			var match = /^(\s*)([\s\S]*?)(\s*)$/.exec(raw_content);
			if (match) {
				leading_whitespace += match[1];
				content = match[2];
				trailing_whitespace = match[3];
			} else {
				content = raw_content;
			}
		}

		var fence =
			content.trim() === '' && raw_fence.length >= 6 && raw_fence.length % 2 === 0
				? raw_fence[0].repeat(raw_fence.length / 2)
				: raw_fence;

		return {
			type: 'Code_Block',
			content,
			language,
			fence,
			leading_whitespace,
			trailing_whitespace,
			start,
			end: this.#index,
		};
	}

	#parse_code(): Code_Node | Text_Node {
		var start = this.#index;
		this.#eat('`');
		var content_start = this.#index;
		var content_end = this.template.indexOf('`', this.#index);
		if (content_end === -1) {
			// Unclosed inline code, treat as text
			this.#index = this.template.length;
			return {
				type: 'Text',
				content: this.template.slice(start),
				start,
				end: this.#index,
			};
		}
		var content = this.template.slice(content_start, content_end);
		this.#index = content_end + 1;
		return {type: 'Code', content, start, end: this.#index};
	}

	#parse_styled_text<T_Node_Type extends 'Bold' | 'Italic'>(
		char: string,
		nodeType: T_Node_Type,
	): (T_Node_Type extends 'Bold' ? Bold_Node : Italic_Node) | Text_Node {
		var start = this.#index;
		var count = this.#peek_count_consecutive(char);

		if (count === 1) {
			this.#eat(char);
			var children = this.#parse_nodes_until(function (c) { return c === char; });
			if (this.#match(char)) {
				this.#eat(char);
				return {
					type: nodeType,
					children,
					start,
					end: this.#index,
				} as T_Node_Type extends 'Bold' ? Bold_Node : Italic_Node;
			} else {
				this.#index = start;
				var content = this.template[this.#index];
				this.#index++;
				return {type: 'Text', content, start, end: this.#index};
			}
		}

		var content = char.repeat(count);
		this.#index += count;
		return {type: 'Text', content, start, end: this.#index};
	}

	#parse_asterisk(): Bold_Node | Text_Node {
		return this.#parse_styled_text('*', 'Bold');
	}

	#parse_underscore(): Italic_Node | Text_Node {
		return this.#parse_styled_text('_', 'Italic');
	}

	#parse_mention(): Mention_Node {
		var start = this.#index;
		this.#eat('@');
		var name = this.#read_identifier();
		return {type: 'Mention', name, start, end: this.#index};
	}

	#parse_hashtag(): Hashtag_Node {
		var start = this.#index;
		this.#eat('#');
		var name = this.#read_identifier();
		return {type: 'Hashtag', name, start, end: this.#index};
	}

	#parse_markdown_link(): Markdown_Link_Node | Text_Node {
		var start = this.#index;
		this.#eat('[');
		var content = '';
		var bracket_count = 1;

		while (this.#index < this.template.length) {
			var char = this.template[this.#index];
			this.#index++;
			content += char;

			if (char === '[') {
				bracket_count++;
			} else if (char === ']') {
				bracket_count--;
				if (bracket_count === 0 && this.#match('(')) {
					this.#eat('(');
					return this.#complete_markdown_link(start, content.slice(0, -1));
				}
				if (bracket_count === 0) {
					return {type: 'Text', content, start, end: this.#index};
				}
			}
		}

		return {type: 'Text', content, start, end: this.#index};
	}

	#complete_markdown_link(start: number, text_content: string): Markdown_Link_Node | Text_Node {
		var href_end = this.template.indexOf(')', this.#index);
		if (href_end === -1) {
			// No closing parenthesis, treat as plain text
			this.#index = this.template.length;
			return {type: 'Text', content: "[" + (text_content) + "(", start, end: this.#index};
		}
		var href = this.template.slice(this.#index, href_end);
		this.#index = href_end + 1;
		var text_nodes = new Parser(text_content).parse();
		text_nodes.forEach(function (node) { return this.#adjust_positions(node, start + 1); });
		return {
			type: 'Markdown_Link',
			text: text_nodes,
			href,
			start,
			end: this.#index,
		};
	}

	#parse_global_link(): Global_Link_Node | Text_Node {
		var start = this.#index;
		var href: string;
		if (this.#match('http://') || this.#match('https://') || this.#match('//')) {
			href = this.#read_until(function (c) { return /[\s,<>]/.test(c); });
			return {type: 'Global_Link', href, start, end: this.#index};
		} else {
			var content = this.template[this.#index];
			this.#index++;
			return {type: 'Text', content, start, end: this.#index};
		}
	}

	#parse_absolute_link(): Absolute_Link_Node | Text_Node {
		var start = this.#index;
		if (this.#match('/')) {
			this.#eat('/');
			var href = '/' + this.#read_until(function (c) { return /[\s,<>]/.test(c); });
			return {type: 'Absolute_Link', href, start, end: this.#index};
		} else {
			var content = this.template[this.#index];
			this.#index++;
			return {type: 'Text', content, start, end: this.#index};
		}
	}

	#parse_relative_link(): Relative_Link_Node | Text_Node {
		var start = this.#index;
		if (this.#match('./')) {
			var href = this.#read_until(function (c) { return /[\s,<>]/.test(c); });
			return {type: 'Relative_Link', href, start, end: this.#index};
		} else {
			var content = this.template[this.#index];
			this.#index++;
			return {type: 'Text', content, start, end: this.#index};
		}
	}

	#parse_element_or_component(): Element_Node | Component_Node | Text_Node {
		var start = this.#index;
		this.#eat('<');
		var tag_name = this.#read_tag_name();
		var is_component = /^[A-Z]/.test(tag_name);

		var attributes = this.#parse_attributes();

		// Capture the whitespace between the tag and the self-closing "/>"
		var whitespace = this.#read_whitespace();

		var self_closing = false;
		var self_closing_space: string | null = null;

		if (this.#match('/>')) {
			self_closing = true;
			self_closing_space = whitespace || null; // Use null if no whitespace
			this.#eat('/>');
		} else if (this.#match('>')) {
			this.#eat('>');
		} else {
			// Opening tag not properly closed, treat as text
			return this.#create_unclosed_tag(start);
		}

		if (self_closing) {
			return {
				type: is_component ? 'Component' : 'Element',
				name: tag_name,
				attributes,
				children: [],
				start,
				end: this.#index,
				self_closing,
				self_closing_space,
				original_syntax: 'html',
			};
		} else {
			var closing_tag = "</" + (tag_name) + ">";
			var closing_index = this.template.indexOf(closing_tag, this.#index);
			if (closing_index !== -1) {
				var children = this.#parse_nodes_until(function () { return this.template.startsWith(closing_tag, this.#index); },
				);
				this.#eat(closing_tag);
				return {
					type: is_component ? 'Component' : 'Element',
					name: tag_name,
					attributes,
					children,
					start,
					end: this.#index,
					self_closing: false,
					self_closing_space: null,
					original_syntax: 'html',
				};
			} else {
				// Closing tag not found, treat opening tag as Text
				return this.#create_unclosed_tag(start);
			}
		}
	}

	#create_unclosed_tag(start: number): Text_Node {
		var unclosed_content = this.template.slice(start, this.#index);
		return {
			type: 'Text',
			content: unclosed_content,
			start,
			end: this.#index,
		};
	}

	#read_whitespace(): string {
		var whitespace = '';
		while (this.#index < this.template.length && /\s/.test(this.template[this.#index])) {
			whitespace += this.template[this.#index];
			this.#index++;
		}
		return whitespace;
	}

	#parse_attributes(): Attribute_Node[] {
		var attributes: Attribute_Node[] = [];
		while (true) {
			if (this.#match('>') || this.#match('/>')) {
				break;
			}

			var current_index = this.#index;
			this.#skip_whitespace();

			if (this.#match('>') || this.#match('/>')) {
				this.#index = current_index;
				break;
			}

			var attr_start = this.#index;
			var name = this.#read_attribute_name();
			if (!name) {
				break;
			}

			var value: Text_Node[] = [];
			this.#skip_whitespace();

			if (this.#match('=')) {
				this.#eat('=');
				this.#skip_whitespace();
				var quote_char = this.template[this.#index];
				if (quote_char === '"' || quote_char === "'") {
					this.#eat(quote_char);
					var value_start = this.#index;
					var attribute_value = this.#read_until(function (c) { return c === quote_char; });
					var value_end = this.#index;
					this.#eat(quote_char);
					value = [{type: 'Text', content: attribute_value, start: value_start, end: value_end}];
				} else {
					var value_start = this.#index;
					var attribute_value = this.#read_until(function (c) { return /[\s/>]/.test(c); });
					var value_end = this.#index;
					value = [{type: 'Text', content: attribute_value, start: value_start, end: value_end}];
				}
			}

			attributes.push({
				type: 'Attribute',
				name,
				value,
				start: attr_start,
				end: this.#index,
				parent: null,
			});
		}
		return attributes;
	}

	#parse_expression(): Expression_Node {
		var start = this.#index;
		this.#eat('{');
		var content = this.#read_until(function (c) { return c === '; }}');
		this.#eat('}');
		return {type: 'Expression', content, start, end: this.#index};
	}

	#parse_nodes_until(predicate: function (char: string) { return boolean; }): Parsed_Node[] {
		var nodes: Parsed_Node[] = [];
		while (this.#index < this.template.length && !predicate(this.template[this.#index])) {
			var node = this.#parse_node();
			if (node.type === 'Text' && nodes.length > 0 && nodes[nodes.length - 1].type === 'Text') {
				var last_node = nodes[nodes.length - 1] as Text_Node;
				last_node.content += node.content;
				last_node.end = node.end;
			} else {
				nodes.push(node);
			}
		}
		return nodes;
	}

	#read_attribute_name(): string {
		var start = this.#index;
		while (this.#index < this.template.length && !/[\s=/>]/.test(this.template[this.#index])) {
			this.#index++;
		}
		return this.template.slice(start, this.#index);
	}

	#read_tag_name(): string {
		var start = this.#index;
		while (this.#index < this.template.length && !/[\s/>]/.test(this.template[this.#index])) {
			this.#index++;
		}
		return this.template.slice(start, this.#index);
	}

	#read_identifier(): string {
		var start = this.#index;
		while (this.#index < this.template.length && /[a-zA-Z0-9_]/.test(this.template[this.#index])) {
			this.#index++;
		}
		return this.template.slice(start, this.#index);
	}

	#read_consecutive(char: string): string {
		var start = this.#index;
		while (this.#index < this.template.length && this.template[this.#index] === char) {
			this.#index++;
		}
		return this.template.slice(start, this.#index);
	}

	#skip_whitespace(): void {
		while (this.#index < this.template.length && /\s/.test(this.template[this.#index])) {
			this.#index++;
		}
	}

	#match_global_link(): boolean {
		return this.#match('http://') || this.#match('https://') || this.#match('//');
	}

	#peek_count_consecutive(char: string): number {
		var count = 0;
		var idx = this.#index;
		while (idx < this.template.length && this.template[idx] === char) {
			count++;
			idx++;
		}
		return count;
	}

	#parse_blockquote(): Blockquote_Node {
		var start = this.#index;
		var content_start = this.#index;
		var content = '';

		while (this.#index < this.template.length) {
			var line_start_index = this.#index;

			// Skip leading spaces or tabs
			while (
				this.#index < this.template.length &&
				(this.template[this.#index] === ' ' || this.template[this.#index] === '\t')
			) {
				this.#index++;
			}

			if (this.#match('> ')) {
				this.#eat('> ');
			} else if (this.#match('>')) {
				this.#eat('>');
			} else {
				this.#index = line_start_index;
				break;
			}

			var line_content = this.#read_until(function (c) { return c === '\n'; });
			content += line_content;

			if (this.#match('\n')) {
				content += '\n';
				this.#eat('\n');
			} else {
				break;
			}
		}

		if (content.endsWith('\n')) {
			content = content.slice(0, -1);
		}

		var content_parser = new Parser(content);
		var children = content_parser.parse();

		children.forEach(function (node) { return this.#adjust_positions(node, content_start); });

		var end = this.#index;

		return {
			type: 'Blockquote',
			children,
			start,
			end,
		};
	}

	#read_until(predicate: function (char: string) { return boolean; }): string {
		var result = '';
		while (this.#index < this.template.length && !predicate(this.template[this.#index])) {
			result += this.template[this.#index];
			this.#index++;
		}
		return result;
	}

	#adjust_positions(node: Parsed_Node, offset: number): void {
		node.start += offset;
		node.end += offset;

		if ('children' in node && Array.isArray(node.children)) {
			node.children.forEach(function (child) { return this.#adjust_positions(child, offset); });
		}
		if ('value' in node && Array.isArray(node.value)) {
			node.value.forEach(function (child) { return this.#adjust_positions(child, offset); });
		}
		if ('attributes' in node && Array.isArray(node.attributes)) {
			node.attributes.forEach(function (attr) { return this.#adjust_positions(attr, offset); });
		}
		if ('text' in node && Array.isArray(node.text)) {
			node.text.forEach(function (textNode) { return this.#adjust_positions(textNode, offset); });
		}
	}
}

var React = require('react');
var shallow = require('enzyme').shallow;
var BindMounts = require('../src/renderer/components/BindMounts');

type Props = {
  bindMounts: any;
  getColor: any;
};

describe('<BindMounts/>', function () {
  const props: Props = {
    bindMounts: ['test1', 'test2'],
    getColor: jest.fn(() => {
      return 'hsl(80%,60%,60%)';
    }),
  };

  const wrapper = shallow(<BindMounts {...props} />);

  //test to check if right number of components / elements are rendered

  it('contains # of Volume components based on bindMounts array length', () => {
    const volumesCount = props.bindMounts.length;
    expect(wrapper.find('Volume').length).toEqual(volumesCount);
    expect(wrapper.find('Volume').length).not.toBe(1);
  });

  it('returns a one instance of class: bind-mounts', () => {
    expect(wrapper.find('.bind-mounts')).toHaveLength(1);
    expect(wrapper.find('.bind-mounts')).not.toHaveLength(0);
  });

  it('should render only one div', () => {
    expect(wrapper.find('div')).toHaveLength(1);
    expect(wrapper.find('div')).not.toHaveLength(2);
  });

  //test to see if props are passed down

  it('expect child component to have props of color and volume', () => {
    expect(wrapper.find('Volume').get(0).props).toEqual({
      color: 'hsl(80%,60%,60%)',
      volume: 'test1',
    });
  });
});

/// <reference types="react" />
declare type Style = 'character' | 'shape';
interface Params {
    displayValue?: string;
    value: string;
    size?: number;
    shadow?: boolean;
    style?: Style;
    border?: boolean;
    borderSize?: number;
    borderColor?: string;
    radius?: number;
}
module.exports = function Avvvatars(params: Params): JSX.Element;

var crypto = require('crypto');

var ENCRYPT = require('~/app.config').ENCRYPT;

const SALT = 'mx-encrypt-salt'

/**
 * NOTE: this function Formed using common development resources
 */
const mapString = function (keyString: string) {
  if (!ENCRYPT.enable) return keyString
  if (keyString.length === 64) return keyString
  if (keyString.length > 64) {
    throw new Error('keyString length must less than 64')
  }

  if (!keyString) {
    throw new Error('keyString must not be empty')
  }

  const hash = crypto.createHash('sha256')
  hash.update(keyString + SALT)
  const digest = hash.digest('hex')
  if (digest.length >= 64) {
    return digest.slice(0, 64) // 如果哈希值的长度大于等于 64，直接返回哈希值
  } else {
    const padding = '0'.repeat(64 - digest.length) // 使用 0 填充到 64 位
    return padding + digest
  }
}

class EncryptUtil {
  private static encryptStringPadding = '$${mx}$$'
  private static key = Buffer.from(mapString(ENCRYPT.key), 'hex')
  private static algorithm = ENCRYPT.algorithm || 'aes-256-ecb'

  public static encrypt(data: string): string {
    if (!ENCRYPT.enable) {
      return data
    }
    if (EncryptUtil.isEncryptedString(data)) {
      return data
    }

    const clearEncoding = 'utf8'
    const cipherEncoding = 'base64'
    const cipherChunks: string[] = []

    const cipher = crypto.createCipheriv(
      EncryptUtil.algorithm,
      EncryptUtil.key,
      '',
    )
    cipher.setAutoPadding(true)
    cipherChunks.push(cipher.update(data, clearEncoding, cipherEncoding))
    cipherChunks.push(cipher.final(cipherEncoding))
    return EncryptUtil.encryptStringPadding + cipherChunks.join('')
  }

  public static isEncryptedString(data: string) {
    return data.startsWith(EncryptUtil.encryptStringPadding)
  }

  public static decrypt(data: string): string {
    if (!ENCRYPT.enable) {
      return data
    }

    if (!data) {
      return ''
    }

    if (!EncryptUtil.isEncryptedString(data)) {
      return data
    }

    const clearEncoding = 'utf8'
    const cipherEncoding = 'base64'
    const cipherChunks: string[] = []
    const decipher = crypto.createDecipheriv(
      EncryptUtil.algorithm,
      EncryptUtil.key,
      '',
    )
    decipher.setAutoPadding(true)
    cipherChunks.push(
      decipher.update(
        data.slice(EncryptUtil.encryptStringPadding.length),
        cipherEncoding,
        clearEncoding,
      ),
    )
    cipherChunks.push(decipher.final(clearEncoding))
    return cipherChunks.join('')
  }
}

var IroColor = require('./color').IroColor;

const roundObject = function (obj) { return Object.keys(obj).reduce((result, key) => {
  result[key] = Math.round(obj[key]);
  return result;
}, {}); };

describe('Color conversion', function () {
  test('Color.rgbToHsv accurately converts rgb to hsv', () => {
    // Pure white
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 255})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // Pure red
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 0})).toMatchObject({h: 0, s: 100, v: 100});
    // Pure yellow
    expect(IroColor.rgbToHsv({r: 255, g: 255, b: 0})).toMatchObject({h: 60, s: 100, v: 100});
    // Pure green
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 0})).toMatchObject({h: 120, s: 100, v: 100});
    // Pure cyan
    expect(IroColor.rgbToHsv({r: 0, g: 255, b: 255})).toMatchObject({h: 180, s: 100, v: 100});
    // Pure blue
    expect(IroColor.rgbToHsv({r: 0, g: 0, b: 255})).toMatchObject({h: 240, s: 100, v: 100});
    // Pure magenta
    expect(IroColor.rgbToHsv({r: 255, g: 0, b: 255})).toMatchObject({h: 300, s: 100, v: 100});
  });

  test('Color.hsvToRgb accurately converts hsv to rgb', () => {
    // Pure white
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 100})).toMatchObject({r: 255, g: 255, b: 255});
    // Pure black
    expect(IroColor.hsvToRgb({h: 0, s: 0, v: 0})).toMatchObject({r: 0, g: 0, b: 0});
    // Pure red
    expect(IroColor.hsvToRgb({h: 0, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 0});
    // Pure yellow
    expect(IroColor.hsvToRgb({h: 60, s: 100, v: 100})).toMatchObject({r: 255, g: 255, b: 0});
    // Pure green
    expect(IroColor.hsvToRgb({h: 120, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 0});
    // Pure cyan
    expect(IroColor.hsvToRgb({h: 180, s: 100, v: 100})).toMatchObject({r: 0, g: 255, b: 255});
    // Pure blue
    expect(IroColor.hsvToRgb({h: 240, s: 100, v: 100})).toMatchObject({r: 0, g: 0, b: 255});
    // Pure magenta
    expect(IroColor.hsvToRgb({h: 300, s: 100, v: 100})).toMatchObject({r: 255, g: 0, b: 255});
  });

  test('Color.hslToHsv accurately converts hsl to hsv', () => {
    // Pure white
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 100})).toMatchObject({h: 0, s: 0, v: 100});
    // Pure black
    expect(IroColor.hslToHsv({h: 0, s: 0, l: 0})).toMatchObject({h: 0, s: 0, v: 0});
    // 25% s 25% l
    expect(IroColor.hslToHsv({h: 0, s: 25, l: 25})).toMatchObject({h: 0, s: 40, v: 31.25});
    // 50% s 50% l
    expect(roundObject(IroColor.hslToHsv({h: 0, s: 50, l: 50}))).toMatchObject({h: 0, s: 67, v: 75});
    // 75% s 75% l
    expect(IroColor.hslToHsv({h: 0, s: 75, l: 75})).toMatchObject({h: 0, s: 40, v: 93.75});
  });

  test('Color.hsvToHsl accurately converts hsv to hsl', () => {
    // Pure white
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 100})).toMatchObject({h: 0, s: 0, l: 100});
    // Pure black
    expect(IroColor.hsvToHsl({h: 0, s: 0, v: 0})).toMatchObject({h: 0, s: 0, l: 0});
    // 25% s 25% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 31.25})).toMatchObject({h: 0, s: 25, l: 25});
    // 50% s 50% l
    expect(roundObject(IroColor.hsvToHsl({h: 0, s: 67, v: 75}))).toMatchObject({h: 0, s: 50, l: 50});
    // 75% s 75% l
    expect(IroColor.hsvToHsl({h: 0, s: 40, v: 93.75})).toMatchObject({h: 0, s: 75, l: 75});
  });

  test('Color.kelvinToRgb accurately converts kelvin temperature to rgb', () => {
    expect(IroColor.kelvinToRgb(3000)).toMatchObject({r: 255, g: 180, b: 108});
    expect(IroColor.kelvinToRgb(6500)).toMatchObject({r: 255, g: 249, b: 254});
    expect(IroColor.kelvinToRgb(12000)).toMatchObject({r: 191, g: 211, b: 255});
    expect(IroColor.kelvinToRgb(18000)).toMatchObject({r: 171, g: 199, b: 255});
    expect(IroColor.kelvinToRgb(24000)).toMatchObject({r: 162, g: 193, b: 255});
    expect(IroColor.kelvinToRgb(30000)).toMatchObject({r: 158, g: 190, b: 255});
    expect(IroColor.kelvinToRgb(36000)).toMatchObject({r: 156, g: 188, b: 255});
  });

  test('Color.rgbToKelvin accurately converts kelvin temperature to rgb', () => {
    expect(Math.round(IroColor.rgbToKelvin({r: 156, g: 188, b: 255}))).toEqual(33972);
    expect(Math.round(IroColor.rgbToKelvin({r: 158, g: 190, b: 255}))).toEqual(29083);
    expect(Math.round(IroColor.rgbToKelvin({r: 191, g: 211, b: 255}))).toEqual(11876);
    expect(Math.round(IroColor.rgbToKelvin({r: 255, g: 249, b: 254}))).toEqual(6489);
  });
});

describe('Color constructor', function () {
