/**
 * Configuration management for Custom Rules CLI
 */
var fs = require('fs');
var path = require('path');
var yaml = require('yaml');
var chalk = require('chalk');

export interface GlobalOptions {
  profile?: string;
  dest?: string;
  verbose?: boolean;
  config?: string;
}

export interface RuleConfig {
  name: string;
  description?: string;
  enabled: boolean;
  severity: 'error' | 'warning' | 'info';
  config?: Record<string, any>;
}

export interface ConfigSchema {
  name: string;
  version: string;
  settings: {
    output_format: string;
    verbose: boolean;
    max_workers?: number;
    backup_enabled?: boolean;
  };
  rules: RuleConfig[];
  destinations: {
    reports: string;
    logs: string;
    backups?: string;
  };
  security: {
    neverExecute: string[];
    blockedCommands: string[];
    unsafePatterns: string[];
  };
  exclusions: {
    files: string[];
    directories: string[];
    patterns: string[];
    extensions: string[];
  };
  integrations: {
    git: {
      enabled: boolean;
      hooks?: string[];
    };
    ci_cd?: {
      enabled: boolean;
    };
  };
}

class ConfigManager {
  private config: ConfigSchema;
  private profileName: string;
  private verbose: boolean;

  constructor(options: GlobalOptions = {}) {
    this.profileName = options.profile || 'default';
    this.verbose = options.verbose || false;
    this.config = this.getDefaultConfig();

    this.loadConfig(options.config);
  }

  private loadConfig(configFile?: string): void {
    var configPaths = this.getConfigPaths(configFile);

    for (var configPath of configPaths) {
      if (fs.existsSync(configPath)) {
        try {
          var content = fs.readFileSync(configPath, 'utf8');
          var loadedConfig = yaml.parse(content);

          if (loadedConfig) {
            this.config = { ...this.config, ...loadedConfig };
            if (this.verbose) {
              console.log(chalk.green("Loaded configuration from: " + (configPath) + ""));
            }
            return;
          }
        } catch (error) {
          if (this.verbose) {
            console.log(chalk.yellow("Failed to load config from " + (configPath) + ": " + (error instanceof Error ? error.message : 'Unknown error') + ""));
          }
          continue;
        }
      }
    }

    if (this.verbose) {
      console.log(chalk.yellow('Using default configuration'));
    }
  }

  private getConfigPaths(explicitConfig?: string): string[] {
    var paths: string[] = [];
    var cwd = process.cwd();
    var home = require('os').homedir();

    // Explicit config file
    if (explicitConfig) {
      paths.push(path.resolve(explicitConfig));
    }

    // Current directory
    paths.push(
      path.join(cwd, 'custom-rules.yaml'),
      path.join(cwd, 'custom-rules.yml'),
      path.join(cwd, '.custom-rules.yaml'),
      path.join(cwd, '.custom-rules.yml')
    );

    // Profile-specific configs
    var profilesDir = path.join(cwd, 'profiles');
    if (fs.existsSync(profilesDir)) {
      paths.push(
        path.join(profilesDir, "" + (this.profileName) + ".yaml"),
        path.join(profilesDir, "" + (this.profileName) + ".yml")
      );
    }

    // Home directory
    paths.push(
      path.join(home, '.config', 'custom-rules', 'config.yaml'),
      path.join(home, '.custom-rules.yaml')
    );

    return paths;
  }

  private getDefaultConfig(): ConfigSchema {
    return {
      name: this.profileName,
      version: '1.0.0',
      settings: {
        output_format: 'json',
        verbose: this.verbose,
        max_workers: 4,
        backup_enabled: true
      },
      rules: [],
      destinations: {
        reports: './reports',
        logs: './logs',
        backups: './backups'
      },
      security: {
        neverExecute: [
          'rm -rf /',
          'del /f /s /q C:\\*',
          'format c:',
          'mkfs.*',
          'sudo rm -rf',
          ':(){ :|:& };:',
          'chmod -R 777 /',
          'dd if=/dev/zero',
          'shutdown',
          'reboot',
          'halt'
        ],
        blockedCommands: [
          'curl *://*/malware*',
          'wget *://*/malware*',
          'powershell -enc*',
          'bash -c "$(curl*',
          'eval*',
          'exec*'
        ],
        unsafePatterns: [
          '\\$\\([^)]*\\)',
          '`[^`]*`',
          '\\$\\{[^}]*\\}',
          '>[>&].*',
          '\\|\\s*sh',
          '\\|\\s*bash'
        ]
      },
      exclusions: {
        files: [
          '.env',
          '.env.local',
          '.env.production',
          '*.key',
          '*.pem',
          '*.p12',
          'id_rsa',
          'id_dsa',
          'known_hosts',
          'authorized_keys'
        ],
        directories: [
          'node_modules',
          '.git',
          'dist',
          'build',
          'coverage',
          '.nyc_output',
          'tmp',
          'temp',
          '.cache'
        ],
        patterns: [
          '**/node_modules/**',
          '**/.git/**',
          '**/dist/**',
          '**/build/**',
          '**/*.log',
          '**/*.tmp',
          '**/coverage/**',
          '**/.DS_Store',
          '**/Thumbs.db'
        ],
        extensions: [
          '.exe',
          '.bat',
          '.cmd',
          '.com',
          '.scr',
          '.pif',
          '.msi',
          '.dll'
        ]
      },
      integrations: {
        git: {
          enabled: false,
          hooks: []
        },
        ci_cd: {
          enabled: false
        }
      }
    };
  }

  public get(key: string): any {
    var keys = key.split('.');
    var value: any = this.config;

    for (var k of keys) {
      if (value && typeof value === 'object' && k in value) {
        value = value[k];
      } else {
        return undefined;
      }
    }

    return value;
  }

  public set(key: string, value: any): void {
    var keys = key.split('.');
    var config: any = this.config;

    for (var i = 0; i < keys.length - 1; i++) {
      var k = keys[i];
      if (!(k in config)) {
        config[k] = {};
      }
      config = config[k];
    }

    config[keys[keys.length - 1]] = value;
  }

  public getConfig(): ConfigSchema {
    return { ...this.config };
  }

  public save(filePath?: string): void {
    var outputPath = filePath || path.join(process.cwd(), "" + (this.profileName) + ".yaml");

    try {
      // Ensure directory exists
      var dir = path.dirname(outputPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      var yamlContent = yaml.stringify(this.config);
      fs.writeFileSync(outputPath, yamlContent, 'utf8');

      if (this.verbose) {
        console.log(chalk.green("Configuration saved to: " + (outputPath) + ""));
      }
    } catch (error) {
      console.error(chalk.red("Failed to save configuration: " + (error instanceof Error ? error.message : 'Unknown error') + ""));
      throw error;
    }
  }
}

/**
 * Module Description:
 *
 * Provides functionality for sending different types of emails (verification, password reset, 2FA)
 * using the Resend email service. It includes utilities for generating HTML email content
 * and methods for sending specific email types based on predefined templates.
 */

var Resend = require('resend').Resend;

// Initialises Resend service with API key from environment variables.
var emailClient = new Resend(process.env.RESEND_API_KEY);

// Domain for email links.
var domain = process.env.NEXT_PUBLIC_URL;

/**
 * Sends an email with the provided content.
 */
async function sendEmail(email: string, subject: string, htmlContent: string) {
  await emailClient.emails.send({
    from: "no-reply@savin-it.co.uk",
    to: email,
    subject,
    html: htmlContent,
  });
}

/**
 * Generates HTML content for emails based on template parameters.
 *
 * Email template Supported by standard GitHub tools then further altered to fit project's needs.
 */
function generateEmailHtml(templateParams: {
  header: string;
  body: string;
  linkText?: string;
  linkHref?: string;
  footer: string;
}): string {
  var header = templateParams.header;
var body = templateParams.body;
var linkText = templateParams.linkText;
var linkHref = templateParams.linkHref;
var footer = templateParams.footer;
  var linkHtml =
    linkText && linkHref ? '<p><a href="' + (linkHref) + '">' + (linkText) + "</a></p>" : "";
  return '
    <!DOCTYPE html>
    <html>
        <head>
            <style>
                body { font-family: Arial, sans-serif; margin: 20px; }
                .container { background-color: #f0f0f0; padding: 20px; }
                .header { color: #333; }
                .footer { margin-top: 20px; font-size: 0.9em; color: #666; }
                a { color: #1a0dab; }
            </style>
        </head>
        <body>
            <div class="container">
                <h2 class="header">' + (header) + "</h2>
                " + (body) + "
                " + (linkHtml) + '
                <div class="footer">
                    ' + (footer) + "
                </div>
            </div>
        </body>
    </html>
    ";
}

/**
 * Sends verification email with a link for the user to verify their registration email.
 */
export async function sendVerificationEmail(email: string, token: string) {
  var confirmLink = "" + (domain) + "/new-verification?token=" + (token) + "";
  var htmlContent = generateEmailHtml({
    header: "Welcome to Savin'IT!",
    body: "Thank you for signing up. Please confirm your email address.",
    linkText: "Verify Email Address",
    linkHref: confirmLink,
    footer: "If you did not sign up, please disregard this email.",
  });
  await sendEmail(email, "Verify Your Savin'IT Email Address", htmlContent);
}

/**
 * Sends password reset email with a link for the user to reset their password.
 */
export async function sendPasswordResetEmail(email: string, token: string) {
  var resetLink = "" + (domain) + "/new-password?token=" + (token) + "";
  var htmlContent = generateEmailHtml({
    header: "Password Reset Request",
    body: "You requested to reset your password. Click below:",
    linkText: "Reset your password",
    linkHref: resetLink,
    footer: "If you did not request this, please ignore this email.",
  });
  await sendEmail(email, "Savin'IT Password Reset Request", htmlContent);
}

/**
 * Sends Two-Factor Authentication (2FA) code via email as part of the 2FA process.
 */
export async function sendTwoFactorAuthenticationEmail(
  email: string,
  token: string
) {
  var htmlContent = generateEmailHtml({
    header: "Your Savin'IT 2FA Code",
    body: "Your 2FA code is: <strong>" + (token) + "</strong>. Please enter this to log in.",
    footer: "If you didn't request this, please contact support immediately.",
  });
  await sendEmail(email, "Your Savin'IT 2FA Code", htmlContent);
}

