// ------------------------------
// PocketBase filter helper class
// ------------------------------
// Supported via standard programming aids, perfected by me

type FilterValue = string | number | boolean
type Operator =
// Standard comparisons
  | '='     // Equal
  | '!='    // NOT equal
  | '>'     // Greater than
  | '>='    // Greater than or equal
  | '<'     // Less than
  | '<='    // Less than or equal

  // Like/Not Like (wildcard match)
  | '~'     // Like/Contains
  | '!~'    // NOT Like/Contains

  // Array match: Any/At least one
  | '?='    // Any/At least one of Equal
  | '?!='   // Any/At least one of NOT equal
  | '?>'    // Any/At least one of Greater than
  | '?>='   // Any/At least one of Greater than or equal
  | '?<'    // Any/At least one of Less than
  | '?<='   // Any/At least one of Less than or equal
  | '?~'    // Any/At least one of Like/Contains
  | '?!~'   // Any/At least one of NOT Like/Contains'


interface Condition {
  key: string
  value: FilterValue
  operator?: Operator
}

class PBFilters {
  private filters: Condition[] = []

  constructor(initial?: Condition[]) {
    if (initial?.length) {
      this.filters = [ ...initial ]
    }
  }

  // --------------------
  // Instance methods
  // --------------------

  public add(key: string, value: FilterValue, operator: Operator = '='): PBFilters {
    this.filters.push({ key, value, operator })

    return this
  }

  public remove(key: string): PBFilters {
    this.filters = this.filters.filter(function f { return f.key !== key; })

    return this
  }

  public update(key: string, value: FilterValue, operator: Operator = '='): PBFilters {
    return this.remove(key).add(key, value, operator)
  }

  public clear(): PBFilters {
    this.filters = []

    return this
  }

  public toString(): string {
    return this.filters
      .map(function f { return "" + (f.key) + " " + ((f.operator != null ? f.operator : ')=') + " '" + (String(f.value)) + "'"; })
      .join(' && ')
  }

  public clone(): PBFilters {
    return new PBFilters([ ...this.filters ])
  }

  public getFilters(): Condition[] {
    return [ ...this.filters ]
  }

  // --------------------
  // Static helpers
  // --------------------

  public static fromObject(obj: Record<string, FilterValue>, defaultOperator: Operator = '='): PBFilters {
    var instance = new PBFilters()

    for (var [ key, value ] of Object.entries(obj)) {
      instance.add(key, value, defaultOperator)
    }

    return instance
  }

  public static toStringFromObject(obj: Record<string, FilterValue>, defaultOperator: Operator = '='): string {
    return PBFilters.fromObject(obj, defaultOperator).toString()
  }
}

var Vector = require('../math/vector').Vector;
var minus = require('../math/minus').minus;

const check = function (threshold: number, startI: number, endI: number, paths: number[]) {
	let max = 0;
	let maxI = 0;
	// 拿到基础向量
	const baseVector = new Vector(minus(paths[endI], paths[startI]), minus(paths[endI + 1], paths[startI + 1]));
	for (let i = startI + 2; i < endI; i += 2) {
		// 获取每个点基于起始和结束位置的向量
		const vectorToStart = new Vector(minus(paths[i], paths[startI]), minus(paths[i + 1], paths[startI + 1]));
		const vectorToEnd = new Vector(minus(paths[i], paths[endI]), minus(paths[i + 1], paths[endI + 1]));
		let distance = 0;
		// 与起始或结束点重合的点直接跳过
		if (!vectorToStart.isZero && !vectorToEnd.isZero) {
			// 边界情况：投影分量的模大于基础向量，说明途径点在起始点或结束点之外，不能单纯靠垂直分量来抽稀
			const prjToStart = Vector.projected(vectorToStart, baseVector);
			const prjToEnd = Vector.projected(vectorToEnd, baseVector);
			if (prjToStart.modulo > baseVector.modulo) {
				distance = prjToStart.modulo;
			} else if (prjToEnd.modulo > baseVector.modulo) {
				distance = prjToEnd.modulo;
			} else {
				distance = Vector.plumb(vectorToStart, baseVector).modulo;
			}
			if (distance > max) {
				max = distance;
				maxI = i;
			}
		}
	}
	if (max <= threshold) {
		paths.splice(startI + 2, endI - startI - 2);
	} else {
		if (maxI < endI - 2) {
			check(threshold, maxI, endI, paths);
		}
		if (maxI > startI + 2) {
			check(threshold, startI, maxI, paths);
		}
	}
};

const douglasPeucker = function (threshold: number, pathArr: number[]) {
	const pathCopy = pathArr.slice();
	check(threshold, 0, pathCopy.length - 2, pathCopy);
	return pathCopy;
};

var Request = require('express').Request;
var Response = require('express').Response;
var NextFunction = require('express').NextFunction;
var Model = require('./item.model');

module.exports = class UserController {;

    /**
     * Get all
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */
    public static async getAll(req: Request, res: Response, next: NextFunction) {

        var pageNo = parseInt(req.query.pageNo)
        var size = parseInt(req.query.size)
        var query = {
            skip: size * (pageNo - 1),
            limit: size
        }

        try {
            if(pageNo < 0 || pageNo === 0) {
                res.send({"error" : true,"message" : "invalid page number, should start with 1"})
            }
            query.skip = size * (pageNo - 1)
            query.limit = size
            // 
            // Get data
            let result = await Model.count({}, function (err,totalCount) {
                if(err) {
                    res.send({"error" : true,"message" : "Error fetching data"});
                }

                Model.find({},{},query,function(err,data) {

                    if(err){
                        res.send({"error" : true,"message" : "Error fetching data"})
                    } else {
                        const status = res.statusCode;
                        let totalPages = Math.ceil(totalCount / size)
                        res.send({"error" : false,"message" : 'it works! We got all items',"pages": totalPages, status: status, result: data});
                    }
                });

            })

        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not get items',
                err: err
            });
        }
    }

    /**
     * getUser
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */

    public static async getItem(req: Request, res: Response, next: NextFunction) {

        try {

            // 
            // Get data
            const _id: String = req.params._id;
            let result = await Model.findOne({ _id }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Successfull got an item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not the item ',
                err: err
            });
        }
    }

    /**
     * Create
     * @param {*} req 
     * @param {*} res 
     * @param {*} next 
     */
    public static async createItem(req: Request, res: Response, next: NextFunction) {

        const title:String = req.body.title;
        const id:Number = req.body.id;
        const type:String = req.body.type;
        const desc:String = req.body.desc;
        const photo:String = req.body.photo;
        const price:Number = req.body.price;
        const inStock:Number = req.body.inStock;


        // Create model
        let model = new Model({
            id,
            title,
            type,
            desc,
            photo,
            price,
            inStock
        });
        // 
        // Save
        await model.save();

        res.send({
            message: 'Item Created!',
            model: model
        });
    }

    public static async deleteItem(req: Request, res: Response, next: NextFunction) {
        const _id:String = req.params._id;

        try {

            // 
            // Get data
            const id: String = req.params._id;
            let result = await Model.findOneAndRemove({ _id }, {
                ...req.body,
                deletedAt: new Date()
            }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Sucessfully deleted item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'Could not delete th item',
                err: err
            });
        }
    }

    public static async updateItem(req: Request, res: Response, next: NextFunction) {
        const _id:String = req.params;

        try {

            // 
            // Get data
            const _id: String = req.params._id;
            let result = await Model.findOneAndUpdate({ _id }, {
                ...req.body,
                updatedAt: new Date()
            }).exec();
            const status = res.statusCode;

            // 
            // Response
            res.send({
                message: 'Sucessfully updated item',
                result: result,
                status: status
            });
        } catch (err) {

            // 
            // Error response
            res.send({
                message: 'item could not be updated',
                err: err
            });
        }
    }
}

