var decompress = require('decompress');
var fs = require('fs-extra');
var path = require('path');

var Progress = require('progress');
var _import = require('request');

var _import = require('./config');

function download(url: string, destPath: string) {
  return new Promise(function (resolve, reject) {
    console.log("Downloading GPG from " + (url) + ".");

    var req = request({
      url,
      headers: {
        "Accept": "application/octet-stream",
        "User-Agent": "squeegpg",
      },
    });

    req.pipe(fs.createWriteStream(destPath));

    req.on("error", (err: any) => {
      if (err.code === "ETIMEDOUT") {
        console.error(
          "A timeout occurred while downloading " + (url) + ". Check your Internet connection and try again. " +
          "If you are using a proxy, make sure that the HTTP_PROXY and HTTPS_PROXY environment variables " +
          "are set.",
        );
      } else {
        console.error("An error occurred while downloading " + (url) + ".", err);
      }
      reject(err);
    });

    req.on("response", (res: Response) => {
      if (res.statusCode !== 200) {
        console.error("Non-200 response returned from " + (url) + ": " + (res.statusCode) + ".");
        reject(new Error("Non-200 response"));
      }

      var len = parseInt(res.headers["content-length"] || "0", 10);

      var bar = new Progress("[:bar] :percent :etas", {
        complete: "=",
        incomplete: " ",
        width: 50,
        total: len,
      });

      res.on("data", (chunk) => bar.tick(chunk.length));
      res.on("end", () => {
        console.log("\n");
        resolve();
      });
    });
  });
}

async function main() {
  await fs.mkdirs(config.outputDir);

  var platform: IPlatform;
  if (!(process.platform in config.platforms)) {
    console.error("Unrecognized platform " + (process.platform) + ".");
    console.error("No binary distribution is available for your platform.");
    throw new Error("No binary distribution");
  } else {
    platform = config.platforms[process.platform] as IPlatform;
  }

  var url = "https://github.com/atom/squeegpg-native/releases/download/" + (config.nativeTag) + "/" + (platform.tarball) + "";
  var tarballPath = path.join(config.outputDir, platform.tarball);

  try {
    await download(url, tarballPath);
    await decompress(tarballPath, config.outputDir);
  } finally {
    await fs.remove(tarballPath);
  }
}

main().then(
  function () { return process.exit(0); },
  function (err) {
    // tslint:disable-next-line no-console
    console.error("Unable to download GPG archive", err);
    process.exit(1);
  },
);

var Observable = require('./objects').Observable;
var Derivation = require('./objects').Derivation;
var Computed = require('./objects').Computed;


let inTransaction: boolean = false;
let derivationsDuringTransaction = new Set<Derivation>();

/**
 * Decorator to indicate that a class property is an Observable, thus triggering any Computed values or Reactions
 * whenever the value of this Observable changes.
 * For this demo, this only supports `@observable someProp`. No support for Arrays and Maps.
 */
function observable(obj: any, prop: string): any {
    const observable = {
        derivations: new Set<Derivation>(),
        val: undefined
    };
    return {
        enumerable: false,
        configurable: true,
        get: function () {
            if (Derivation.derivationEvaluated) {
                Derivation.derivationEvaluated.newDependencies.add(observable);
            }
            return observable.val;
        },
        set: function (newVal: any) {
            const oldVal = observable.val;
            observable.val = newVal;
            if (observable.val !== oldVal) { // Something changed, trigger actions
                triggerDerivations(observable.derivations);
            }
        }
    }
}

/**
 * Triggering derivations after an observable changes is done in two stages.
 * 1 - Send a 'stale' notification that propagates all the way through the dependency tree.
 * Each Derivation keeps track of the number of 'stale' notification it receives, which tells it how many dependencies it has to wait on.
 * 2 - Send a 'ready' notification to the Derivations directly affected (without going through computed values) by the original obsrvable change.
 * Once a Derivation has received as many 'ready' notifications as it has received 'stale' notifications (and that at least one of their values changed),
 * it in turn sends a 'ready' notification to its direct dependents, along with whether its value has changed.
 * run this in 2 waves. 1 - Send 'stale' notifications to all derivations. The derivations will count the number of stale notifications they get.
*/
function triggerDerivations(derivations: Set<Derivation>) {
    if (inTransaction) {
        for (let derivation of derivations) derivationsDuringTransaction.add(derivation);
        return;
    }

    // Mark any accessed derivation as stale
    for (let derivation of derivations) derivation.markStale();
    // Then send 'ready' notifications to all derivations once a depencency has finished evaluating
    // A derivation is always re-evaluated when it is triggered in order to update its Observable dependencies
    for (let derivation of derivations) derivation.sendReady(true);
}

/**
 * A computed value is cached and only re-computed whenever an observable on which this is dependent changes value.
 * This thus assumes that computed methods are pure. Computed values act as both observables and derivations
 * since they are updated by observables and update the derivations that depend on this.
 * In MobX, the value is also garbage collected if there are no listeners.
 */
function computed<T>(obj: any, prop: string, descriptor: TypedPropertyDescriptor<T>): any {
    if (!descriptor.get) return descriptor;

    const originalGetter = descriptor.get.bind(obj); // The original getter lives in descriptor.get
    const observable: Observable = {
        val: undefined,
        derivations: new Set<Derivation>()
    };

    const computed = new Computed(observable, originalGetter);

    computed.evaluate(); // Initialize

    return {
        enumerable: false,
        configurable: true,
        get: function () {
            if (Derivation.derivationEvaluated) {
                Derivation.derivationEvaluated.newDependencies.add(observable);
            }
            return observable.val;
        }
    };
}

/**
 * Runs the given method 'fn' while keeping track of all affected Reactions.
 * All these Reactions are then triggered once after 'fn' has completed.
 */
function transaction(fn: function () { return void; }) {
    inTransaction = true;
    fn();
    inTransaction = false;

    triggerDerivations(derivationsDuringTransaction);
    derivationsDuringTransaction = new Set<Derivation>();
}

/**
 * Runs the given method whenever an Observable or a Computed value used inside changes value.
 * Evaluates the Observable dependencies at runtime, thus only running when absolutely necessary.
 */
function autorun(fn: function () { return void; }) {
    const reaction = new Derivation(fn);
    reaction.evaluate(); // Run it initially. This also allows to figure out the (initial) dependencies of that reaction
}

var Component = require('@angular/core').Component;
var OnDestroy = require('@angular/core').OnDestroy;
var OnInit = require('@angular/core').OnInit;
var FormBuilder = require('@angular/forms').FormBuilder;
var FormGroup = require('@angular/forms').FormGroup;
var Router = require('@angular/router').Router;
var ActivatedRoute = require('@angular/router').ActivatedRoute;
var FormioAppConfig = require('@formio/angular').FormioAppConfig;
var FormioService = require('@formio/angular').FormioService;
import {
  debounceTime,
  filter,
  switchMap,
  takeUntil,
  map,
} from 'rxjs/operators';
var Subject = require('rxjs').Subject;
var DinetFormioForm = require('../../dinet_common').DinetFormioForm;
var FormioServiceFactoryService = require('../../formio-service-factory.service').FormioServiceFactoryService;

/** This component Built using basic development resources-5, original component for meo2.component.ts */

@Component({
  selector: 'app-meo2',
  templateUrl: './meo2.component.html',
  styleUrls: ['./meo2.component.scss'],
})
class Meo2Component implements OnInit, OnDestroy {
  url = this.appConfig.appUrl;
  lotUrl = this.appConfig.appUrl; // URL a lot formhoz

  userDisplayResults: DinetFormioForm[] = [];
  searchForm!: FormGroup;

  //private formService = new FormioService(this.url);
  //private lotFormService = new FormioService(this.url);
  private formService: FormioService;
  private lotFormService: FormioService;

  private destroy$ = new Subject<void>();

  private readonly lotQuery = {
    params: {
      name__eq: 'lot',
      type: 'resource',
    },
  };

  constructor(
    public appConfig: FormioAppConfig,
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private formioFactory: FormioServiceFactoryService
  ) {
    this.formService = this.formioFactory.create(this.url);
    this.lotFormService = this.formioFactory.create(this.lotUrl);
  }

  /** Ha egy sorra kattintanak, elmentjük a szükséges adatokat és betöltjük a lépést */
  ClickedRow(i: number, form: DinetFormioForm) {
    const result = this.userDisplayResults[i]?.data;
    if (!result) return;

    localStorage.setItem('prod_no', (result.productNo != null ? result.productNo : ''));
    localStorage.setItem('lot_no', (result.lot != null ? result.lot : ''));
    localStorage.setItem('initial_quantity', (result.initialQuantity != null ? result.initialQuantity : ''));

    this.FindStep(form);
  }

  /** Megkeresi a következő lépést a termék nevéből */
  FindStep(form: DinetFormioForm) {
    const name = localStorage.getItem('prod_no');
    if (!name) return;

    const query = {
      params: {
        name__regex: "/" + (name) + "/i",
        tags__eq: ['common'],
        type: 'form',
      },
    };

    this.formService
      .loadForms(query)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: function (results) {
          const dinetResults = (results as DinetFormioForm[]).sort((a, b) =>
            ((a.name != null ? a.name : '')).localeCompare((b.name != null ? b.name : ''), undefined, {
              sensitivity: 'base',
            })
          );

          localStorage.setItem('forms', JSON.stringify(dinetResults));

          if (dinetResults.length > 0) {
            this.router.navigate(['step', dinetResults[0]._id], {
              relativeTo: this.route,
            });
          } else {
            alert('No Product found!'); // TODO: snackbar ajánlott
          }
        },
        error: function (e) {
          console.error(e);
          alert('Error loading forms: ' + e); // TODO: snackbar ajánlott
        },
      });
  }

  ngOnInit() {
    // Lot form betöltés
    this.lotFormService
      .loadForms(this.lotQuery)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: function (results) {
          const lotForms = results as DinetFormioForm[];
          if (lotForms.length > 0) {
            const lotId = (lotForms[0]._id != null ? lotForms[0]._id : '');
            this.lotUrl = "" + (this.appConfig.appUrl) + "/form/" + (lotId) + "/submission";
            //this.lotFormService = new FormioService(this.lotUrl);
            this.lotFormService = this.formioFactory.create(this.lotUrl); // ✅ no `new`
          }
        },
        error: function (e) {
          alert('Error loading forms: ' + e);
        },
      });

    // Kereső form
    this.searchForm = this.fb.group({ lot: [''] });
    localStorage.removeItem('forms');

    this.searchForm
      .get('lot')!
      .valueChanges.pipe(
        debounceTime(400),
        filter(function (value) { return value?.length > 1; }),
        map(function (value) { return value.trim(); }),
        switchMap(function (value) { return this.lotFormService.loadSubmissions({
            params: {
              'data.lot__regex': "/" + (value) + "/i",
              'data.inProduction': 'true',
            },
          }); }),
        takeUntil(this.destroy$)
      )
      .subscribe(function (results) {
        this.userDisplayResults = results as DinetFormioForm[];
      });
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
}

