// MeSpeak
const meSpeak = require("mespeak");
meSpeak.loadConfig(require("../public/mespeak-config.json"));
meSpeak.loadVoice(require("mespeak/voices/en/en-us.json"));

// Scroll Indicator
const beepFileURL = require("../public/beep.mp3");
let beepArrayBuffer: ArrayBuffer;
let beepAudioBuffer: AudioBuffer;

getArrayBuffer(beepFileURL).then(function (buffer) {
  beepArrayBuffer = buffer;
});

let pitchConst = 350;

/** Sets the position of the PannerNode. */
function setPannerPosition(x: number = 0, y: number = 0, z: number = 5): void {
  if (!panner) {
    console.error(
      "Panner has not been initialized; make sure to only call setPannerPosition() once you're the audioContext has been initialized!"
    );
    return;
  }

  panner.positionX.value = Math.min(Math.max(x, leftStereoCutoff), rightStereoCutoff) * 20;
  panner.positionY.value = y;
  panner.positionZ.value = z;
}

let lastSoundSource: { sourceNode: AudioBufferSourceNode; id: number } | undefined;
let soundPromiseRejectMethods: Map<number, Function> = new Map();
let soundsPlayed = 0;
let sources: AudioBufferSourceNode[] = [];

let leftStereoCutoff = -1;
let rightStereoCutoff = 1;

let voiceSpeed = 175;

let spatializeAudio = true;
chrome.storage.sync.get(["spatializeAudio", "leftStereoCutoff", "rightStereoCutoff", "voiceSpeed"], function (items) {
  const loadedSettings = items as Partial<Settings>;

  spatializeAudio = (loadedSettings.spatializeAudio != null ? loadedSettings.spatializeAudio : true);
  leftStereoCutoff = loadedSettings.leftStereoCutoff ?? -1;
  rightStereoCutoff = (loadedSettings.rightStereoCutoff != null ? loadedSettings.rightStereoCutoff : 1);
  voiceSpeed = (loadedSettings.voiceSpeed != null ? loadedSettings.voiceSpeed : 175);
});

interface PlaySoundProps {
  bias: { x: number; y: number };
  text?: string;
  scrollBeep?: boolean;
}

export async function playSound({ bias, text, scrollBeep = false }: PlaySoundProps): Promise<void> {
  if (text === "") return;

  return new Promise(async function (resolve, reject) {
    if (!spatializeAudio) bias = { x: 0, y: 0 };

    if (!audioCtx) {
      audioCtx = new AudioContext();
      panner = audioCtx.createPanner();

      beepAudioBuffer = await audioCtx.decodeAudioData(beepArrayBuffer);
    }

    await audioCtx.resume();

    const id = soundsPlayed++;

    soundPromiseRejectMethods.set(id, reject);

    // Prevent multiple sounds from playing at the same time
    stopAllSounds();

    let source = audioCtx.createBufferSource();
    lastSoundSource = { sourceNode: source, id: id };
    sources.push(source);

    if (!scrollBeep) {
      // TTS using MeSpeak
      const audioData = meSpeak.speak(text, { speed: voiceSpeed, rawdata: true });
      source.buffer = await audioCtx.decodeAudioData(audioData);
    } else {
      // Royalty free beep: https://samplefocus.com/samples/short-beep
      if (!beepArrayBuffer) {
        console.error("There was an error in loading the beep sound file.");
        reject();
        return;
      }

      source.buffer = beepAudioBuffer;
    }

    source.onended = () => {
      lastSoundSource = undefined;
      resolve();
    };

    // Modifies pitch based on provided y-value
    setPannerPosition(bias.x, bias.y);

    source.detune.value = pitchConst * panner!.positionY.value;

    // Balancing volume levels
    const gainNode = audioCtx.createGain();
    gainNode.gain.value = logarithmicIncrease(Math.abs(bias.x)); // Gain increases as distance from center increases to help balance out volume levels

    console.log("%cGain amount: " + (gainNode.gain.value) + "; Bias: x: " + (bias.x) + ", y: " + (bias.y) + "", "color: lightblue");

    source.connect(gainNode).connect(panner!).connect(audioCtx.destination);

    source.start(0);
  });
}

function stopAllSounds() {
  try {
    if (lastSoundSource !== undefined) {
      lastSoundSource.sourceNode.stop();

      //Reject last sound's promise
      soundPromiseRejectMethods.get(lastSoundSource.id)!(lastSoundSource.id);
      soundPromiseRejectMethods.delete(lastSoundSource.id);

      lastSoundSource = undefined;
    }

    for (let i = 0; i < sources.length; i++) {
      const source = sources[i];

      if (source) {
        source.stop();
      }
    }
  } catch {
    // Possible error: InvalidStateNode (DOMException) Thrown if the node has not been started by calling start(). (https://developer.mozilla.org/en-US/docs/Web/API/AudioScheduledSourceNode/stop)
    // This error isn't important. A try/catch block is used to help keep the console neater until a better method of solving this issue is found.
  }
}

const cancelSoundsCallback = function (e: KeyboardEvent) {
  if (e.key.toLowerCase() === Keys.Esc) stopAllSounds();
};
const addCancelSoundsHandler = function () { return document.addEventListener("keydown", cancelSoundsCallback); };
const clearCancelSoundsHandler = function () { return document.removeEventListener("keydown", cancelSoundsCallback); };

// Supported via standard programming aids
function logarithmicIncrease(x: number) {
  const maxOutput = 10; // Set the maximum output value
  const minInput = 0.25; // Set the input value where the curve peaks
  const k = Math.log(maxOutput + 1) / Math.log(1 + maxOutput * (1 - minInput)); // Calculate the logarithmic scaling factor
  return (Math.log(1 + maxOutput * x) / Math.log(1 + maxOutput * minInput)) * k + 1; // Apply the logarithmic scaling factor and shift output to start at 1
}

onEventListenerStatusChange({ onEnable: addCancelSoundsHandler, onDisable: clearCancelSoundsHandler });

var cheerio = require('cheerio');
var axios = require('axios');
var Name = require('mizzoureview-reading/models/name').Name;
import {
    AIPromptAnswers,
    Professor,
} from 'mizzoureview-reading/models/professor';
var generateWikiFunFacts = require('src/helpers/gemini.js').generateWikiFunFacts;

// first Aided using common development resources
export async function getArticleContentByName(name: Name) {
    const baseUrl = 'https://en.wikipedia.org/w/api.php';

    // Step 1: Search for the page
    const searchParams = new URLSearchParams({
        origin: '*',
        action: 'parse',
        page: "" + (name) + "",
        format: 'json',
    });

    const fetchUrl = "" + (baseUrl) + "?" + (searchParams) + "";

    var data = await.data;axios.get(fetchUrl);

    if (data.error) {
        return 'No article';
    }
    const $ = cheerio.load(data.parse.text['*']);

    // Extract only the main content paragraphs
    const articleText = $('p').text();

    return articleText;
}

export async function setProfessorFunFacts(
    profArray: Professor[],
): Promise<boolean> {
    for (let i = 0; i < profArray.length; i++) {
        const prof: Professor = profArray[i];
        if (prof.basicInfo === undefined) {
            return false;
        }
        const article = await getArticleContentByName(prof.basicInfo.name);
        const funFacts = await generateWikiFunFacts(article);
        if (funFacts !== undefined) {
            if (prof.aIPromptAnswers === undefined) {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                });
            } else {
                prof.aIPromptAnswers = new AIPromptAnswers({
                    funFacts: funFacts,
                    letterToProfessor: prof.aIPromptAnswers.letterToProfessor,
                    letterToStudent: prof.aIPromptAnswers.letterToStudent,
                });
            }
        }
    }
    return true;
}

var _getListener = require('./ListenerMap')._getListener;
var _removeListener = require('./ListenerMap')._removeListener;
var _setListener = require('./ListenerMap')._setListener;
import {
  AsyncMessageListener,
  CoreListener,
  CoreResponse,
  MessageListener,
} from './types'

const scopeOn = function (scope: string) { return (callback: MessageListener) => {
  const listener: CoreListener = (message, sender) => {
    if (message.async || message.scope !== scope) {
      return false
    }

    try {
      callback(message.payload, sender)
    } catch (error) {
      // Log listener error
      console.error('Uncaught error in chrome.runtime.onMessage listener')
      console.error(error)
    }

    return false
  }

  chrome.runtime.onMessage.addListener(listener)
  _setListener(scope, callback, listener)
}

const scopeAsyncOn = (scope: string) => (
  callback: AsyncMessageListener,
) => {
  const listener: CoreListener = (message, sender, sendResponse) => {
    if (message.async && scope === message.scope) {
      handleMessage()
      return true
    }

    return false

    async function handleMessage() {
      try {
        const respond = (response: any): void => {
          const coreResponse: CoreResponse = {
            success: true,
            payload: response,
          }

          sendResponse(coreResponse)
        }

        await callback(message.payload, sender, respond)
      } catch (error) {
        const response: CoreResponse = {
          success: false,
          payload: {
            greeting: error.message,
          },
        }

        console.error(error)
        sendResponse(response)
      }
    }
  }

  chrome.runtime.onMessage.addListener(listener)
  _setListener(scope, callback, listener)
}

const scopeOff = (scope: string) => (
  listener: MessageListener | AsyncMessageListener,
) => {
  const _listener = _getListener(scope, listener)

  if (_listener) {
    _removeListener(scope, listener)
    chrome.runtime.onMessage.removeListener(_listener)
  }
}; }

var fs = require('fs');
var Module = require('../').Module;

const bitcode = new Module('source-name');

// Create an instance of `bitcode-builder`
const b = bitcode.createBuilder();

// Define a function
const sig = b.signature(b.i(32), [ b.i(32), b.i(32) ]);
const fn = sig.defineFunction('fn_name', [ 'param0', 'param1' ]);

const param0 = fn.getArgument('param0');
const param1 = fn.getArgument('param1');
const sum = fn.body.binop('add', param0, param1);

fn.body.ret(sum);

// Add function to the module
bitcode.add(fn);

// Build module
fs.writeFileSync('out.bc', bitcode.build());

// Notice! This file JSDOC is Supported by standard GitHub tools.
// So some of this JSDOC is not correct.
// Please refer to documents https://multi-embed-player.pages.dev/docs/reference/iframe_class/#mep_niconico-class

/**
 * @typedef {Object} mep_niconico_load_object
 * @property {string} videoId - The ID of the video.
 * @property {number} [startSeconds] - The start time of the video.
 * @property {number} [endSeconds] - The end time of the video.
 */
interface mep_niconico_load_object {
    videoId: string;
    startSeconds?: number;
    endSeconds?: number;
}

/**
 * @typedef {Object} mep_niconico_playerVars
 * @property {number} [startSeconds] - The start time of the video.
 * @property {number} [endSeconds] - The end time of the video.
 * @property {number} [autoplay] - Whether the video is on autoplay.
 * @property {number} [displayComment] - Whether the video is on display comment mode.
 */
interface mep_niconico_playerVars {
    startSeconds?: number;
    endSeconds?: number;
    autoplay?: number;
    displayComment?: number;
}

/**
 * @typedef {Object} mep_niconico_content
 * @property {string} videoId - The ID of the video.
 * @property {number} width - The width of the player.
 * @property {number} height - The height of the player.
 * @property {mep_niconico_playerVars} playerVars - The player variables.
 */
interface NiconicoPlayerState {
    isRepeat: boolean;
    playerStatus: number;
    currentTime?: number;        // ミリ秒単位
    duration?: number;           // ミリ秒単位
    muted?: boolean;             // ミュート状態
    volume?: number;             // 0-1の範囲
    videoInfo?: {
        title?: string;          // 動画タイトル
    };
}

interface mep_niconico_content {
    videoId: string;
    width: number;
    height: number;
    playerVars?: mep_niconico_playerVars;
}

interface NiconicoPlayMessage {
    eventName: 'play';
}

interface NiconicoPauseMessage {
    eventName: 'pause';
}

interface NiconicoSeekMessage {
    eventName: 'seek';
    data: {
        time: number;  // ミリ秒
    };
}

interface NiconicoCommentVisibilityMessage {
    eventName: 'commentVisibilityChange';
    data: {
        commentVisibility: boolean;
    };
}

interface NiconicoMuteMessage {
    eventName: 'mute';
    data: {
        mute: boolean;
    };
}

interface NiconicoVolumeMessage {
    eventName: 'volumeChange';
    data: {
        volume: number;  // 0-1の範囲
    };
}

type NiconicoPostMessage = 
    | NiconicoPlayMessage 
    | NiconicoPauseMessage 
    | NiconicoSeekMessage 
    | NiconicoCommentVisibilityMessage 
    | NiconicoMuteMessage 
    | NiconicoVolumeMessage;

/**
 * Class representing a Niconico player.
 */
class mep_niconico{
    state: NiconicoPlayerState;
    startSeconds: number;
    player: HTMLIFrameElement;
    playerId: string;
    autoplay_flag: boolean;
    endSeconds: number;
    displayCommentMode: boolean | undefined;

    /**
     * The ID of the player.
     * @type {number}
     */
    static playerId = 0;
    /**
     * The origin of the Niconico player.
     * @type {string}
     */
    static origin = 'https://embed.nicovideo.jp';
    /**
     * The result of checking local storage.
     * @type {boolean}
     */
    static localStorageCheck: boolean | null = null;
    /**
     * Create a Niconico player.
     * @param {string|HTMLElement} replacing_element - The element to replace with the player.
     * @param {Object} content - The content of the player.
     * @param {Function} player_set_event_function - The function to set player events.
     */
    constructor(replacing_element: string | HTMLElement, content: mep_niconico_content, player_set_event_function?: function (player: HTMLIFrameElement) { return void; }){
        /**
         * The state of the player.
         * @type {Object}
         * @property {boolean} isRepeat - Whether the player is on repeat.
         * @property {number} playerStatus - The status of the player.
         */
        var element: HTMLElement;
        if(typeof replacing_element === "string"){
            var found_element = document.getElementById(replacing_element);
            if (!found_element) {
                throw new Error('Element with id "' + (replacing_element) + '" not found');
            }
            element = found_element;
        } else {
            element = replacing_element;
        }
        this.state = {
            isRepeat: false,
            playerStatus: 0
        };
        this.#messageListener();
        /**
         * The start time of the player.
         * @type {number}
         */
        this.startSeconds = 0;
        if(content?.playerVars?.startSeconds!=undefined){
            this.startSeconds = content?.playerVars?.startSeconds;
        }
        var niconico_doc = document.createElement("iframe");
        niconico_doc.src = "https://embed.nicovideo.jp/watch/" + content["videoId"] + "?jsapi=1&playerId=" + String(mep_niconico.playerId) + "&from=" + String(this.startSeconds);
        this.playerId = String(mep_niconico.playerId);
        mep_niconico.playerId++;
        niconico_doc.width = String(content["width"]);
        niconico_doc.height = String(content["height"]);
        niconico_doc.allow = "autoplay";//fix bug not autoplay on chrome
        niconico_doc.allowFullscreen = true;//fix bug can't watch on full screen(all browser)
        niconico_doc.style.border = "none";//fix bug display border on outer frame
        element.replaceWith(niconico_doc);
        /**
         * The player element.
         * @type {HTMLIFrameElement}
         */
        this.player = niconico_doc;
        if(typeof player_set_event_function === "function"){
            player_set_event_function(this.player);
        }
        /**
         * Whether the player is on autoplay.
         * @type {boolean}
         */
        this.autoplay_flag = false;
        if(content?.playerVars?.autoplay==1){//終わり次第再生
            this.autoplay_flag = true;
        }
        /**
         * The end time of the player.
         * @type {number}
         */
        this.endSeconds = -1;
        if(content?.playerVars?.endSeconds!==undefined){
            this.endSeconds = content?.playerVars?.endSeconds;
        }
        if(content?.playerVars?.displayComment!==undefined){
            if(content?.playerVars?.displayComment==0){
                this.displayCommentMode = false;
            }
            else if(content?.playerVars?.displayComment==1){
                this.displayCommentMode = true;
            }
        }
    }
    /**
     * Cue a video by ID.
     * @param {mep_niconico_load_object} content - The content of the video.
     */
    cueVideoById(content: mep_niconico_load_object){
        this.startSeconds = 0;
        if(content["startSeconds"]!=undefined){
            this.startSeconds = content["startSeconds"];
        }
        this.endSeconds = -1;
        if(content["endSeconds"]!=undefined){
            this.endSeconds = content["endSeconds"];
        }
        this.player.src = "https://embed.nicovideo.jp/watch/" + content["videoId"] + "?jsapi=1&playerId=" + String(this.playerId) + "&from=" + String(this.startSeconds);
        this.autoplay_flag = false;
    }
    /**
     * Load a video by ID.
     * @param {mep_niconico_load_object} content - The content of the video.
     */
    loadVideoById(content: mep_niconico_load_object){
        this.startSeconds = 0;
        if(content["startSeconds"]!=undefined){
            this.startSeconds = content["startSeconds"];
        }
        this.endSeconds = -1;
        if(content["endSeconds"]!=undefined){
            this.endSeconds = content["endSeconds"];
        }
        this.player.src = "https://embed.nicovideo.jp/watch/" + content["videoId"] + "?jsapi=1&playerId=" + String(this.playerId) + "&from=" + String(this.startSeconds);
        this.autoplay_flag = true;
    }
    /**
     * Get the real duration of the video.
     * @returns {number} The duration of the video.
     */
    getRealDulation(): number{//original function
        if(this.endSeconds==-1){
            return this.getDuration() - this.startSeconds;
        }
        else{
            return this.endSeconds - this.startSeconds;
        }
    }
    /**
     * Play the video.
     */
    playVideo(): void{
        this.#postMessage({
            eventName: 'play'
        })
    }
    /**
     * Pause the video.
     */
    pauseVideo(): void{
        this.#postMessage({
            eventName: 'pause'
        })
    }
    /**
     * Get the current time of the video.
     * @returns {number} The current time of the video.
     */
    getCurrentTime(): number{
        return ((this.state.currentTime != null ? this.state.currentTime : 0))/1000;//msec->sec
    }
    /**
     * Get the duration of the video.
     * @returns {number} The duration of the video.
     */
    getDuration(): number{
        return ((this.state.duration != null ? this.state.duration : 0))/1000;//msec->sec
    }
    /**
     * Get the title of the video.
     * @returns {string} The title of the video.
     */
    getTitle(): string{
        return this.state.videoInfo?(.title != null ? .title : '');
    }
    /**
     * Check if the video is muted.
     * @returns {boolean} Whether the video is muted.
     */
    isMuted(): boolean{
        return (this.state.muted != null ? this.state.muted : false);
    }
    /**
     * Get the volume of the video.
     * @returns {number} The volume of the video.
     */
    getVolume(): number{
        return Number(this.state.volume)*100;
    }
    /**
     * Seek to a specific time in the video.
     * @param {number} seconds - The time to seek to.
     */
    seekTo(seconds: number): void{
        this.#postMessage({
            eventName: 'seek',
            data: {
              time: seconds*1000//secounds->msec
            }
          })
    }
    /**
     * Change the display comment mode of the video.
     * @param {boolean} mode - The display comment mode to set.
     */
    displayComment(mode: boolean): void{
        this.#postMessage({
            eventName: "commentVisibilityChange",
            data:{
                commentVisibility: mode
            }
        })
    }
    /**
     * Mute the video.
     */
    mute(): void{
        this.#postMessage({
            eventName: "mute",
            data:{
                mute:true
            }
        })
    }
    /**
     * Unmute the video.
     */
    unMute(): void{
        this.#postMessage({
            eventName: "mute",
            data:{
                mute:false
            }
        })
    }
    /**
     * Set the volume of the video.
     * @param {number} volume - The volume to set.
     */
    setVolume(volume: number): void{
        this.#postMessage({
            eventName: "volumeChange",
            data:{
                volume: volume/100
            }
        })
    }
    /**
     * Get the state of the player.
     * @returns {number} The state of the player.
     */
    getPlayerState(): number{
        if(this.getCurrentTime()>=this.getDuration()-0.5||(this.endSeconds!=-1&&this.getCurrentTime()>=(this.endSeconds-0.5))){//最後まで行った
            return 4
        }
        else{
            return this.state.playerStatus;
        }
    }
    /**
     * Post a message to the player.
     * @param {Object} request - The request to post.
     */
    #postMessage(request: NiconicoPostMessage): void {
        var message = Object.assign({
            sourceConnectorType: 1,
            playerId: this.playerId
        }, request);
        if (this.player.contentWindow) {
            this.player.contentWindow.postMessage(message, (window as any).mep_niconico.origin);
        }
    }
    /**
     * Listen for messages from the player.
     */
    #messageListener(): void {
        window.addEventListener('message', function (e) {
          if (e.origin === (window as any).mep_niconico.origin && e.data.playerId === this.playerId) {
            var data = e.data.data;
            switch (e.data.eventName) {
                case 'statusChange': {
                    break;
                }
                case 'error':{
                    this.player.dispatchEvent(new CustomEvent("onError", {detail:{code:500}}));
                    break;
                }
                case 'playerMetadataChange':{
                    break;
                }
                case 'loadComplete':{
                    if(this.autoplay_flag){
                        this.playVideo();
                    }
                    this.player.dispatchEvent(new Event("onReady"));
                    break;
                }
                case 'playerStatusChange':{
                    this.player.dispatchEvent(new CustomEvent("onStateChange", {detail: this.getPlayerState()}));
                    if(this.getCurrentTime()>=this.getDuration()-0.5||(this.endSeconds!=-1&&this.getCurrentTime()>=(this.endSeconds-0.5))){//最後まで行った
                        this.player.dispatchEvent(new Event("onEndVideo"));
                    }
                    break;
                }
                default:
                    console.log(e.data);
            }

            this.state = Object.assign({}, this.state, data);
            if(this.endSeconds!=-1&&((this.state.currentTime != null ? this.state.currentTime : 0))>=this.endSeconds*1000){//終了時間の時自動で停止
                this.pauseVideo();
            }
          }
        });
      }
}
(window as any).mep_niconico = mep_niconico;

var functions = require('firebase-functions');
var Email = require('../domain/common/email').Email;
