'use strict';

var logBlacklist = ['BMS_PASSWORD'];

/**
 * Class for environment variables with default values
 */
class EnvVar {
  private messages: any[];
  private errors: boolean;

  constructor () {
    this.reset();
  }

  log ( message, level ) {
    this.messages.push( { level: level, message: message } );
  }

  init ( config ) {
    // Cycle through all defined environment variables
    for ( var envVar of config.envVars ) {
      // Check if the environment variable is set. If not, cycle through the aliases.
      if ( !( envVar.name in process.env ) ) {
        for ( var i in envVar.alias ) {
          var alias = envVar.alias[i];
          // If the alias exists, copy it to the actual name and delete it.
          if ( alias in process.env ) {
            this.log( "The use of " + (alias) + " is deprecated. Please use " + (envVar.name) + " instead", 'warn' );
            process.env[envVar.name] = process.env[alias];
            delete process.env[alias];
          }
        }
      }

      // Check if the environment variable is set and display it, if it is not set
      // apply the default value. In case the environment variable is required and
      // not set, stop the process.
      if ( envVar.name in process.env ) {
        // Cover blacklisted values
        var value = process.env[envVar.name];

        if ( logBlacklist.indexOf( envVar.name ) !== -1 ) value = '******';

        this.log("" + (envVar.name) + " = " + (value) + " - " + (envVar.description) + "", 'info');
      } else {
        if ( envVar.required === true ) {
          this.log( "" + (envVar.name) + " not set, but required", 'error' );
          this.errors = true;
        } else {
          this.log( "" + (envVar.name) + " = " + (envVar.defaultValue) + " (default) - " + (envVar.description) + "", 'info' );
          process.env[envVar.name] = envVar.defaultValue;
        }
      }
    }
  }

  list ( logger ) {
    for ( var i = 0; i < this.messages.length; i++ ) {
      var m = this.messages[i];
      switch ( m.level ) {
        case 'info':
          logger.info( m.message, 'ENV' );
          break;
        case 'warn':
          logger.warn( m.message, 'ENV' );
          break;
        case 'error':
          logger.error( m.message, 'ENV' );
          break;
        default:
          break;
      }
    }
    this.messages = [];
  }

  hasErrors () {
    return this.errors;
  }

  reset () {
    this.messages = [];
    this.errors = false;
  }
}

var envVar = new EnvVar;

var run = require('deno').run;
var expressive = require('deps.ts').expressive;
var path = require('deps.ts').path;
var opn = require('deps.ts').opn;
var watch = require('deps.ts').watch;

export async function main(
  main: string,
  index: string,
  srcDir: string,
  distDir: string,
  publicDir: string,
  port: number
) {
  let shouldRefresh = false;
  const app = new expressive.App();
  // app.use(expressive.simpleLog());
  app.use(async function (req, res, next) {
    try {
      await next();
    } catch (e) {
      console.log(e);
      throw e;
    }
  });
  app.use(expressive.static_(publicDir));
  app.use(expressive.static_(distDir));
  app.use(expressive.bodyParser.json());
  app.get("/", async function (req, res) {
    await res.file(index, html => {
      return html.replace("</head>", "<script>" + (reloader) + "</script></head>");
    });
  });
  app.get("/live", async function (req, res) {
    if (shouldRefresh) {
      shouldRefresh = false;
      res.status = 205;
    }
  });
  const server = await app.listen(port);
  console.log("server listening on port " + server.port + ".");
  opn("http://localhost:" + port);
  watch([srcDir, publicDir], {
    interval: 500
  }).start(async function () {
    const code = await compile(main, distDir);
    if (code === 0) {
      shouldRefresh = true;
    }
  });
}

function compile(main: string, distDir: string): Promise<number> {
  return new Promise(async function resolve {
    const process = run({
      args: ["elm", "make", main, "--output", path.join(distDir, "elm.js")],
      stdout: "inherit",
      stderr: "inherit"
    });
    const status = await process.status();
    resolve(status.code);
  });
}

const reloader = '
  errorCount = 0;
  function live() {
    fetch("/live").then(function res {
      // console.log(res.status);
      if (res.status === 205) {
        errorCount = 0;
        location.reload();
      } else if (res.status === 200) {
        errorCount = 0;
        setTimeout(live, 1000);
      } else {
        errorCount++;
        if(errorCount > 10) {
          console.log("stopped connection.");
        } else {
          setTimeout(live, 1000);
        }
      }
    }).catch(function e {
      errorCount++;
      if(errorCount > 10) {
        console.log("stopped connection.");
      } else {
        setTimeout(live, 1000);
      }
    });
  }
  live();
';

