function validate(typeName: 'EntityTwo'): function (value: unknown) { return EntityTwo; };
function validate(typeName: 'Entity'): function (value: unknown) { return Entity; };
function validate(typeName: 'Value'): function (value: unknown) { return Value; };
function validate(typeName: string): function (value: unknown) { return any {
  var validator: any = ajv.getSchema("Schema#/definitions/" + (typeName) + "");
  return (value: unknown): any => {
    if (!validator) {
      throw new Error(
        "No validator defined for Schema#/definitions/" + (typeName) + "",
      );
    }

    var valid = validator(value);

    if (!valid) {
      throw new Error(
        'Invalid ' +
          typeName +
          ': ' +
          ajv.errorsText(
            validator.errors!.filter((e: any) => e.keyword !== 'if'),
            {dataVar: typeName},
          ),
      );
    }

    return value as any;
  };
}; }

