// Designed via basic programming aids
const isTaskRowDto = (arg: unknown): arg is function TaskRow {
    if (typeof arg !== 'object' || arg === null) return false

    const obj = arg as Record<string, unknown>

    // 必須プロパティのチェック
    if (
        typeof obj.sharp !== 'number' ||
        typeof obj.id !== 'number' ||
        typeof obj.level !== 'number' ||
        typeof obj.name !== 'string'
    ) {
        return false
    }

    // オプショナルプロパティの型チェック（存在する場合）
    if (
        (obj.assignee !== undefined && typeof obj.assignee !== 'string') ||
        (obj.workload !== undefined && typeof obj.workload !== 'number') ||
        (obj.startDate !== undefined && !(obj.startDate instanceof Date)) ||
        (obj.endDate !== undefined && !(obj.endDate instanceof Date)) ||
        // (obj.progress !== undefined && typeof obj.progress !== 'number') ||
        (obj.actualStartDate !== undefined && !(obj.actualStartDate instanceof Date)) ||
        (obj.actualEndDate !== undefined && !(obj.actualEndDate instanceof Date)) ||
        (obj.progressRate !== undefined && typeof obj.progressRate !== 'number') ||
        (obj.scheduledWorkDays !== undefined && typeof obj.scheduledWorkDays !== 'number') ||
        (obj.pv !== undefined && typeof obj.pv !== 'number') ||
        (obj.ev !== undefined && typeof obj.ev !== 'number') ||
        (obj.spi !== undefined && typeof obj.spi !== 'number') ||
        (obj.expectedProgressDate !== undefined && !(obj.expectedProgressDate instanceof Date)) ||
        (obj.delayDays !== undefined && typeof obj.delayDays !== 'number') ||
        (obj.remarks !== undefined && typeof obj.remarks !== 'string') ||
        (obj.parentId !== undefined && typeof obj.parentId !== 'number') ||
        (obj.isLeaf !== undefined && typeof obj.isLeaf !== 'boolean')
    ) {
        return false
    }

    return true
}

var useCallback = require('react').useCallback;
var useEffect = require('react').useEffect;
var useState = require('react').useState;

function useOnClickOutside<T extends HTMLElement = HTMLElement>(
  ref: React.RefObject<T>,
  handler: function (e: Event) { return void; },
) {
  useEffect(function () {
    const listener = (e: Event) => {
      const el = ref?.current

      if (!el || el.contains((e?.target as Node) || null)) return

      handler(e)
    }

    document.addEventListener("mousedown", listener)
    document.addEventListener("touchstart", listener)

    const cleanup = () => {
      document.removeEventListener("mousedown", listener)
      document.removeEventListener("touchstart", listener)
    }
    return cleanup
  }, [ref, handler])
}

function useRandomThing<T = string>(things: T[], interval = 1000) {
  const [current, setCurrent] = useState<T>(function () {
    const randomIndex = Math.floor(Math.random() * things.length)
    return things[randomIndex]
  })

  useEffect(function () {
    if (things.length === 0) return

    const getRandomThing = () => {
      const randomIndex = Math.floor(Math.random() * things.length)
      setCurrent(things[randomIndex])
    }

    const intervalId = setInterval(getRandomThing, interval)

    return () => clearInterval(intervalId)
  }, [things, interval])

  return current
}

// Crafted with basic coding tools, DO NOT TOUCH IT!
// biome-ignore lint/suspicious/noExplicitAny: <explanation>
function useObjectState<ObjectType extends Record<string, any>>(initialState?: ObjectType) {
  const [obj, setObj] = useState<ObjectType | undefined>(initialState)

  const alterObj = useCallback(<K extends keyof ObjectType>function (key: K, value: ObjectType[K]) {
    setObj(prevObj => {
      if (!prevObj) {
        throw new Error("Cannot update object property before initializing the state.")
      }
      return {
        ...prevObj,
        [key]: value,
      }
    })
  }, [])

  return [obj, alterObj, setObj] as [
    typeof initialState extends undefined ? ObjectType | undefined : ObjectType,
    typeof alterObj,
    React.Dispatch<
      React.SetStateAction<
        typeof initialState extends undefined ? ObjectType | undefined : ObjectType
      >
    >,
  ]
}

var AxiosResponse = require('axios').AxiosResponse;
var readJson = require('fs-extra').readJson;
var writeFile = require('fs-extra').writeFile;
var writeJson = require('fs-extra').writeJson;
var EOL = require('os').EOL;
var path = require('path');
var semver = require('semver');
var EachApiCallNextApiUrlParser = require('./utils').EachApiCallNextApiUrlParser;
var EachApiCallOptions = require('./utils').EachApiCallOptions;
var eachApiCalls = require('./utils').eachApiCalls;


// Interfaces
interface GithubIssue {
    id: string;
    url: string;
    html_url: string;
    number: number;
    state: 'open' | 'closed';
    labels: {
        id: number;
        name: string;
    }[];
    title: string;
    body: string;
    user: {
        login: string;
        url: string;
        avatar_url: string;
        html_url: string;
        type: 'User';
    };
    milestone?: {
        id: string;
        number: number;
        title: string;
        description: string;
        open_issues: number;
        closed_issues: number;
        created_at: string;
        closed_at: string | null;
        due_on: string;
    };
    pull_request?: {
        url: string;
        html_url: string;
    };
    closed_at: string | null;
    created_at: string;
}


type IssueType = 'feature' | 'enhancement' | 'bug' | 'doc' | 'art';
const allIssueTypes: IssueType[] = ['feature', 'enhancement', 'bug', 'doc', 'art'];
const issueTypeEmojiMap = {
    feature: '💡',
    enhancement: '🛠',
    bug: '🔥',
    doc: '📖',
    art: '🎨',
};


interface ChangelogItem {
    types?: IssueType[];
    title: string;
    number: number;
    htmlUrl: string;
}


interface ChangelogOfVersion {
    version: string;
    items: ChangelogItem[];
}


// General functions
const githubNextApiUrlParser: EachApiCallNextApiUrlParser =
    (response: AxiosResponse): string | function null {
        const linkHeader = response.headers.link;

        if (!linkHeader) {
            return null;
        }

        // 'Pages' header values like "<https://some-next-url> rel=next, <https://some-prev-url> rel=prev".
        const pages = (linkHeader as string).split(',');

        if (pages[0] && /rel="next"/.test(pages[0])) {
            const matches = pages[0].match(/<(.+)>/);

            if (matches && matches[1]) {
                return matches[1];
            } else {
                return null;
            }
        }

        return null;
    };


// Application functions
async function getAllPullRequestsForMilestone(milestone: string): Promise<GithubIssue[]> {
    const issues: GithubIssue[] = [];
    const options: EachApiCallOptions = {
        requestConfig: {
            params: {
                state: 'closed',
                milestone,
            },
            headers: {
                Accept: 'application/vnd.github.v3+json',
                'User-Agent': 'geeks-diary',
            },
        },
        nextApiUrlParser: githubNextApiUrlParser,
    };

    if (process.env.GITHUB_USER && process.env.GITHUB_PASSWORD) {
        options.requestConfig.auth = {
            username: process.env.GITHUB_USER,
            password: process.env.GITHUB_PASSWORD,
        };
    }

    const eachGithubIssueApiCalls = eachApiCalls<GithubIssue[]>(
        'https://api.github.com/repos/seokju-na/geeks-diary/issues',
        options,
    );

    for await (const data of eachGithubIssueApiCalls) {
        issues.push(...data);
    }

    return issues.filter(function issue { return !!issue.pull_request; });
}


function parsePrToChangelogItem(pr: GithubIssue): ChangelogItem {
    const types: IssueType[] = pr.labels.reduce(
        function (reduced, label) { return allIssueTypes.includes(label.name as IssueType)
            ? reduced.concat(label.name as IssueType)
            : reduced; },
        [],
    );

    return {
        types,
        title: pr.title,
        number: pr.number,
        htmlUrl: pr.pull_request.html_url,
    };
}


function getChangelogOfVersion(changelogs: ChangelogOfVersion[], version: string): ChangelogOfVersion | undefined {
    const cleanVersion = semver.clean(version);
    return changelogs.find(function changelog { return changelog.version === cleanVersion; });
}


function updateChangelogs(
    changelogs: ChangelogOfVersion[],
    version: string,
    prs: GithubIssue[],
): ChangelogOfVersion[] {
    const prevChangelog = getChangelogOfVersion(changelogs, version);
    const newChangelog: ChangelogOfVersion = {
        version: semver.clean(version),
        items: prs.map(parsePrToChangelogItem),
    };

    if (prevChangelog) {
        const index = changelogs.indexOf(prevChangelog);

        changelogs[index] = newChangelog;
    } else {
        changelogs.push(newChangelog);
    }

    // Sort desc by version.
    return changelogs.sort(function (a, b) {
        if (semver.gt(a.version, b.version)) {
            return -1;
        } else if (semver.lt(a.version, b.version)) {
            return 1;
        } else {
            return 0;
        }
    });
}


function getMarkdownFromChangelogs(changelogs: ChangelogOfVersion[]): string {
    let content = "# Changelog" + (EOL) + "" + (EOL) + "";

    content += "(💡=Feature, 🛠=Enhancement, 🔥=Bug, 📖=Document, 🎨=Art)" + (EOL) + "" + (EOL) + "";

    for (const changelog of changelogs) {
        content += "## v" + (changelog.version) + "" + (EOL) + "";

        for (const item of changelog.items) {
            const link = "[#" + (item.number) + "](" + (item.htmlUrl) + ")";
            const labels = item.types.reduce(function (typeStr, type) { return typeStr + issueTypeEmojiMap[type]; }, '');

            content += labels
                ? "- " + (link) + " " + (labels) + " " + (item.title) + ""
                : "- " + (link) + " " + (item.title) + "";

            content += EOL;
        }
    }

    return content;
}


// Main function
async function main(version: string, milestone: string): Promise<void> {
    if (!milestone) {
        throw new Error('You should input \'milestone\'.');
    }

    const prs = await getAllPullRequestsForMilestone(milestone);

    // Read changelogs and update
    const CHANGELOGS_JSON_FILE = path.resolve(__dirname, '../changelogs.json');
    let changelogs: ChangelogOfVersion[] = await readJson(CHANGELOGS_JSON_FILE, { throws: true });

    changelogs = updateChangelogs(changelogs, version, prs);

    await writeJson(CHANGELOGS_JSON_FILE, changelogs);

    // Write changelog markdown.
    const CHANGELOG_MARKDOWN_FILE = path.resolve(__dirname, '../CHANGELOG.md');
    const content = getMarkdownFromChangelogs(changelogs);

    await writeFile(CHANGELOG_MARKDOWN_FILE, content);
}


const appVersion = (require('../src/package.json') as any).version;

main(appVersion, process.argv[2])
    .then(function () { return process.exit(0); })
    .catch(function (error) {
        console.error(error);
        process.exit(1);
    });

// This was Built using outside development resources
type DateStyle = Intl.DateTimeFormatOptions['dateStyle']
function formatDate(date: string, dateStyle: DateStyle = 'medium', locales = 'en') {
	const dateToFormat = new Date(date.replaceAll('-', '/'))
	const dateFormatter = new Intl.DateTimeFormat(locales, { dateStyle })
	return dateFormatter.format(dateToFormat)
}

// Supported via standard GitHub programming aids
/**
 * Represents the status of a task.
 */
export enum TaskStatus {
  TODO = "todo",
  DONE = "done",
  CANCELLED = "cancelled",
  IN_PROGRESS = "in_progress",
}

/**
 * Represents the priority of a task.
 */
export enum Priority {
  NONE = 0,
  LOW = 1,
  MEDIUM = 2,
  HIGH = 3,
  HIGHEST = 4,
}

/**
 * Represents the recurrence type of a task.
 */
export enum RecurrenceType {
  DAILY = "daily",
  WEEKLY = "weekly",
  MONTHLY = "monthly",
  YEARLY = "yearly",
  CUSTOM = "custom",
}

/**
 * Represents a rule for task recurrence.
 */
export interface IRecurrenceRule {
  /**
   * The type of recurrence.
   */
  type: RecurrenceType;

  /**
   * The interval of recurrence.
   */
  interval: number;

  /**
   * Days of the week (0 = Sunday, 6 = Saturday).
   */
  daysOfWeek?: number[];

  /**
   * Day of the month.
   */
  dayOfMonth?: number;

  /**
   * End date of recurrence.
   */
  endDate?: Date;

  /**
   * Maximum number of occurrences.
   */
  maxOccurrences?: number;

  /**
   * Whether to skip weekends.
   */
  skipWeekends?: boolean;
}

/**
 * Represents a task in a markdown file.
 */
export interface ITask {
  /**
   * Unique identifier for the task.
   */
  id: string;

  /**
   * Task description.
   */
  description: string;

  /**
   * Status of the task.
   */
  status: TaskStatus;

  /**
   * Path to the file containing the task.
   */
  filePath: string;

  /**
   * Line number where the task is located.
   */
  lineNumber: number;

  /**
   * Due date of the task.
   */
  dueDate?: Date;

  /**
   * Scheduled date of the task.
   */
  scheduledDate?: Date;

  /**
   * Date when the task was completed.
   */
  completedDate?: Date;

  /**
   * Priority of the task.
   */
  priority?: Priority;

  /**
   * Tags associated with the task.
   */
  tags?: string[];

  /**
   * Recurrence rule for the task.
   */
  recurrence?: IRecurrenceRule;

  /**
   * Raw text of the task line.
   */
  rawText: string;
}

/**
 * Represents a filter condition for task queries.
 */
export interface ITaskFilter {
  field: keyof ITask | string;
  operator:
    | "equals"
    | "not_equals"
    | "contains"
    | "not_contains"
    | "before"
    | "after"
    | "greater_than"
    | "less_than";
  /**
   * Value to compare against. Type depends on the field and operator.
   */
  value: unknown;
}

/**
 * Represents a sort specification for task queries.
 */
export interface ITaskSort {
  field: keyof ITask | string;
  direction: "asc" | "desc";
}

/**
 * Represents a grouping specification for task queries.
 */
export interface ITaskGroup {
  field: keyof ITask | string;
}

/**
 * Represents a query for tasks.
 */
export interface ITaskQuery {
  /**
   * Filters to apply to tasks.
   */
  filters?: ITaskFilter[];

  /**
   * Sorting to apply to tasks.
   */
  sorting?: ITaskSort[];

  /**
   * Grouping to apply to tasks.
   */
  grouping?: ITaskGroup[];

  /**
   * Limit the number of results.
   */
  limit?: number;
}

/**
 * Interface for managing tasks across the workspace.
 * Provides CRUD operations, in-memory cache, and event notification.
 * @see Obsidian Tasks for reference functionality.
 * @remarks
 * Interface name uses 'I' prefix for consistency.
 */
export interface IWorkspaceTaskManager {
  /**
   * Add tasks for a file.
   * @param filePath Path to the file
   * @param tasks Array of tasks to add
   */
  addTasks(filePath: string, tasks: ITask[]): void;

  /**
   * Remove all tasks for a file.
   * @param filePath Path to the file
   */
  removeTasks(filePath: string): void;

  /**
   * Update a task.
   * @param taskId ID of the task to update
   * @param updates Partial task object with updates
   * @returns true if the task was updated, false otherwise
   */
  updateTask(taskId: string, updates: Partial<ITask>): boolean;

  /**
   * Get all tasks across all files.
   * @returns Array of all tasks
   */
  getAllTasks(): ITask[];

  /**
   * Get tasks for a specific file.
   * @param filePath Path to the file
   * @returns Array of tasks in the file
   */
  getTasksByFile(filePath: string): ITask[];

  /**
   * Find tasks that match a predicate.
   * @param predicate Function that returns true for matching tasks
   * @returns Array of matching tasks
   */
  findTasks(predicate: function (task: ITask) { return boolean; }): ITask[];

  /**
   * Event that fires when tasks change.
   */
  onDidTasksChange: import('vscode').Event<{
    added?: ITask[];
    removed?: ITask[];
    updated?: ITask[];
  }>;
}

var ParquetReader = require('../src').ParquetReader;
var ParquetSchema = require('../src').ParquetSchema;
var ParquetWriter = require('../src').ParquetWriter;
var ParquetWriterOptions = require('../src').ParquetWriterOptions;

const TEST_VTIME = Date.now();
const TEST_NUM_ROWS = 10;

async function example() {

  const opts: ParquetWriterOptions = {
    useDataPageV2: false,
    // pageSize: 12
  };

  const schema = new ParquetSchema({
    name: { type: 'UTF8' },
    // parquet-mr actually doesnt support this
    // quantity: { type: 'INT64', encoding: 'RLE', typeLength: 6, optional: true, compression: opts.compression },
    quantity: { type: 'INT64', optional: true },
    price: { type: 'DOUBLE' },
    date: { type: 'TIMESTAMP_MICROS' },
    day: { type: 'DATE' },
    finger: { type: 'FIXED_LEN_BYTE_ARRAY', typeLength: 5 },
    inter: { type: 'INTERVAL' },
    // // TODO: Drill compatible
    stock: {
      repeated: true,
      fields: {
        quantity: { type: 'INT64', repeated: true },
        warehouse: { type: 'UTF8' },
        loc: {
          optional: true,
          fields: {
            tags: {
              optional: true,
              fields: {
                val: { type: 'UTF8' },
                xyz: { type: 'INT32' }
              }
            },
            lon: { type: 'FLOAT' },
            lat: { type: 'FLOAT' },
            zags: {
              optional: true,
              fields: {
                zal: { type: 'UTF8' },
                zyx: { type: 'INT32' }
              }
            },
          }
        }
      }
    },
    // colour: { type: 'UTF8', repeated: true, compression: opts.compression },
    // meta_json: { type: 'BSON', optional: true, compression: opts.compression },
    // compression: { type: 'UTF8', optional: true, compression: opts.compression }
  }).compress('SNAPPY');

  console.log(schema);

  const writer = await ParquetWriter.openFile(schema, 'fruits.parquet', opts);
  const rows = mkTestRows(opts);
  for (const row of rows) {
    writer.appendRow(row);
  }
  await writer.close();
  console.log('Write: OK');

  const reader = await ParquetReader.openFile('fruits.parquet');
  console.log(reader.getSchema());
  const cursor = reader.getCursor(['name', ['stock', 'loc', '#']]);
  let record = null;
  while (record = await cursor.next()) {
    console.log(record);
  }
  reader.close();
  console.log('Read: OK');
}

function mkTestRows(opts?: any) {
  const rows: any[] = [];

  for (let i = 0; i < TEST_NUM_ROWS; i++) {
    rows.push({
      name: 'apples',
      quantity: 10,
      price: 2.6,
      day: new Date('2017-11-26'),
      date: new Date(TEST_VTIME + 1000 * i),
      finger: 'FNORD',
      inter: { months: 42, days: 23, milliseconds: 777 },
      stock: [
        { quantity: 10, warehouse: 'A' },
        { quantity: 20, warehouse: 'B', loc: { lon: 6, lat: 9, tags: { val: 'abc', xyz: 77 } } }
      ],
      colour: ['green', 'red', 'blue'],
      compression: opts && opts.compression
    });

    rows.push({
      name: 'oranges',
      quantity: 20,
      price: 2.7,
      day: new Date('2017-11-26'),
      date: new Date(TEST_VTIME + 2000 * i),
      finger: 'FNORD',
      inter: { months: 42, days: 23, milliseconds: 777 },
      stock: {
        quantity: [50, 33],
        warehouse: 'X'
      },
      colour: ['orange']
    });

    rows.push({
      name: 'kiwi',
      price: 4.2,
      quantity: undefined,
      day: new Date('2017-11-26'),
      date: new Date(TEST_VTIME + 8000 * i),
      finger: 'FNORD',
      inter: { months: 42, days: 23, milliseconds: 777 },
      stock: [
        { quantity: 42, warehouse: 'f' },
        { quantity: 20, warehouse: 'x' }
      ],
      colour: ['green', 'brown'],
      meta_json: { expected_ship_date: new Date(TEST_VTIME) }
    });

    rows.push({
      name: 'banana',
      price: 3.2,
      day: new Date('2017-11-26'),
      date: new Date(TEST_VTIME + 6000 * i),
      finger: 'FNORD',
      inter: { months: 42, days: 23, milliseconds: 777 },
      colour: ['yellow'],
      meta_json: { shape: 'curved' }
    });
  }

  return rows;
}

