  ByteArray,
  crypto,
} from '@graphprotocol/graph-ts'

// Import event types from the registry contract ABI
var AuctionStarted = require('./types/AuctionRegistrar/AuctionRegistrar').AuctionStarted;
var NewBid = require('./types/AuctionRegistrar/AuctionRegistrar').NewBid;
var BidRevealed = require('./types/AuctionRegistrar/AuctionRegistrar').BidRevealed;
var HashRegistered = require('./types/AuctionRegistrar/AuctionRegistrar').HashRegistered;
var HashReleased = require('./types/AuctionRegistrar/AuctionRegistrar').HashReleased;
var HashInvalidated = require('./types/AuctionRegistrar/AuctionRegistrar').HashInvalidated;

// Import entity types generated from the GraphQL schema
var Account = require('./types/schema').Account;
var AuctionedName = require('./types/schema').AuctionedName;

var rootNode:ByteArray = byteArrayFromHex("93cdeb708b7545dc668eb9280176169d1c33cfd8ed6f04690a0bcc88a93fc4ae")

function auctionStarted(event: AuctionStarted): void {
  var auction = new AuctionedName(event.params.hash.toHex())

  auction.registrationDate = event.params.registrationDate.toI32()
  auction.bidCount = 0
  auction.maxBid = null
  auction.secondBid = null
  auction.state = "AUCTION"
  auction.save()
}

function bidRevealed(event: BidRevealed): void {
  if(event.params.status == 5) {
    // Actually a cancelled bid; hash is not the label hash
    return
  }

  var auction = AuctionedName.load(event.params.hash.toHex())
  switch(event.params.status) {
    case 0: // Harmless invalid bid
    case 1: // Bid revealed late
      break;
    case 4: // Bid lower than second bid
      auction.bidCount += 1
      break;
    case 2: // New winning bid
      var account = Account.load(event.params.owner.toHex())
      if (account == null){
        account = new Account(event.params.owner.toHex())
        account.domainCount = 0
      }
      account.save()

      auction.secondBid = auction.maxBid
      auction.maxBid = event.params.value
      auction.winningBidder = account.id
      auction.bidCount += 1
      break;
    case 3: // Runner up bid
      auction.secondBid = event.params.value
      auction.bidCount += 1
      break;
  }
  auction.save()
}

function hashRegistered(event: HashRegistered): void {
  var auction = new AuctionedName(event.params.hash.toHex())
  auction.secondBid = event.params.value
  auction.winningBidder = event.params.owner.toHex()
  auction.registrationDate = event.params.registrationDate.toI32()
  auction.domain = crypto.keccak256(concat(rootNode, event.params.hash)).toHex();
  auction.state = "FINALIZED"
  auction.save()
}

function hashReleased(event: HashReleased): void {
  var auction = new AuctionedName(event.params.hash.toHex())
  auction.releaseDate = event.block.timestamp.toI32()
  auction.state = "RELEASED"
  auction.save()
}

function hashInvalidated(event: HashInvalidated): void {
  var auction = new AuctionedName(event.params.hash.toHex())
  auction.state = "FORBIDDEN"
  auction.save()
}

// Helper for concatenating two byte arrays
function concat(a: ByteArray, b: ByteArray): ByteArray {
  var out = new Uint8Array(a.length + b.length)
  for (var i = 0; i < a.length; i++) {
    out[i] = a[i]
  }
  for (var j = 0; j < b.length; j++) {
    out[a.length + j] = b[j]
  }
  return out as ByteArray
}

function byteArrayFromHex(s: string): ByteArray {
  if(s.length % 2 !== 0) {
    throw new TypeError("Hex string must have an even number of characters")
  }
  var out = new Uint8Array(s.length / 2)
  for(var i = 0; i < s.length; i += 2) {
    out[i / 2] = parseInt(s.substring(i, i + 2), 16) as u32
  }
  return out as ByteArray;
}

