'use strict';
// The module 'vscode' contains the VS Code extensibility API
// Import the module and reference it with the alias vscode in your code below
var vscode = require('vscode');
var sortInsideEditor = require('./sortInsideEditor');
var sortOnSave = require('./sortOnSave');
var shouldSortOnSave = require('./options').shouldSortOnSave;
var shouldEnableJavascript = require('./options').shouldEnableJavascript;

var sortOnSaveDisposer: vscode.Disposable;

// this method is called when your extension is activated
// your extension is activated the very first time the command is executed
function activate(context: vscode.ExtensionContext) {

    // The command has been defined in the package.json file
    // Now provide the implementation of the command with  registerCommand
    // The commandId parameter must match the command field in package.json
    var sortOnCommandDisposer = vscode.commands.registerCommand('extension.sortTypescriptImports', function () {
        // The code you place here will be executed every time your command is executed

        if (shouldEnableJavascript() && isFileJavascript() ||
            isFileTypescript()) {
            sortInsideEditor();
        }
    });

    var configurationWatcher = vscode.workspace.onDidChangeConfiguration(configure);
    configure();

    context.subscriptions.push(
        sortOnCommandDisposer,
        configurationWatcher);
}

function isFileJavascript() {
    return (
        vscode.window.activeTextEditor.document.languageId === 'javascript' ||
        vscode.window.activeTextEditor.document.languageId === 'javascriptreact'
    );
}

function isFileTypescript() {
    return (
        vscode.window.activeTextEditor.document.languageId === 'typescript' ||
        vscode.window.activeTextEditor.document.languageId === 'typescriptreact'
    );
}

function configure() {
    if (shouldSortOnSave()) {
        enableFileWatcher();
    } else if (!shouldSortOnSave()) {
        disableFileWatcher();
    }
}

function enableFileWatcher() {
    if (!sortOnSaveDisposer) {
        sortOnSaveDisposer = vscode.workspace.onWillSaveTextDocument(sortOnSave);
    }
}

function disableFileWatcher() {
    if (sortOnSaveDisposer) {
        sortOnSaveDisposer.dispose();
        sortOnSaveDisposer = undefined;
    }
}

// this method is called when your extension is deactivated
function deactivate() {
    disableFileWatcher();
}

var metroResolver = require('metro-resolver');
var loadConfig = require('tsconfig-paths').loadConfig;
var createMatchPath = require('tsconfig-paths').createMatchPath;
var parse = require('path').parse;
var join = require('path').join;

function resolveRequest(
  _context: any,
  moduleName: string,
  platform: string | null
) {
  var resolveRequest = _context.resolveRequest;

  try {
    return metroResolver.resolve(context, moduleName, platform);
  } catch {
    // ignore
  }

  const matcher = getMatcher();
  const match = matcher(moduleName);
  if (match) {
    return {
      type: 'sourceFile',
      filePath: match,
    };
  } else {
    // Resolve as a normal asset
    const parsedPath = parse(context.originModulePath);
    const filePath = join(parsedPath.dir, moduleName);
    return {
      type: 'sourceFile',
      filePath,
    };
  }
}

let matcher: MatchPath;
function getMatcher() {
  if (!matcher) {
    const result = loadConfig();
    if (result.resultType === 'success') {
      var absoluteBaseUrl = result.absoluteBaseUrl;
var paths = result.paths;
      matcher = createMatchPath(absoluteBaseUrl, paths);
    } else {
      throw new Error("Could not load tsconfig for project");
    }
  }
  return matcher;
}

