// 在方法体中处理可选参数未填的情况

// rest spread
// 任意数量的方法参数
// 收集，展开

// 可以传入任意数量参数的方法
function bar(...args) {
  args.forEach(function arg {
    console.log(arg);
  });
}
bar(1, 2, 3);

// function foo(a, b) {
