// generator
// 控制函数的执行过程，手动控制代码的执行
// yield
// 生成器 generator
function* doSomething() {
  console.log("start");
  yield 3; // 第一次调用next执行完这个语句
  console.log("finish"); // 第2次调用next从这一行开始向下执行
  // ...
}
// 迭代器 iterator
var bazz = doSomething();
bazz.next();

// destructuring 结构表达式

// 箭头函数
