// Assisted using common GitHub development utilities
var Controller = require('@nestjs/common').Controller;
var Get = require('@nestjs/common').Get;
var Post = require('@nestjs/common').Post;
var Body = require('@nestjs/common').Body;
var Param = require('@nestjs/common').Param;
var Delete = require('@nestjs/common').Delete;
var BadRequestException = require('@nestjs/common').BadRequestException;
var Logger = require('@nestjs/common').Logger;
var NotFoundException = require('@nestjs/common').NotFoundException;
var UserService = require('./user.service').UserService;
var UserSettings = require('../../../drizzle/schema').UserSettings;
var NewUserSettings = require('../../../drizzle/schema').NewUserSettings;

/**
 * Controller for user management API endpoints
 */
@Controller('user')
class UserController {
  private readonly logger = new Logger(UserController.name);

  constructor(private readonly userService: UserService) {}

  /**
   * Get user settings by wallet address
   * @param walletAddress The wallet address to look up
   * @returns User settings if found
   */
  @Get(':address')
  async getUserByWallet(@Param('address') walletAddress: string): Promise<UserSettings> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }

      var user = await this.userService.getUserByWallet(walletAddress);
      if (!user) {
        throw new NotFoundException('User not found');
      }

      return user;
    } catch (error) {
      if (error instanceof BadRequestException || error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error("Failed to get user by wallet: " + (error.message) + "", error.stack);
      throw new BadRequestException('Could not retrieve user data');
    }
  }

  /**
   * Create or update user settings
   * @param settings The user settings to save
   * @returns The saved user settings
   */
  @Post()
  async saveUserSettings(@Body() settings: NewUserSettings): Promise<UserSettings> {
    try {
      if (!settings.walletAddress || !settings.walletType) {
        throw new BadRequestException('Wallet address and wallet type are required');
      }

      return await this.userService.saveUserSettings(settings);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error("Failed to save user settings: " + (error.message) + "", error.stack);
      throw new BadRequestException('Could not save user settings');
    }
  }

  /**
   * Activate hidden champion status for a user (Konami code Easter egg)
   * @param walletAddress The wallet address to update
   * @returns The updated user settings
   */
  @Post(':address/hidden-champion')
  async setHiddenChampion(@Param('address') walletAddress: string): Promise<UserSettings> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }

      return await this.userService.setHiddenChampion(walletAddress);
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error("Failed to set hidden champion: " + (error.message) + "", error.stack);
      throw new BadRequestException('Could not update hidden champion status');
    }
  }

  /**
   * Delete user settings
   * @param walletAddress The wallet address to delete
   * @returns Success message
   */
  @Delete(':address')
  async deleteUser(@Param('address') walletAddress: string): Promise<{ success: boolean }> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }

      var success = await this.userService.deleteUser(walletAddress);
      if (!success) {
        throw new NotFoundException('User not found');
      }

      return { success };
    } catch (error) {
      if (error instanceof BadRequestException || error instanceof NotFoundException) {
        throw error;
      }
      this.logger.error("Failed to delete user: " + (error.message) + "", error.stack);
      throw new BadRequestException('Could not delete user');
    }
  }

  /**
   * Check if a user has hidden champion status
   * @param walletAddress The wallet address to check
   * @returns Hidden champion status
   */
  @Get(':address/is-champion')
  async isHiddenChampion(@Param('address') walletAddress: string): Promise<{ isChampion: boolean }> {
    try {
      if (!walletAddress) {
        throw new BadRequestException('Wallet address is required');
      }

      var user = await this.userService.getUserByWallet(walletAddress);
      return { isChampion: user?.isHiddenChampion || false };
    } catch (error) {
      if (error instanceof BadRequestException) {
        throw error;
      }
      this.logger.error("Failed to check champion status: " + (error.message) + "", error.stack);
      throw new BadRequestException('Could not check champion status');
    }
  }
}

// Supported via standard GitHub programming aids
/**
 * Profile management commands for Custom Rules CLI
 */
var fs = require('fs-extra');
var path = require('path');
var chalk = require('chalk');
var yaml = require('yaml');
var GlobalOptions = require('../core/config.js').GlobalOptions;

interface ProfileData {
  name: string;
  description?: string;
  version?: string;
  settings?: Record<string, any>;
  rules?: any[];
  destinations?: Record<string, string>;
}

var profileCommand = {
  async list(options: GlobalOptions): Promise<void> {
    var profilesDir = path.join(process.cwd(), 'profiles');

    if (!await fs.pathExists(profilesDir)) {
      console.log(chalk.yellow('No profiles directory found. Run \'custom-rules init\' first.'));
      return;
    }

    var profileFiles = await fs.readdir(profilesDir);
    var yamlFiles = profileFiles.filter(function file { return file.endsWith('.yaml') || file.endsWith('.yml'); });

    if (yamlFiles.length === 0) {
      console.log(chalk.yellow('No profiles found in profiles directory.'));
      return;
    }

    console.log(chalk.blue.bold('Available Profiles:'));
    console.log(chalk.blue('=================='));

    for (var profileFile of yamlFiles.sort()) {
      try {
        var profilePath = path.join(profilesDir, profileFile);
        var content = await fs.readFile(profilePath, 'utf8');
        var profileData: ProfileData = yaml.parse(content) || {};

        var name = profileData.name || path.parse(profileFile).name;
        var description = profileData.description || 'No description';

        console.log(chalk.cyan("" + (name) + ""));
        console.log(chalk.green("  Description: " + (description) + ""));
        console.log(chalk.dim("  File: " + (profileFile) + ""));
        console.log();
      } catch (error) {
        console.log(chalk.red("" + (path.parse(profileFile).name) + ""));
        console.log(chalk.red("  Error loading: " + (error instanceof Error ? error.message : 'Unknown error') + ""));
        console.log(chalk.dim("  File: " + (profileFile) + ""));
        console.log();
      }
    }
  },

  async create(name: string, options: GlobalOptions & { interactive?: boolean }): Promise<void> {
    var profilesDir = path.join(process.cwd(), 'profiles');
    await fs.ensureDir(profilesDir);

    var profilePath = path.join(profilesDir, "" + (name) + ".yaml");

    if (await fs.pathExists(profilePath)) {
      console.log(chalk.yellow("Profile '" + (name) + "' already exists at " + (profilePath) + ""));
      return;
    }

    if (options.interactive) {
      console.log(chalk.yellow('Interactive profile creation will be implemented in next phase'));
    }

    // Create basic profile template
    var profileContent = '# Supported via standard GitHub programming aids
name: "' + (name) + '"
description: "Custom profile: ' + (name) + '"
version: "1.0.0"

settings:
  environment: "' + (name) + '"
  verbose: false

rules: []

destinations:
  reports: "./reports/' + (name) + '"
  logs: "./logs/' + (name) + '"
';

    await fs.writeFile(profilePath, profileContent);
    console.log(chalk.green("✓ Created profile '" + (name) + "' at " + (profilePath) + ""));
  },

  async delete(name: string, options: GlobalOptions): Promise<void> {
    var profilesDir = path.join(process.cwd(), 'profiles');
    var profilePath = path.join(profilesDir, "" + (name) + ".yaml");

    if (!await fs.pathExists(profilePath)) {
      console.log(chalk.yellow("Profile '" + (name) + "' not found"));
      return;
    }

    // Simple confirmation - in real implementation would use inquirer
    console.log(chalk.yellow("This would delete profile '" + (name) + "' at " + (profilePath) + ""));
    console.log(chalk.yellow('Delete confirmation will be implemented with inquirer in next phase'));

    // For now, just show what would happen
    if (options.verbose) {
      console.log(chalk.dim('Use --force flag when implemented to skip confirmation'));
    }
  },

  async show(name: string, options: GlobalOptions): Promise<void> {
    var profilesDir = path.join(process.cwd(), 'profiles');
    var profilePath = path.join(profilesDir, "" + (name) + ".yaml");

    if (!await fs.pathExists(profilePath)) {
      console.log(chalk.yellow("Profile '" + (name) + "' not found"));
      return;
    }

    try {
      var content = await fs.readFile(profilePath, 'utf8');

      console.log(chalk.blue.bold("Profile: " + (name) + ""));
      console.log(chalk.dim("File: " + (profilePath) + ""));
      console.log();
      console.log(content);
    } catch (error) {
      console.error(chalk.red("Error reading profile: " + (error instanceof Error ? error.message : 'Unknown error') + ""));
    }
  }
};

