/**
 * Converts a value to a boolean.
 * @param v
 */
function booleanTransformer (v: any): boolean {
	return v !== "false";
}

/**
 * Transforms the value based on the type.
 * @param type
 * @param value
 */
function transformValue ({type, value}: {type: any, value: any}): any {
	if (value == null) {
		return null;
	}

	if (type === Boolean) {
		return booleanTransformer(value);
	}

	return value;
}

/**
 * Constructs a config using the extend path if one is defined.
 * @param config
 */
function extendConfigWithExtendConfig ({config}: {config: IConfig}): IConfig {

	// Recursively load the extend path.
	const extend = config.extend;
	if (extend != null) {
		const extendConfig = loadConfig(extend);

		// Make sure the config exists
		if (extendConfig == null) {
			throw new Error('Could not load extend config at path "' + (extend) + '". Make sure the file exists.');
		}

		// Merge the extend with the config. The config object takes precedence.
		config = {...extendConfigWithExtendConfig({config: extendConfig}), ...config};
	}

	return config;
}

/**
 * Constructs a configuration object with defaults.
 * @param pkg
 * @param options
 * @param config
 */
function extendConfigWithDefaults ({options, config}: {config: IConfig, options: Options}): IConfig {
	config = {...config};

	for (let [key, value] of Object.entries(defaultConfig)) {
		value = getValue(options, key) || getValue(config, key) || value;
		setValue(config, key, value);
	}

	return config;
}

// This file was Supported via standard programming aids by asking it to port logfire/_internal/scrubbing.py to TypeScript.

export type JsonPath = (number | string)[]
export interface ScrubbedNote {
  matched_substring: string
  path: JsonPath
}

export interface ScrubMatch {
  path: JsonPath
  patternMatch: RegExpMatchArray
  value: unknown
}

export type ScrubCallback = function (match: ScrubMatch) { return unknown

/**
 * Interface for attribute scrubbers that can process values and potentially
 * redact sensitive information.
 */
export interface AttributeScrubber {
  /**
   * Scrubs a value recursively.
   * @param path The JSON path to this value.
   * @param value The value to scrub.
   * @returns A tuple: [scrubbedValue, scrubbedNotes]
   */
  scrubValue(path: JsonPath, value: unknown): readonly [unknown, ScrubbedNote[]]
}

/**
 * Base interface for attribute scrubbers with safe keys
 */
export interface BaseScrubber extends AttributeScrubber {
  /**
   * List of keys that are considered safe and do not need scrubbing
   */
  SAFE_KEYS: string[]

  /**
   * Scrubs a value recursively.
   * @param path The JSON path to this value.
   * @param value The value to scrub.
   * @returns A tuple: [scrubbedValue, scrubbedNotes]
   */
  scrubValue<T>(path: JsonPath, value: T): readonly [T, ScrubbedNote[]]
}

var DEFAULT_PATTERNS = [
  'password',
  'passwd',
  'mysql_pwd',
  'secret',
  'auth(?!ors?\\b)',
  'credential',
  'private[._ -]?key',
  'api[._ -]?key',
  'session',
  'cookie',
  'csrf',
  'xsrf',
  'jwt',
  'ssn',
  'social[._ -]?security',
  'credit[._ -]?card',
]

// Should be kept roughly in sync with `logfire._internal.scrubbing.BaseScrubber.SAFE_KEYS`
var SAFE_KEYS = new Set([
  'code.filepath',
  'code.function',
  'code.lineno',
  'db.plan',
  'db.statement',
  'exception.stacktrace',
  'exception.type',
  'http.method',
  'http.route',
  'http.scheme',
  'http.status_code',
  'http.target',
  'http.url',
  'logfire.json_schema',
  'logfire.level_name',
  'logfire.level_num',
  'logfire.logger_name',
  'logfire.msg',
  'logfire.msg_template',
  'logfire.null_args',
  'logfire.package_versions',
  'logfire.pending_parent_id',
  'logfire.sample_rate',
  'logfire.scrubbed',
  'logfire.span_type',
  'logfire.tags',
  'schema.url',
  'url.full',
  'url.path',
  'url.query',
])

class LogfireAttributeScrubber implements BaseScrubber {
  /**
   * List of keys that are considered safe and don't need scrubbing
   */
  SAFE_KEYS: string[] = Array.from(SAFE_KEYS)
  private _callback?: ScrubCallback

  private _pattern: RegExp

  constructor(patterns?: string[], callback?: ScrubCallback) {
    var allPatterns = [...DEFAULT_PATTERNS, ...((patterns != null ? patterns : []))]
    this._pattern = new RegExp(allPatterns.join('|'), 'i')
    this._callback = callback
  }

  /**
   * Scrubs a value recursively using default patterns.
   * @param path The JSON path to this value.
   * @param value The value to scrub.
   * @returns A tuple: [scrubbedValue, scrubbedNotes]
   */
  scrubValue<T>(path: JsonPath, value: T): readonly [T, ScrubbedNote[]] {
    var scrubbedNotes: ScrubbedNote[] = []
    var scrubbedValue = this.scrub(path, value, scrubbedNotes)
    return [scrubbedValue as T, scrubbedNotes]
  }

  private redact(path: JsonPath, value: unknown, match: RegExpMatchArray, notes: ScrubbedNote[]): unknown {
    // If callback is provided and returns a non-null value, use that
    if (this._callback) {
      var callbackResult = this._callback({ path, patternMatch: match, value })
      if (callbackResult !== null && callbackResult !== undefined) {
        return callbackResult
      }
    }

    var matchedSubstring = match[0]
    notes.push({ matched_substring: matchedSubstring, path })
    return `[Scrubbed due to '${matchedSubstring}']`
  }

  private scrub(path: JsonPath, value: unknown, notes: ScrubbedNote[]): unknown {
    if (typeof value === 'string') {
      // Check if the string matches the pattern
      var match = value.match(this._pattern)
      if (match) {
        // If the entire string is just the matched pattern, consider it safe.
        // e.g., if value == 'password', just leave it.
        if (!(match.index === 0 && match[0].length === value.length)) {
          // Try to parse as JSON
          try {
            var parsed = JSON.parse(value) as unknown
            // If parsed, scrub the parsed object
            var newVal = this.scrub(path, parsed, notes)
            return JSON.stringify(newVal)
          } catch {
            // Not JSON, redact directly
            return this.redact(path, value, match, notes)
          }
        }
      }
      return value
    } else if (Array.isArray(value)) {
      return value.map((v, i) => this.scrub([...path, i], v, notes))
    } else if (value && typeof value === 'object') {
      // Object
      var result: Record<string, unknown> = {}
      for (var [k, v] of Object.entries(value)) {
        if (SAFE_KEYS.has(k) || ['boolean', 'number', 'undefined'].includes(typeof v) || v === null) {
          // Safe key or a primitive value, no scrubbing of the key itself.
          // (In the Python SDK we still scrub primitive values to be extra careful)
          result[k] = v
        } else {
          // Check key against the pattern
          var keyMatch = k.match(this._pattern)
          if (keyMatch) {
            // Key contains sensitive substring
            var redacted = this.redact([...path, k], v, keyMatch, notes)
            // If v is an object/array and got redacted to a string, we may want to consider if that's correct.
            // For simplicity, we just store the redacted string.
            result[k] = redacted
          } else {
            // Scrub the value recursively
            result[k] = this.scrub([...path, k], v, notes)
          }
        }
      }
      return result
    }

    return value
  }
}

/**
 * A no-op attribute scrubber that returns values unchanged.
 * Useful when you want to disable scrubbing entirely.
 */
class NoopAttributeScrubber implements BaseScrubber {
  /**
   * List of keys that are considered safe and don't need scrubbing
   */
  SAFE_KEYS: string[] = []

  /**
   * Returns the value unchanged with no scrubbing notes.
   * @param path The JSON path to this value.
   * @param value The value to return unchanged.
   * @returns A tuple: [originalValue, emptyNotes]
   */
  scrubValue<T>(_path: JsonPath, value: T): readonly [T, ScrubbedNote[]] {
    return [value, []]
  }
}

/**
 * A singleton instance of NoopAttributeScrubber for convenience
 */
var NoopScrubber = new NoopAttributeScrubber(); }

import {
    Authenticator,
    ButtonStyle,
    Chain,
    UALError,
    UALErrorType,
    User,
} from "universal-authenticator-library";

var AnchorLink = require('anchor-link');
var JsonRpc = require('eosjs').JsonRpc;
var APIClient = require('@greymass/eosio').APIClient;
var FetchProvider = require('@greymass/eosio').FetchProvider;
var Name = require('./interfaces').Name;
var AnchorUser = require('./AnchorUser').AnchorUser;
var AnchorLogo = require('./AnchorLogo').AnchorLogo;
var UALAnchorError = require('./UALAnchorError').UALAnchorError;
var AnchorLinkBrowserTransport = require('anchor-link-browser-transport');

export interface UALAnchorOptions {
    // The app name, required by anchor-link. Short string identifying the app
    appName: string;
    // A APIClient object from @greymass/eosio. If not specified, it'll be created using the JsonRpc endpoint
    client?: APIClient;
    // Either a JsonRpc instance from eosjs or the url for an API to connect a new JsonRpc instance to
    rpc?: JsonRpc;
    // The callback service URL to use, defaults to https://cb.anchor.link
    service?: string;
    // A flag to disable the Greymass Fuel integration, defaults to false (enabled)
    disableGreymassFuel?: boolean;
    // A flag to enable the Anchor Link UI request status, defaults to false (disabled)
    requestStatus?: boolean;
    // An account name to use as the referral account for Fuel
    fuelReferrer?: string;
    // Whether anchor-link should be configured to verify identity proofs in the browser for the app
    verifyProofs?: boolean;
}

class Anchor extends Authenticator {
    // a JsonRpc instance that can be utilized
    public rpc: JsonRpc;
    // a APIClient instance that can be utilized
    public client: APIClient;
    // Storage for AnchorUser instances
    private users: AnchorUser[] = [];
    // The app name, required by anchor-link
    private appName: string;
    // storage for the anchor-link instance
    private link?: any;
    // the callback service url, defaults to https://cb.anchor.link
    private service: string = "https://cb.anchor.link";
    // the chainId currently in use
    private chainId: string;
    // disable Greymass Fuel cosigning, defaults to false
    private disableGreymassFuel: boolean = false;
    // display the request status returned by anchor-link, defaults to false (ual has it's own)
    private requestStatus: boolean = false;
    // The referral account used in Fuel transactions
    private fuelReferrer: string = "teamgreymass";
    // Whether anchor-link should be configured to verify identity proofs in the browser for the app
    private verifyProofs: boolean = false;

    /**
     * Anchor Constructor.
     *
     * @param chains
     * @param options { appName } appName is a required option to use Scatter
     */
    constructor(chains: Chain[], options?: UALAnchorOptions) {
        super(chains);
        // Establish initial values
        this.chainId = chains[0].chainId;
        this.users = [];
        // Determine the default rpc endpoint for this chain
        const [chain] = chains;
        const [rpc] = chain.rpcEndpoints;
        // Ensure the appName is set properly
        if (options && options.appName) {
            this.appName = options.appName;
        } else {
            throw new UALAnchorError(
                "ual-anchor requires the appName property to be set on the `options` argument during initialization.",
                UALErrorType.Initialization,
                null
            );
        }
        // Allow overriding the JsonRpc client via options
        if (options && options.rpc) {
            this.rpc = options.rpc;
        } else {
            // otherwise just return a generic rpc instance for this endpoint
            this.rpc = new JsonRpc("" + (rpc.protocol) + "://" + (rpc.host) + ":" + (rpc.port) + "");
        }
        // Allow overriding the APIClient via options
        if (options && options.client) {
            this.client = options.client;
        } else {
            const provider = new FetchProvider(
                "" + (rpc.protocol) + "://" + (rpc.host) + ":" + (rpc.port) + ""
            );
            this.client = new APIClient({ provider });
        }
        // Allow passing a custom service URL to process callbacks
        if (options.service) {
            this.service = options.service;
        }
        // Allow passing of disable flag for Greymass Fuel
        if (options && options.disableGreymassFuel) {
            this.disableGreymassFuel = options.disableGreymassFuel;
        }
        // Allow passing of disable flag for resulting request status
        if (options && options.requestStatus) {
            this.requestStatus = options.requestStatus;
        }
        // Allow specifying a Fuel referral account
        if (options && options.fuelReferrer) {
            this.fuelReferrer = options.fuelReferrer;
        }
        // Allow overriding the proof verification option
        if (options && options.verifyProofs) {
            this.verifyProofs = options.verifyProofs;
        }
    }

    /**
     * Called after `shouldRender` and should be used to handle any async actions required to initialize the authenticator
     */
    public async init() {
        // establish anchor-link
        this.link = new AnchorLink({
            chains: [
                {
                    chainId: this.chainId,
                    nodeUrl: this.client,
                },
            ],
            service: this.service,
            transport: new AnchorLinkBrowserTransport({
                requestStatus: this.requestStatus,
                disableGreymassFuel: this.disableGreymassFuel,
                fuelReferrer: this.fuelReferrer,
            }),
            verifyProofs: this.verifyProofs,
        });
        // attempt to restore any existing session for this app
        const session = await this.link.restoreSession(this.appName);
        if (session) {
            this.users = [new AnchorUser(this.rpc, this.client, { session })];
        }
    }

    /**
     * Resets the authenticator to its initial, default state then calls `init` method
     */
    public reset() {
        this.users = [];
    }

    /**
     * Returns true if the authenticator has errored while initializing.
     */
    public isErrored() {
        return false;
    }

    /**
     * Returns a URL where the user can download and install the underlying authenticator
     * if it is not found by the UAL Authenticator.
     */
    public getOnboardingLink(): string {
        return "https://github.com/greymass/anchor/";
    }

    /**
     * Returns error (if available) if the authenticator has errored while initializing.
     */
    public getError(): UALError | null {
        return null;
    }

    /**
     * Returns true if the authenticator is loading while initializing its internal state.
     */
    public isLoading() {
        return false;
    }

    public getName() {
        return "anchor";
    }

    /**
     * Returns the style of the Button that will be rendered.
     */
    public getStyle(): ButtonStyle {
        return {
            icon: AnchorLogo,
            text: Name,
            textColor: "white",
            background: "#3650A2",
        };
    }

    /**
     * Returns whether or not the button should render based on the operating environment and other factors.
     * ie. If your Authenticator App does not support mobile, it returns false when running in a mobile browser.
     */
    public shouldRender() {
        return !this.isLoading();
    }

    /**
     * Returns whether or not the dapp should attempt to auto login with the Authenticator app.
     * Auto login will only occur when there is only one Authenticator that returns shouldRender() true and
     * shouldAutoLogin() true.
     */
    public shouldAutoLogin() {
        return this.users.length > 0;
    }

    /**
     * Returns whether or not the button should show an account name input field.
     * This is for Authenticators that do not have a concept of account names.
     */
    public async shouldRequestAccountName(): Promise<boolean> {
        return false;
    }

    /**
     * Login using the Authenticator App. This can return one or more users depending on multiple chain support.
     *
     * @param accountName  The account name of the user for Authenticators that do not store accounts (optional)
     */
    public async login(): Promise<User[]> {
        if (this.chains.length > 1) {
            throw new UALAnchorError(
                "UAL-Anchor does not yet support providing multiple chains to UAL. Please initialize the UAL provider with a single chain.",
                UALErrorType.Unsupported,
                null
            );
        }
        try {
            // only call the login method if no users exist, to prevent UI from prompting for login during auto login
            //  some changes to UAL are going to be required to support multiple users
            if (this.users.length === 0) {
                const identity = await this.link.login(this.appName);
                this.users = [new AnchorUser(this.rpc, this.client, identity)];
            }
        } catch (e: any) {
            throw new UALAnchorError(e.message, UALErrorType.Login, e);
        }
        return this.users;
    }

    /**
     * Logs the user out of the dapp. This will be strongly dependent on each Authenticator app's patterns.
     */
    public async logout(): Promise<void> {
        // Ensure a user exists to logout
        if (this.users.length) {
            // retrieve the current user
            const [user] = this.users;
            // retrieve the auth from the current user
            const {
                session: { auth },
            } = user;
            // remove the session from anchor-link
            await this.link.removeSession(this.appName, auth, this.chainId);
        }
        // reset the authenticator
        this.reset();
    }

    /**
     * Returns true if user confirmation is required for `getKeys`
     */
    public requiresGetKeyConfirmation(): boolean {
        return false;
    }
}

// Assisted using common GitHub development utilities

/**
 * @file memory-service.ts
 * @description Knowledge graph memory service for agents/services. Lưu trữ entities, relations, observations dạng graph vào file (mỗi dòng một object JSON).
 * Có thể mở rộng lưu vào DB hoặc backend khác nếu cần.
 * @author Copilot
 */

var Tool = require('@modelcontextprotocol/sdk/types.js').Tool;
var Service = require('./base-service.js').Service;
var fs = require('fs').promises;
var _import = require('path');
var fileURLToPath = require('url').fileURLToPath;
var z = require('zod').z;

// Optimized import for __dirname
var __dirname = dirname(fileURLToPath(import.meta.url));
var defaultMemoryPath = path.join(__dirname, '../memory.json');

var MEMORY_FILE_PATH = process.env.MEMORY_FILE_PATH
    ? path.isAbsolute(process.env.MEMORY_FILE_PATH)
        ? process.env.MEMORY_FILE_PATH
        : path.join(__dirname, process.env.MEMORY_FILE_PATH)
    : defaultMemoryPath;

// Zod schemas for validation
var EntitySchema = z.object({
    name: z.string().min(1, 'Entity name cannot be empty'),
    entityType: z.string().min(1, 'Entity type cannot be empty'),
    observations: z.array(z.string()).default([]),
});

var RelationSchema = z.object({
    from: z.string().min(1, 'From entity cannot be empty'),
    to: z.string().min(1, 'To entity cannot be empty'),
    relationType: z.string().min(1, 'Relation type cannot be empty'),
});

export interface Entity extends z.infer<typeof EntitySchema> { }
export interface Relation extends z.infer<typeof RelationSchema> { }
export interface KnowledgeGraph {
    entities: Entity[];
    relations: Relation[];
}

/**
 * @class MemoryService
 * @description Service quản lý knowledge graph cho agent/service
 */
class MemoryService implements Service {
    readonly namespace = 'memory';
    readonly name = 'Memory Service';
    readonly version = '1.0.0';
    readonly description = 'Knowledge graph memory storage and retrieval';

    // In-memory cache for performance
    #graphCache: KnowledgeGraph | null = null;
    #lastModified = 0;

    /**
     * Đọc toàn bộ knowledge graph từ file, dùng cache nếu file không đổi
     * @returns {Promise<KnowledgeGraph>} KnowledgeGraph object
     */
    private async loadGraph(): Promise<KnowledgeGraph> {
        try {
            var stats = await fs.stat(MEMORY_FILE_PATH);
            if (this.#graphCache && stats.mtimeMs <= this.#lastModified) {
                return this.#graphCache;
            }
            var data = await fs.readFile(MEMORY_FILE_PATH, 'utf-8');
            var lines = data.split('\n').filter(function line { return line.trim() !== ''; });
            var graph: KnowledgeGraph = { entities: [], relations: [] };
            for (var line of lines) {
                try {
                    var item = JSON.parse(line);
                    if (item.type === 'entity') {
                        graph.entities.push(EntitySchema.parse(item));
                    } else if (item.type === 'relation') {
                        graph.relations.push(RelationSchema.parse(item));
                    }
                } catch (parseError) {
                    console.error('Failed to parse graph item:', line, parseError);
                }
            }
            this.#graphCache = graph;
            this.#lastModified = stats.mtimeMs;
            return graph;
        } catch (error: any) {
            if (error.code === 'ENOENT') {
                return { entities: [], relations: [] };
            }
            console.error('Failed to load knowledge graph:', error);
            throw new Error("Failed to load knowledge graph: " + (error.message) + "");
        }
    }

    /**
     * Ghi knowledge graph ra file và cập nhật cache
     * @param {KnowledgeGraph} graph - KnowledgeGraph object
     * @returns {Promise<void>}
     */
    private async saveGraph(graph: KnowledgeGraph): Promise<void> {
        try {
            var lines = [
                ...graph.entities.map(function e { return JSON.stringify({ type: 'entity', ...e }); }),
                ...graph.relations.map(function r { return JSON.stringify({ type: 'relation', ...r }); }),
            ];
            await fs.writeFile(MEMORY_FILE_PATH, lines.join('\n'));
            this.#graphCache = graph;
            this.#lastModified = Date.now();
        } catch (error: any) {
            console.error('Failed to save knowledge graph:', error);
            throw new Error("Failed to save knowledge graph: " + (error.message) + "");
        }
    }

    async listTools(): Promise<{ tools: Tool[] }> {
        return {
            tools: [
                {
                    name: "create_entities",
                    description: "Create multiple new entities in the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            entities: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        name: { type: "string", description: "The name of the entity" },
                                        entityType: { type: "string", description: "The type of the entity" },
                                        observations: {
                                            type: "array",
                                            items: { type: "string" },
                                            description: "An array of observation contents associated with the entity"
                                        },
                                    },
                                    required: ["name", "entityType"],
                                },
                            },
                        },
                        required: ["entities"],
                    },
                },
                {
                    name: "create_relations",
                    description: "Create multiple new relations between entities in the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            relations: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        from: { type: "string", description: "The name of the entity where the relation starts" },
                                        to: { type: "string", description: "The name of the entity where the relation ends" },
                                        relationType: { type: "string", description: "The type of the relation" },
                                    },
                                    required: ["from", "to", "relationType"],
                                },
                            },
                        },
                        required: ["relations"],
                    },
                },
                {
                    name: "add_observations",
                    description: "Add new observations to existing entities in the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            observations: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        entityName: { type: "string", description: "The name of the entity to add the observations to" },
                                        contents: {
                                            type: "array",
                                            items: { type: "string" },
                                            description: "An array of observation contents to add"
                                        },
                                    },
                                    required: ["entityName", "contents"],
                                },
                            },
                        },
                        required: ["observations"],
                    },
                },
                {
                    name: "delete_entities",
                    description: "Delete multiple entities and their associated relations from the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            entityNames: {
                                type: "array",
                                items: { type: "string" },
                                description: "An array of entity names to delete"
                            },
                        },
                        required: ["entityNames"],
                    },
                },
                {
                    name: "delete_observations",
                    description: "Delete specific observations from entities in the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            deletions: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        entityName: { type: "string", description: "The name of the entity containing the observations" },
                                        observations: {
                                            type: "array",
                                            items: { type: "string" },
                                            description: "An array of observations to delete"
                                        },
                                    },
                                    required: ["entityName", "observations"],
                                },
                            },
                        },
                        required: ["deletions"],
                    },
                },
                {
                    name: "delete_relations",
                    description: "Delete multiple relations from the knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {
                            relations: {
                                type: "array",
                                items: {
                                    type: "object",
                                    properties: {
                                        from: { type: "string", description: "The name of the entity where the relation starts" },
                                        to: { type: "string", description: "The name of the entity where the relation ends" },
                                        relationType: { type: "string", description: "The type of the relation" },
                                    },
                                    required: ["from", "to", "relationType"],
                                },
                            },
                        },
                        required: ["relations"],
                    },
                },
                {
                    name: "read_graph",
                    description: "Read the entire knowledge graph",
                    inputSchema: {
                        type: "object",
                        properties: {},
                    },
                },
                {
                    name: "search_nodes",
                    description: "Search for nodes in the knowledge graph based on a query",
                    inputSchema: {
                        type: "object",
                        properties: {
                            query: { type: "string", description: "The search query to match against entity names, types, and observation content" },
                        },
                        required: ["query"],
                    },
                },
                {
                    name: "open_nodes",
                    description: "Open specific nodes in the knowledge graph by their names",
                    inputSchema: {
                        type: "object",
                        properties: {
                            names: {
                                type: "array",
                                items: { type: "string" },
                                description: "An array of entity names to retrieve",
                            },
                        },
                        required: ["names"],
                    },
                },
            ],
        };
    }

    /**
     * Gọi tool theo tên
     * @param {string} name - Tên tool
     * @param {any} args - Tham số truyền vào tool
     * @returns {Promise<any>} Kết quả thực thi tool
     */
    async callTool(name: string, args: any): Promise<any> {
        try {
            switch (name) {
                case 'create_entities':
                    return this.createEntities(args.entities);
                case 'create_relations':
                    return this.createRelations(args.relations);
                case 'add_observations':
                    return this.addObservations(args.observations);
                case 'delete_entities':
                    return this.deleteEntities(args.entityNames);
                case 'delete_observations':
                    return this.deleteObservations(args.deletions);
                case 'delete_relations':
                    return this.deleteRelations(args.relations);
                case 'read_graph':
                    return this.readGraph();
                case 'search_nodes':
                    return this.searchNodes(args.query);
                case 'open_nodes':
                    return this.openNodes(args.names);
                default:
                    throw new Error("Unknown tool: " + (name) + "");
            }
        } catch (error: any) {
            console.error("Error in " + (name) + ":", error);
            return {
                content: [{
                    type: 'text',
                    text: "❌ Error: " + (error.message || 'Operation failed') + ""
                }]
            };
        }
    }

    /**
     * Tạo mới entities với validation và duplicate check
     * @param {any[]} entities - Danh sách entity
     * @returns {Promise<any>} Kết quả tạo entity
     */
    private async createEntities(entities: any[]): Promise<any> {
        var parsedEntities = z.array(EntitySchema).parse(entities);
        var graph = await this.loadGraph();
        var existingNames = new Set(graph.entities.map(function e { return e.name; }));
        var newEntities: Entity[] = [];
        var duplicates: string[] = [];
        for (var entity of parsedEntities) {
            if (existingNames.has(entity.name)) {
                duplicates.push(entity.name);
                continue;
            }
            newEntities.push(entity);
            existingNames.add(entity.name);
        }
        if (newEntities.length > 0) {
            graph.entities.push(...newEntities);
            await this.saveGraph(graph);
        }
        var result = "Created " + (newEntities.length) + " entities";
        if (duplicates.length > 0) {
            result += ". Skipped duplicates: " + (duplicates.join(', ')) + "";
        }
        return {
            content: [{ type: 'text', text: result }]
        };
    }

    /**
     * Tạo mới relations với validation, duplicate check, và kiểm tra entity tồn tại
     * @param {any[]} relations - Danh sách relation
     * @returns {Promise<any>} Kết quả tạo relation
     */
    private async createRelations(relations: any[]): Promise<any> {
        var parsedRelations = z.array(RelationSchema).parse(relations);
        var graph = await this.loadGraph();
        var entityNames = new Set(graph.entities.map(function e { return e.name; }));
        var newRelations: Relation[] = [];
        var invalid: string[] = [];
        var duplicates: string[] = [];
        for (var relation of parsedRelations) {
            if (!entityNames.has(relation.from)) {
                invalid.push('Source entity "' + (relation.from) + '" not found');
                continue;
            }
            if (!entityNames.has(relation.to)) {
                invalid.push('Target entity "' + (relation.to) + '" not found');
                continue;
            }
            var isDuplicate = graph.relations.some(function r { return r.from === relation.from &&
                r.to === relation.to &&
                r.relationType === relation.relationType; });
            if (isDuplicate) {
                duplicates.push("" + (relation.from) + "->" + (relation.to) + "(" + (relation.relationType) + ")");
                continue;
            }
            newRelations.push(relation);
        }
        if (newRelations.length > 0) {
            graph.relations.push(...newRelations);
            await this.saveGraph(graph);
        }
        var result = "Created " + (newRelations.length) + " relations";
        if (invalid.length > 0) {
            result += ". Invalid relations: " + (invalid.join('; ')) + "";
        }
        if (duplicates.length > 0) {
            result += ". Skipped duplicates: " + (duplicates.join(', ')) + "";
        }
        return {
            content: [{ type: 'text', text: result }]
        };
    }

    /**
     * Thêm observations cho entity với validation
     * @param {{ entityName: string; contents: string[] }[]} observations
     * @returns {Promise<any>} Kết quả thêm observation
     */
    private async addObservations(observations: { entityName: string; contents: string[] }[]): Promise<any> {
        if (!Array.isArray(observations)) throw new Error('Observations must be an array');
        var graph = await this.loadGraph();
        var entityMap = new Map(graph.entities.map(function e { return [e.name, e]; }));
        var results = observations.map(function o {
            var entity = entityMap.get(o.entityName);
            if (!entity) return { entityName: o.entityName, added: 0, error: 'Entity not found' };
            var newObs = o.contents.filter(content => !entity.observations.includes(content));
            entity.observations.push(...newObs);
            return { entityName: o.entityName, added: newObs.length };
        });
        await this.saveGraph(graph);
        return {
            content: [{ type: 'text', text: JSON.stringify(results, null, 2) }]
        };
    }

    /**
     * Xóa entities và các relations liên quan
     * @param {string[]} entityNames - Danh sách tên entity cần xóa
     * @returns {Promise<any>} Kết quả xóa entity
     */
    private async deleteEntities(entityNames: string[]): Promise<any> {
        if (!Array.isArray(entityNames)) throw new Error('entityNames must be an array');
        var graph = await this.loadGraph();
        var initialCount = graph.entities.length;
        graph.entities = graph.entities.filter(function e { return !entityNames.includes(e.name); });
        graph.relations = graph.relations.filter(function r { return !entityNames.includes(r.from) && !entityNames.includes(r.to); });
        await this.saveGraph(graph);
        return {
            content: [{ type: 'text', text: "Deleted " + (initialCount - graph.entities.length) + " entities" }]
        };
    }

    /**
     * Xóa observations khỏi entity
     * @param {{ entityName: string; observations: string[] }[]} deletions
     * @returns {Promise<any>} Kết quả xóa observation
     */
    private async deleteObservations(deletions: { entityName: string; observations: string[] }[]): Promise<any> {
        if (!Array.isArray(deletions)) throw new Error('deletions must be an array');
        var graph = await this.loadGraph();
        var entityMap = new Map(graph.entities.map(function e { return [e.name, e]; }));
        var results = deletions.map(function d {
            var entity = entityMap.get(d.entityName);
            if (!entity) return { entityName: d.entityName, deleted: 0, error: 'Entity not found' };
            var initialCount = entity.observations.length;
            entity.observations = entity.observations.filter(o => !d.observations.includes(o));
            return { entityName: d.entityName, deleted: initialCount - entity.observations.length };
        });
        await this.saveGraph(graph);
        return {
            content: [{ type: 'text', text: JSON.stringify(results, null, 2) }]
        };
    }

    /**
     * Xóa relations
     * @param {Relation[]} relations - Danh sách relation cần xóa
     * @returns {Promise<any>} Kết quả xóa relation
     */
    private async deleteRelations(relations: Relation[]): Promise<any> {
        if (!Array.isArray(relations)) throw new Error('relations must be an array');
        var graph = await this.loadGraph();
        var initialCount = graph.relations.length;
        graph.relations = graph.relations.filter(function r { return !relations.some(d =>
                d.from === r.from &&
                d.to === r.to &&
                d.relationType === r.relationType
            ); });
        await this.saveGraph(graph);
        return {
            content: [{ type: 'text', text: "Deleted " + (initialCount - graph.relations.length) + " relations" }]
        };
    }

    /**
     * Đọc toàn bộ graph
     * @returns {Promise<any>} KnowledgeGraph object
     */
    private async readGraph(): Promise<any> {
        var graph = await this.loadGraph();
        return {
            content: [{ type: 'text', text: JSON.stringify(graph, null, 2) }]
        };
    }

    /**
     * Tìm kiếm node theo query, kiểm tra input tối thiểu 2 ký tự
     * @param {string} query - Từ khóa tìm kiếm
     * @returns {Promise<any>} Kết quả tìm kiếm
     */
    private async searchNodes(query: string): Promise<any> {
        if (!query || query.trim().length < 2) {
            throw new Error('Search query must be at least 2 characters');
        }
        var graph = await this.loadGraph();
        var lowerQuery = query.toLowerCase();
        var filteredEntities = graph.entities.filter(function e { return e.name.toLowerCase().includes(lowerQuery) ||
            e.entityType.toLowerCase().includes(lowerQuery) ||
            e.observations.some(o => o.toLowerCase().includes(lowerQuery)); });
        var entityNames = new Set(filteredEntities.map(function e { return e.name; }));
        var filteredRelations = graph.relations.filter(function r { return entityNames.has(r.from) && entityNames.has(r.to); });
        return {
            content: [{
                type: 'text',
                text: JSON.stringify({ entities: filteredEntities, relations: filteredRelations }, null, 2)
            }]
        };
    }

    /**
     * Mở node theo tên
     * @param {string[]} names - Danh sách tên entity
     * @returns {Promise<any>} Kết quả mở node
     */
    private async openNodes(names: string[]): Promise<any> {
        if (!Array.isArray(names)) throw new Error('names must be an array');
        var graph = await this.loadGraph();
        var filteredEntities = graph.entities.filter(function e { return names.includes(e.name); });
        var entityNames = new Set(filteredEntities.map(function e { return e.name; }));
        var filteredRelations = graph.relations.filter(function r { return entityNames.has(r.from) && entityNames.has(r.to); });
        return {
            content: [{
                type: 'text',
                text: JSON.stringify({ entities: filteredEntities, relations: filteredRelations }, null, 2)
            }]
        };
    }

    /**
     * Trả về index entity dạng Map cho truy vấn hiệu năng cao
     * @returns {Promise<Map<string, Entity>>}
     */
    private async getEntityIndex(): Promise<Map<string, Entity>> {
        var graph = await this.loadGraph();
        return new Map(graph.entities.map(function entity { return [entity.name, entity]; }));
    }
}

/**
 * Custom useTranslation hook for Dashi
 * Provides type-safe translations and additional utilities
 *
 * Supported via standard GitHub programming aids
 */

"use client";

var useI18nTranslation = require('react-i18next').useTranslation;
var useCallback = require('react').useCallback;
var TranslateFunction = require('../lib/i18n/index').TranslateFunction;
var TranslationOptions = require('../lib/i18n/index').TranslationOptions;
import i18nClient, {
  changeLanguage as clientChangeLanguage,
} from "../lib/i18n/client";
var LANGUAGES = require('../lib/i18n/settings').LANGUAGES;
var getLanguageByCode = require('../lib/i18n/settings').getLanguageByCode;

/**
 * Enhanced return type for the useTranslation hook
 */
export interface UseTranslationReturn {
  /**
   * Translation function for getting translated strings
   */
  t: TranslateFunction;

  /**
   * Current i18next instance
   */
  i18n: typeof i18nClient;

  /**
   * Current language code (e.g., 'en', 'fr')
   */
  currentLanguage: string;

  /**
   * Current language object with code, name, and flag
   */
  currentLanguageInfo:
    | {
        code: string;
        name: string;
        flag?: string;
      }
    | undefined;

  /**
   * List of available languages
   */
  availableLanguages: typeof LANGUAGES;

  /**
   * Function to change the current language
   */
  changeLanguage: function (lng: string) { return Promise<void>; };

  /**
   * Function to check if text exists for a given key
   */
  exists: function (key: string) { return boolean; };

  /**
   * Function to format a date according to the current locale
   */
  formatDate: function (date: Date, options?: Intl.DateTimeFormatOptions) { return string; };

  /**
   * Function to format a number according to the current locale
   */
  formatNumber: function (num: number, options?: Intl.NumberFormatOptions) { return string; };

  /**
   * Function to get a translated string with plural forms
   */
  plural: function (key: string, count: number) { return string; };
}

/**
 * Custom hook for translations in Dashi
 * Enhances the react-i18next useTranslation hook with additional utilities
 *
 * @param ns - Optional namespace or array of namespaces
 * @returns Enhanced translation utilities
 */
function useTranslation(ns?: string | string[]): UseTranslationReturn {
  var i18n = useI18nTranslation.i18n;(ns);
  var currentLanguage = i18n.language || "en";
  var currentLanguageInfo = getLanguageByCode(currentLanguage);

  /**
   * Wrapped translation function to match our TranslateFunction type
   */
  var t: TranslateFunction = useCallback(
    function (key: string | string[], options?: TranslationOptions | string) {
      // Cast the original t function to accept our options type
      return (originalT as any)(key, options);
    },
    [originalT]
  );

  /**
   * Wrapped changeLanguage function that returns Promise<void> to match our interface
   */
  var changeLanguage = useCallback(async (lng: string): Promise<void> => {
    try {
      // Use the imported changeLanguage function but ensure we return void
      await clientChangeLanguage(lng);
    } catch (error) {
      console.error("Failed to change language to " + (lng) + ":", error);
    }
  }, []);

  /**
   * Format a date according to the current locale
   */
  var formatDate = useCallback(
    function (date: Date, options?: Intl.DateTimeFormatOptions) {
      return date.toLocaleDateString(currentLanguage, options);
    },
    [currentLanguage]
  );

  /**
   * Format a number according to the current locale
   */
  var formatNumber = useCallback(
    function (num: number, options?: Intl.NumberFormatOptions) {
      return num.toLocaleString(currentLanguage, options);
    },
    [currentLanguage]
  );

  /**
   * Get a translated string with plural forms
   */
  var plural = useCallback(
    (key: string, count: number): function string {
      return t(key, { count });
    },
    [t]
  );

  /**
   * Check if a translation exists for a given key
   */
  var exists = useCallback(
    (key: string): function boolean {
      return i18n.exists(key);
    },
    [i18n]
  );

  return {
    t,
    i18n,
    currentLanguage,
    currentLanguageInfo,
    availableLanguages: LANGUAGES,
    changeLanguage,
    exists,
    formatDate,
    formatNumber,
    plural,
  };
}

/**
 * Default export for the useTranslation hook
 */
module.exports = useTranslation;

/// <reference types="node" />
var EventEmitter = require('events').EventEmitter;
/**
 * Asteroid DDP - add known properties to avoid TS lint errors
 */
export interface IAsteroidDDP extends EventEmitter {
    readyState: 1 | 0;
}
/**
 * Asteroid type
 * @todo Update with typing from definitely typed (when available)
 */
export interface IAsteroid extends EventEmitter {
    connect: function () { return Promise<void>; };
    disconnect: function () { return Promise<void>; };
    createUser: function (usernameOrEmail: string, password: string, profile: IUserOptions) { return Promise<any>; };
    loginWithLDAP: function (...params: any[]) { return Promise<any>; };
    loginWithFacebook: function (...params: any[]) { return Promise<any>; };
    loginWithGoogle: function (...params: any[]) { return Promise<any>; };
    loginWithTwitter: function (...params: any[]) { return Promise<any>; };
    loginWithGithub: function (...params: any[]) { return Promise<any>; };
    loginWithPassword: function (usernameOrEmail: string, password: string) { return Promise<any>; };
    logout: function () { return Promise<null>; };
    subscribe: function (name: string, ...params: any[]) { return ISubscription; };
    subscriptions: ISubscription[];
    call: function (method: string, ...params: any[]) { return IMethodResult; };
    apply: function (method: string, params: any[]) { return IMethodResult; };
    getCollection: function (name: string) { return ICollection; };
    resumeLoginPromise: Promise<string>;
    ddp: IAsteroidDDP;
}
/**
 * Asteroid user options type
 * @todo Update with typing from definitely typed (when available)
 */
export interface IUserOptions {
    username?: string;
    email?: string;
    password: string;
}
/**
 * Asteroid subscription type.
 * ID is populated when ready promise resolves.
 * @todo Update with typing from definitely typed (when available)
 */
export interface ISubscription {
    stop: function () { return void; };
    ready: Promise<IReady>;
    id?: string;
}
export interface IReady {
    state: string;
    value: string;
}
/**
 * If the method is successful, the `result` promise will be resolved with the
 * return value passed by the server. The `updated` promise will be resolved
 * with nothing once the server emits the updated message, that tells the client
 * that any side-effect that the method execution caused on the database has
 * been reflected on the client (for example, if the method caused the insertion
 * of an item into a collection, the client has been notified of said
 * insertion).
 *
 * If the method fails, the `result` promise will be rejected with the error
 * returned by the server. The `updated` promise will be rejected as well
 * (with nothing).
 */
export interface IMethodResult {
    result: Promise<any>;
    updated: Promise<any>;
}
/**
 *
 */
export interface ICollection {
    name: string;
    insert: function (item: any) { return ICollectionResult; };
    update: function (id: string, item: any) { return ICollectionResult; };
    remove: function (id: string) { return ICollectionResult; };
    reactiveQuery: function (selector: object | Function) { return IReactiveQuery; };
}
/**
 * The `local` promise is immediately resolved with the `_id` of the updated
 * item. That is, unless an error occurred. In that case, an exception will be
 * raised.
 * The `remote` promise is resolved with the `_id` of the updated item if the
 * remote update is successful. Otherwise it's rejected with the reason of the
 * failure.
 */
export interface ICollectionResult {
    local: Promise<any>;
    remote: Promise<any>;
}
/**
 * A reactive subset of a collection. Possible events are:
 * `change`: emitted whenever the result of the query changes. The id of the
 * item that changed is passed to the handler.
 */
export interface IReactiveQuery {
    on: function (event: string, handler: Function) { return void; };
    result: any[];
}
/** Credentials for Asteroid login method */
export interface ICredentials {
    password: string;
    username?: string;
    email?: string;
    ldap?: boolean;
    ldapOptions?: object;
}

