"use strict";

var vscode = require('vscode');
var languages = require('./languages').languages;

var configSection = 'rainbow-end';

var defaultDecorations = [
  vscode.window.createTextEditorDecorationType({
    color: { id: "rainbowend.deep1" }
  }),
  vscode.window.createTextEditorDecorationType({
    color: { id: "rainbowend.deep2" }
  }),
  vscode.window.createTextEditorDecorationType({
    color: { id: "rainbowend.deep3" }
  })
];

function createDeepDecorations(): vscode.TextEditorDecorationType[] {
  var colors: string[] | undefined = vscode.workspace.getConfiguration(configSection).get('colors');

  var mappedColors = colors?.map(
    function (color) { return vscode.window.createTextEditorDecorationType({ color }); });
  if (mappedColors && mappedColors.length > 0) {
    return mappedColors;
  }

  return defaultDecorations;
}

var deepDecorations = createDeepDecorations();

var timeout: NodeJS.Timer | null = null;
var regExs: { [index: string]: RegExp } = {};

function activate(context: vscode.ExtensionContext) {
  Object.keys(languages).forEach(function language {
    regExs[language] = buildRegex(language);
  });

  var activeEditor = vscode.window.activeTextEditor;
  if (activeEditor) {
    triggerUpdateDecorations(activeEditor);
  }

  vscode.window.onDidChangeActiveTextEditor(
    function editor {
      activeEditor = editor;
      if (activeEditor) {
        triggerUpdateDecorations(activeEditor);
      }
    },
    null,
    context.subscriptions
  );

  vscode.workspace.onDidChangeTextDocument(
    function event {
      if (activeEditor && event.document === activeEditor.document) {
        triggerUpdateDecorations(activeEditor);
      }
    },
    null,
    context.subscriptions
  );

  vscode.workspace.onDidChangeConfiguration(
    function event {
      if (event.affectsConfiguration(configSection)) {
        deepDecorations = createDeepDecorations();
      }
    },
    null,
    context.subscriptions
  );
}

function triggerUpdateDecorations(activeEditor: vscode.TextEditor) {
  if (timeout) {
    clearTimeout(timeout);
  }
  timeout = setTimeout(updateDecorations, 250);
}

function buildRegex(language: string) {
  var languageConfiguration = languages[language];
  var tokens: Array<string> = languageConfiguration["openTokens"];
  tokens = tokens.concat(languageConfiguration["inlineOpenTokens"]);
  tokens = tokens.concat(languageConfiguration["closeTokens"]);
  tokens = tokens.concat(languageConfiguration["neutralTokens"]);
  return RegExp("(\\b)(" + tokens.join("|") + ")(\\b)", "gm");
}

function ignoreInDelimiters(
  token_pairs:
    | Array<{
        open: string;
        close: string;
      }>
    | undefined,
  text: string
) {
  /* This function replaces text inside each token pair with spaces,
	   so as to ignore the text between delimiters */
  if (token_pairs) {
    token_pairs.forEach(function ({ open: open_delim, close: close_delim }) {
      /* Only allow nesting if delimiters are different */
      if (open_delim == close_delim) {
        var regexp = RegExp(
          "" + (open_delim) + "[^" + (close_delim) + "]*" + (close_delim) + "",
          "gm"
        );
        text = text.replace(regexp, match => {
          return " ".repeat(match.length);
        });
      } else {
        var openRegexp = RegExp("" + (open_delim) + "", "gm");
        var closeRegexp = RegExp("" + (close_delim) + "", "gm");

        var indices = [];

        var match = openRegexp.exec(text);
        if (match == null) {
          return;
        }

        while (match != null) {
          indices.push({ index: match.index, type: "open" });
          match = openRegexp.exec(text);
        }

        match = closeRegexp.exec(text);
        if (match == null) {
          return;
        }

        while (match != null) {
          indices.push({ index: match.index, type: "close" });
          match = closeRegexp.exec(text);
        }

        /* Sort by index */
        indices = indices.sort(({ index: a }, { index: b }) => a - b);

        var ignore_env_counter = 0;
        var first_index = indices[0].index;

        var index: number;
        var type: string;

        /* This isn't so inefficient in that it is
    	     O(indices.length), instead of O(text.length).
	         Also, the list is already ordered, which is really helpful */
        for ({ index, type } of indices) {
          /* skip current token if trying to close when there is no open block
           cannot just break because '\n' can be both a closing token and a
           normal line end
          */
          if (type == "close" && ignore_env_counter == 0) {
            continue;
          }

          /* if counter is zero, should begin an ignore block */
          if (ignore_env_counter == 0) {
            first_index = index;
          }

          if (type == "open") {
            /* if it is an open token, always increment env counter */
            ignore_env_counter++;
          } else {
            ignore_env_counter--;
            /* if counter has reached zero after a closing token,
             end ignore block */
            var last_index = index;

            /* Set ignore block slice as whitespace and keep the rest */
            text =
              text.slice(0, first_index) +
              " ".repeat(last_index - first_index + 1) +
              text.slice(last_index + 1);
          }
        }

        if (ignore_env_counter != 0) {
          /* Didn't close last block */
          text =
            text.slice(0, first_index) +
            " ".repeat(text.length - first_index + 1);
        }
      }
    });
  }
  return text;
}

function updateDecorations() {
  var activeEditor = vscode.window.activeTextEditor;
  if (!activeEditor) {
    return;
  }
  var languageConfiguration = languages[activeEditor.document.languageId];

  var text = activeEditor.document.getText();
  var options: vscode.DecorationOptions[][] = [];
  deepDecorations.forEach(function d {
    options.push([]);
  });
  var match;
  var deep = 0;

  // if we are not case sensitive, then ensure the case of text matches then keyworkd matches
  if (!languageConfiguration.caseSensitive) {
    text = text.toLowerCase();
  }
  // substitute all ignore intervals with spaces
  // this ensures commented code or
  // keywords inside strings are ignored properly

  // also, prepend a whitespace to allow matching the first character in document
  // if needed

  text =
    " " + ignoreInDelimiters(languageConfiguration.ignoreInDelimiters, text);
  while ((match = regExs[activeEditor.document.languageId].exec(text))) {
    var startIndex = match.index + match[1].length - 1; // Decrement to compensate for added character
    var startPos = activeEditor.document.positionAt(startIndex);
    var endPos = activeEditor.document.positionAt(
      startIndex + match[2].length
    );
    var decoration: vscode.DecorationOptions = {
      range: new vscode.Range(startPos, endPos)
    };

    if (languageConfiguration.closeTokens.indexOf(match[2]) > -1) {
      if (deep > 0) {
        deep -= 1;
      }
      options[deep % deepDecorations.length].push(decoration);
    } else if (languageConfiguration.neutralTokens.indexOf(match[2]) > -1) {
      if (deep > 0) {
        options[(deep - 1) % deepDecorations.length].push(decoration);
      }
    } else if (languageConfiguration.openTokens.indexOf(match[2]) > -1) {
      options[deep % deepDecorations.length].push(decoration);
      deep += 1;
    } else {
      if (match[1].length === 0 || match[1].match("^[\\s\n]+$")) {
        options[deep % deepDecorations.length].push(decoration);
        deep += 1;
      }
    }
  }

  deepDecorations.forEach(function (deepDecoration, i) {
    activeEditor.setDecorations(deepDecoration, options[i]);
  });
}

// Copied from https://github.com/Shopify/shopify_app
var itpHelper = "(function() {
      function ITPHelper(opts) {
        this.itpContent = document.getElementById('TopLevelInteractionContent');
        this.itpAction = document.getElementById('TopLevelInteractionButton');
        this.redirectUrl = opts.redirectUrl;
      }

      ITPHelper.prototype.redirect = function() {
        sessionStorage.setItem('shopify.top_level_interaction', true);
        window.location.href = this.redirectUrl;
      }

      ITPHelper.prototype.userAgentIsAffected = function() {
        return Boolean(document.hasStorageAccess);
      }

      ITPHelper.prototype.canPartitionCookies = function() {
        var versionRegEx = /Version\\/12\\.0\\.?\\d? Safari/;
        return versionRegEx.test(navigator.userAgent);
      }

      ITPHelper.prototype.setUpContent = function(onClick) {
        this.itpContent.style.display = 'block';
        this.itpAction.addEventListener('click', this.redirect.bind(this));
      }

      ITPHelper.prototype.execute = function() {
        if (!this.itpContent) {
          return;
        }

        if (this.userAgentIsAffected()) {
          this.setUpContent();
        } else {
          this.redirect();
        }
      }

      this.ITPHelper = ITPHelper;
    })(window);";

module.exports = itpHelper;

require('reflect-metadata');
var createConnection = require('typeorm').createConnection;
var ApolloServer = require('apollo-server-express').ApolloServer;
var express = require('express');
var cookieParser = require('cookie-parser');

var typeDefs = require('./typeDefs').typeDefs;
var resolvers = require('./resolvers').resolvers;
var verify = require('jsonwebtoken').verify;
var ACCESS_TOKEN_SECRET = require('./constants').ACCESS_TOKEN_SECRET;

const startServer = async function () {
  const server = new ApolloServer({
    // These will be defined for both new or existing servers
    typeDefs,
    resolvers,
    context: ({ req, res }: any) => ({ req, res })
  });

  await createConnection();

  const app = express();

  app.use(cookieParser());

  app.use((req, _, next) => {
    const accessToken = req.cookies["access-token"];
    try {
      const data = verify(accessToken, ACCESS_TOKEN_SECRET) as any;
      (req as any).userId = data.userId;
    } catch {}
    next();
  });

  server.applyMiddleware({ app }); // app is from an existing express app

  app.listen({ port: 4000 }, () =>
    console.log("🚀 Server ready at http://localhost:4000" + (server.graphqlPath) + "")
  );
};

startServer();

var ck = require('cryptokitties-contrib');
var JSDOM = require('jsdom').JSDOM;
var _ = require('lodash');
var fetch = require('node-fetch');

module.exports = async function(event, context, callback) {;
	const matron = event.queryStringParameters.matron;
	const sire = event.queryStringParameters.sire;
	const result = await kittyRecommendation(matron, [sire]);
	const response = {
		body: JSON.stringify({
			input: { matron, sire },
			result,
		}),
		statusCode: 200,
	};
	callback(null, response);
}

async function kittyRecommendation(owned, kittys) {
	const kittenPrices = [];
	for (const kitty of kittys) {
		const result = await expectedPriceOfKittens(owned, kitty);
		kittenPrices.push({ ...result, id: kitty });
	}
	const sorted = _.sortBy(kittenPrices, 'averagePriceOfKitten');
	return sorted;
}

async function getKittyGenomePrediction(kitty1, kitty2) {
	if (typeof kitty1 !== 'string') { kitty1 = String(kitty1); }
	if (typeof kitty2 !== 'string') { kitty2 = String(kitty2); }
	const kittyGenomeServiceUrl = 'http://www.kitty.services/api';
	const res = await fetch("" + (kittyGenomeServiceUrl) + "/gene", {
		body: JSON.stringify( [kitty1, kitty2]),
		headers: {
			'Accept': 'application/json',
			'Content-Type': 'application/json;charset=UTF-8',
			'Origin': 'http://www.kitty.services',
		},
		method: 'POST',
	});
	return res.json();
}

async function kittiesOnAuction() {
	return _.map((await ck.listAuctions()), function (k) { return k.id; })
}

async function getCattributes() {
	const kittyGenePriceIndex = "https://cryptokittydex.com/cattributes";
	const res = await fetch("" + (kittyGenePriceIndex) + "");
	const html = await res.text();
	const dom = new JSDOM(html);
	const cattributeInfo = dom.window.document.querySelectorAll('.cattribute-info-layer');
	const result = {};
	_.map(cattributeInfo, function (c) {
		result[c.querySelector('strong').innerHTML] = {
			population: parseInt(c.innerHTML.split('\n')[2].replace('kitties', '').replace(/,/g, '').trim(), 10),
			price: parseFloat(c.querySelector('span[data-title="Average price paid for a kitty possessing this cattribute"]')
				.innerHTML.replace('~', '').replace('ETH', '').trim()),
		};
	});
	return result;
}

async function expectedPriceOfKittens(kitty1, kitty2) {
	const cattributeProbabilities = await getKittyGenomePrediction(kitty1, kitty2);
	const cattributes = await getCattributes();
	const fancyPrice = 2;
	const cattributeProbsSum = _.reduce(cattributeProbabilities.results, function (a, c) { return a + c[1]; }, 0);
	const normalizedCattributeProbs = _.map(cattributeProbabilities.results, function (c) { return [ c[0], c[1] / cattributeProbsSum]; });
	let avgPriceOfKitten = 0;
	// tslint:disable-next-line:prefer-for-of
	for (let i = 0; i < normalizedCattributeProbs.length; i++) {
		if (normalizedCattributeProbs[i][0] !== 'fancy') {
			avgPriceOfKitten =
				avgPriceOfKitten + cattributes[normalizedCattributeProbs[i][0]].price * normalizedCattributeProbs[i][1];
		}
	}
	return {
		averagePriceOfKitten: avgPriceOfKitten,
		results: cattributeProbabilities.results
	};
}

