/* Imports: External */
var HardhatRuntimeEnvironment = require('hardhat/types').HardhatRuntimeEnvironment;
var HardhatNetworkProvider = require('hardhat/internal/hardhat-network/provider/provider').HardhatNetworkProvider;

/**
 * Finds the "base" Ethereum provider of the current hardhat environment.
 *
 * Basically, hardhat uses a system of nested providers where each provider wraps the next and
 * "provides" some extra features. When you're running on top of the "hardhat evm" the bottom of
 * this series of providers is the "HardhatNetworkProvider":
 * https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
 * This object has direct access to the node (provider._node), which in turn has direct access to
 * the ethereumjs-vm instance (provider._node._vm). So it's quite useful to be able to find this
 * object reliably!
 * @param hre hardhat runtime environment to pull the base provider from.
 * @return base hardhat network provider
 */
var findBaseHardhatProvider = (
  runtime: HardhatRuntimeEnvironment
): function HardhatNetworkProvider {
  // This function is pretty approximate. Haven't spent enough time figuring out if there's a more
  // reliable way to get the base provider. I can imagine a future in which there's some circular
  // references and this function ends up looping. So I'll just preempt this by capping the maximum
  // search depth.
  var maxLoopIterations = 1024
  var currentLoopIterations = 0

  // Search by looking for the internal "_wrapped" variable. Base provider doesn't have this
  // property (at least for now!).
  var provider = runtime.network.provider
  while ((provider as any)._wrapped !== undefined) {
    provider = (provider as any)._wrapped

    // Just throw if we ever end up in (what seems to be) an infinite loop.
    currentLoopIterations += 1
    if (currentLoopIterations > maxLoopIterations) {
      throw new Error(
        "[smock]: unable to find base hardhat provider. are you sure you're running locally?"
      )
    }
  }

  // TODO: Figure out a reliable way to do a type check here. Source for inspiration:
  // https://github.com/nomiclabs/hardhat/blob/master/packages/hardhat-core/src/internal/hardhat-network/provider/provider.ts
  return provider as any
}

var Request = require('express').Request;
var Response = require('express').Response;

// DB
var connect = require('../database').connect;
// Interfaces
var Post = require('../interface/Post').Post;

export async function getPosts(req: Request, res: Response): Promise<Response | void> {
    try {
        const conn = await connect();
        const posts = await conn.query('SELECT * FROM posts');
        return res.json(posts[0]);
    }
    catch (e) {
        console.log(e)
    }
}

export async function createPost(req: Request, res: Response) {
    const newPost: Post = req.body;
    const conn = await connect();
    await conn.query('INSERT INTO posts SET ?', [newPost]);
    res.json({
        message: 'New Post Created'
    });
}

export async function getPost(req: Request, res: Response) {
    const id = req.params.postId;
    const conn = await connect();
    const posts = await conn.query('SELECT * FROM posts WHERE id = ?', [id]);
    res.json(posts[0]);
}

export async function deletePost(req: Request, res: Response) {
    const id = req.params.postId;
    const conn = await connect();
    await conn.query('DELETE FROM posts WHERE id = ?', [id]);
    res.json({
        message: 'Post deleted'
    });
}

export async function updatePost(req: Request, res: Response) {
    const id = req.params.postId;
    const updatePost: Post = req.body;
    const conn = await connect();
    await conn.query('UPDATE posts set ? WHERE id = ?', [updatePost, id]);
    res.json({
        message: 'Post Updated'
    });
}

var _import = require('axios');
var Cookies = require('js-cookie');
var qs = require('qs');

export interface Authentication {
  user: object;
  jwt: string;
}

export type Provider = 'facebook' | 'google' | 'github' | 'twitter';

export interface ProviderToken {
  access_token?: string;
  code?: string;
  oauth_token?: string;
}

export interface CookieConfig {
  key: string;
  options: object;
}

export interface LocalStorageConfig {
  key: string;
}

export interface StoreConfig {
  cookie?: CookieConfig | false;
  localStorage?: LocalStorageConfig | false;
}

module.exports = class Strapi {;
  public axios: AxiosInstance;
  public storeConfig: StoreConfig;

  /**
   * Default constructor.
   * @param baseURL Your Strapi host.
   * @param axiosConfig Extend Axios configuration.
   */
  constructor(
    baseURL: string,
    storeConfig?: StoreConfig,
    requestConfig?: AxiosRequestConfig
  ) {
    this.axios = axios.create({
      baseURL,
      paramsSerializer: qs.stringify,
      ...requestConfig
    });
    this.storeConfig = {
      cookie: {
        key: 'jwt',
        options: {
          path: '/'
        }
      },
      localStorage: {
        key: 'jwt'
      },
      ...storeConfig
    };

    if (this.isBrowser()) {
      let existingToken;
      if (this.storeConfig.cookie) {
        existingToken = Cookies.get(this.storeConfig.cookie.key);
      } else if (this.storeConfig.localStorage) {
        existingToken = JSON.parse(window.localStorage.getItem(
          this.storeConfig.localStorage.key
        ) as string);
      }
      if (existingToken) {
        this.setToken(existingToken, true);
      }
    }
  }

  /**
   * Axios request
   * @param method Request method
   * @param url Server URL
   * @param requestConfig Custom Axios config
   */
  public async request(
    method: string,
    url: string,
    requestConfig?: AxiosRequestConfig
  ): Promise<any> {
    try {
      const response: AxiosResponse = await this.axios.request({
        method,
        url,
        ...requestConfig
      });
      return response.data;
    } catch (error) {
      if (error.response) {
        throw new Error(error.response.data.message);
      } else {
        throw error;
      }
    }
  }

  /**
   * Register a new user.
   * @param username
   * @param email
   * @param password
   * @returns Authentication User token and profile
   */
  public async register(
    username: string,
    email: string,
    password: string
  ): Promise<Authentication> {
    this.clearToken();
    const authentication: Authentication = await this.request(
      'post',
      '/auth/local/register',
      {
        data: {
          email,
          password,
          username
        }
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * Login by getting an authentication token.
   * @param identifier Can either be an email or a username.
   * @param password
   * @returns Authentication User token and profile
   */
  public async login(
    identifier: string,
    password: string
  ): Promise<Authentication> {
    this.clearToken();
    const authentication: Authentication = await this.request(
      'post',
      '/auth/local',
      {
        data: {
          identifier,
          password
        }
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * Sends an email to a user with the link of your reset password page.
   * This link contains an URL param code which is required to reset user password.
   * Received link url format https://my-domain.com/rest-password?code=privateCode.
   * @param email
   * @param url Link that user will receive.
   */
  public async forgotPassword(email: string, url: string): Promise<void> {
    this.clearToken();
    await this.request('post', '/auth/forgot-password', {
      data: {
        email,
        url
      }
    });
  }

  /**
   * Reset the user password.
   * @param code Is the url params received from the email link (see forgot password).
   * @param password
   * @param passwordConfirmation
   */
  public async resetPassword(
    code: string,
    password: string,
    passwordConfirmation: string
  ): Promise<void> {
    this.clearToken();
    await this.request('post', '/auth/reset-password', {
      data: {
        code,
        password,
        passwordConfirmation
      }
    });
  }

  /**
   * Retrieve the connect provider URL
   * @param provider
   */
  public getProviderAuthenticationUrl(provider: Provider): string {
    return "" + (this.axios.defaults.baseURL) + "/connect/" + (provider) + "";
  }

  /**
   * Authenticate the user with the token present on the URL (for browser) or in `params` (on Node.js)
   * @param provider
   * @param params
   */
  public async authenticateProvider(
    provider: Provider,
    params?: ProviderToken
  ): Promise<Authentication> {
    this.clearToken();
    // Handling browser query
    if (this.isBrowser()) {
      params = qs.parse(window.location.search, { ignoreQueryPrefix: true });
    }
    const authentication: Authentication = await this.request(
      'get',
      "/auth/" + (provider) + "/callback",
      {
        params
      }
    );
    this.setToken(authentication.jwt);
    return authentication;
  }

  /**
   * List entries
   * @param contentTypePluralized
   * @param params Filter and order queries.
   */
  public getEntries(
    contentTypePluralized: string,
    params?: AxiosRequestConfig['params']
  ): Promise<object[]> {
    return this.request('get', "/" + (contentTypePluralized) + "", {
      params
    });
  }

  /**
   * Get the total count of entries with the provided criteria
   * @param contentType
   * @param params Filter and order queries.
   */
  public getEntryCount(
    contentType: string,
    params?: AxiosRequestConfig['params']
  ): Promise<object[]> {
    return this.request('get', "/" + (contentType) + "/count", {
      params
    });
  }

  /**
   * Get a specific entry
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   */
  public getEntry(contentTypePluralized: string, id: string): Promise<object> {
    return this.request('get', "/" + (contentTypePluralized) + "/" + (id) + "");
  }

  /**
   * Create data
   * @param contentTypePluralized Type of entry pluralized
   * @param data New entry
   */
  public createEntry(
    contentTypePluralized: string,
    data: AxiosRequestConfig['data']
  ): Promise<object> {
    return this.request('post', "/" + (contentTypePluralized) + "", {
      data
    });
  }

  /**
   * Update data
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   * @param data
   */
  public updateEntry(
    contentTypePluralized: string,
    id: string,
    data: AxiosRequestConfig['data']
  ): Promise<object> {
    return this.request('put', "/" + (contentTypePluralized) + "/" + (id) + "", {
      data
    });
  }

  /**
   * Delete an entry
   * @param contentTypePluralized Type of entry pluralized
   * @param id ID of entry
   */
  public deleteEntry(
    contentTypePluralized: string,
    id: string
  ): Promise<object> {
    return this.request('delete', "/" + (contentTypePluralized) + "/" + (id) + "");
  }

  /**
   * Search for files
   * @param query Keywords
   */
  public searchFiles(query: string): Promise<object[]> {
    return this.request('get', "/upload/search/" + (decodeURIComponent(query)) + "");
  }

  /**
   * Get files
   * @param params Filter and order queries
   * @returns Object[] Files data
   */
  public getFiles(params?: AxiosRequestConfig['params']): Promise<object[]> {
    return this.request('get', '/upload/files', {
      params
    });
  }

  /**
   * Get file
   * @param id ID of entry
   */
  public getFile(id: string): Promise<object> {
    return this.request('get', "/upload/files/" + (id) + "");
  }

  /**
   * Upload files
   *
   * ### Browser example
   * ```js
   * var form = new FormData();
   * form.append('files', fileInputElement.files[0], 'file-name.ext');
   * form.append('files', fileInputElement.files[1], 'file-2-name.ext');
   * var files = await strapi.upload(form);
   * ```
   *
   * ### Node.js example
   * ```js
   * var FormData = require('form-data');
   * var fs = require('fs');
   * var form = new FormData();
   * form.append('files', fs.createReadStream('./file-name.ext'), 'file-name.ext');
   * var files = await strapi.upload(form, {
   *   headers: form.getHeaders()
   * });
   * ```
   *
   * @param data FormData
   * @param requestConfig
   */
  public upload(
    data: FormData,
    requestConfig?: AxiosRequestConfig
  ): Promise<object> {
    return this.request('post', '/upload', {
      data,
      ...requestConfig
    });
  }

  /**
   * Set token on Axios configuration
   * @param token Retrieved by register or login
   */
  public setToken(token: string, comesFromStorage?: boolean): void {
    this.axios.defaults.headers.common.Authorization = 'Bearer ' + token;
    if (this.isBrowser() && !comesFromStorage) {
      if (this.storeConfig.localStorage) {
        window.localStorage.setItem(
          this.storeConfig.localStorage.key,
          JSON.stringify(token)
        );
      }
      if (this.storeConfig.cookie) {
        Cookies.set(
          this.storeConfig.cookie.key,
          token,
          this.storeConfig.cookie.options
        );
      }
    }
  }

  /**
   * Remove token from Axios configuration
   */
  public clearToken(): void {
    delete this.axios.defaults.headers.common.Authorization;
    if (this.isBrowser()) {
      if (this.storeConfig.localStorage) {
        window.localStorage.removeItem(this.storeConfig.localStorage.key);
      }
      if (this.storeConfig.cookie) {
        Cookies.remove(
          this.storeConfig.cookie.key,
          this.storeConfig.cookie.options
        );
      }
    }
  }

  /**
   * Check if it runs on browser
   */
  private isBrowser(): boolean {
    return typeof window !== 'undefined';
  }
}

