var Muster = require('@dws/muster').Muster;
var Message = require('@dws/muster-message-transport').Message;

export type SendMessage = function (message: Message<any>) { return void; };

export interface CommandRunner {
  runCommand(message: Message<any>): void;
  sendMessage: SendMessage;
}

export interface CommandRunnerState {}

export interface DevToolsCommand<
  T extends string,
  M extends Message<T>,
  C,
  S extends CommandRunnerState
> {
  name: T;
  run(this: CommandExecutionContext<C, S>, message: M): void;
}

export interface CommandExecutionContext<T, S extends CommandRunnerState> {
  app: Muster;
  config: T;
  getState(): S;
  setState(setter: function (state: S) { return S; }): void;
  sendMessage: SendMessage;
}

function createCommandExecutionContext<C, S extends CommandRunnerState>(
  app: Muster,
  config: C,
  initialState: S,
  sendMessage: SendMessage,
): CommandExecutionContext<C, S> {
  let state = initialState;
  return {
    app,
    config,
    getState() {
      return state;
    },
    setState(setter) {
      state = setter(state);
    },
    sendMessage,
  };
}

function createCommandRunner<C, S extends CommandRunnerState>(
  commandFactories: Array<DevToolsCommand<any, Message<any>, C, S>>,
  app: Muster,
  sendMessage: SendMessage,
  config: C,
  initialState: S,
): CommandRunner {
  const executionContext = createCommandExecutionContext(app, config, initialState, sendMessage);
  const commandsMap = commandFactories.reduce(
    function (map, command) {
      if (map[command.name]) {
        throw new Error("Command " + (command.name) + " already exists!");
      }
      map[command.name] = command;
      return map;
    },
    {} as { [key: string]: DevToolsCommand<any, SendMessage, C, S> },
  );
  return {
    runCommand(message: Message<any>) {
      const command = commandsMap[message.name];
      // Check if the command is supported by the runner
      if (!command) return;
      command.run.call(executionContext, message);
    },
    sendMessage,
  };
}

// Drafted using common development resources

import {
	randomBytes,
	createCipheriv,
	createDecipheriv,
	createHash,
} from "crypto"

class Crypto {
	private static readonly CIPHER = "aes-256-cbc"
	private readonly SECRET_KEY: Buffer

	constructor(key: string) {
		if (key.length !== 128) {
			throw new Error("Key must be 128 characters long")
		}

		// Hash the key to derive a 32-byte key suitable for AES-256-CBC
		this.SECRET_KEY = createHash("sha256").update(key).digest()
	}

	/**
	 * Encrypts the given plaintext using AES-256-CBC cipher and returns the encrypted data in base64 format.
	 *
	 * @param plaintext The plaintext string to be encrypted.
	 * @returns The base64-encoded encrypted string which includes both the IV and ciphertext.
	 */
	encrypt(plaintext: string): string {
		var iv = randomBytes(16) // IV length for AES-256-CBC is 16 bytes
		var cipher = createCipheriv(Crypto.CIPHER, this.SECRET_KEY, iv)
		var encrypted = Buffer.concat([
			cipher.update(plaintext, "utf8"),
			cipher.final(),
		])

		// Combine IV and ciphertext, then encode in base64
		return Buffer.concat([iv, encrypted]).toString("base64")
	}

	/**
	 * Decrypts the given base64-encoded encrypted string and returns the original plaintext.
	 *
	 * @param encrypted The base64-encoded string to be decrypted.
	 * @returns The decrypted plaintext.
	 */
	decrypt(encrypted: string): string {
		var data = Buffer.from(encrypted, "base64")
		var iv = data.subarray(0, 16) // Extract the IV (first 16 bytes)
		var ciphertext = data.subarray(16) // Extract the ciphertext

		var decipher = createDecipheriv(Crypto.CIPHER, this.SECRET_KEY, iv)
		var decrypted = Buffer.concat([
			decipher.update(ciphertext),
			decipher.final(),
		])

		return decrypted.toString("utf8")
	}
}

module.exports = Crypto;

var RustUtilities = require('./rust_utilities').RustUtilities;

export interface RoomConfiguration {
    server_url?: string,
    room_name?: string,
    ice_servers?: RTCIceServer[],
    on_state_change?: function (room_state: RoomState) { return void; };
    on_peer_joined?: function (peer_id: PeerId) { return void; };
    on_peer_left?: function (peer_id: PeerId, time: number) { return void; };
    on_message?: function (peer_id: PeerId, message: Uint8Array) { return void; };
}

export type PeerId = number;

export enum RoomState {
    Joining,
    Connected,
    Disconnected
}

type Peer = {
    id: PeerId,
    connection: RTCPeerConnection,
    data_channel: RTCDataChannel,
    ready: boolean,
    latest_message_data: Uint8Array
    latest_message_offset: number,
}

enum MessageType {
    MultiPartStart = 1,
    MultiPartContinuation = 2,
    SinglePart = 3,
    SinglePartGzipped = 4,
}

const MAX_MESSAGE_SIZE = 16_000;

// TODO: This is Aided using common development resources. Audit it.
function compute_id_from_ip(ipAddress: string): number {
    let uniqueNumber = 0;
    const parts = ipAddress.split(':');
    const ip = parts[0].split('.');
    const port = parseInt(parts[1], 10);

    for (let i = 0; i < 4; i++) {
        uniqueNumber += parseInt(ip[i], 10) * Math.pow(256, 3 - i);
    }
    uniqueNumber += port;

    return uniqueNumber;
}

class Room {
    private _peers_to_join: Set<PeerId> = new Set();
    private _current_state: RoomState = RoomState.Disconnected;
    private _peers: Map<PeerId, Peer> = new Map();
    private _configuration: RoomConfiguration = {};
    private _outgoing_data_chunk = new Uint8Array(MAX_MESSAGE_SIZE + 5);
    private _rust_utilities: RustUtilities;
    private _server_socket?: WebSocket;

    // Default to 1 because 0 conflicts with the 'system' ID.
    my_id = 1;

    // Used for testing
    private _artificial_delay = 0;

    constructor(rust_utilities: RustUtilities) {
        this._rust_utilities = rust_utilities;
    }

    static async setup(_configuration: RoomConfiguration, rust_utilities: RustUtilities): Promise<Room> {
        const room = new Room(rust_utilities);
        await room._setup_inner(_configuration);
        return room;
    }

    private message_peer_inner(peer: Peer, data: Uint8Array) {
        if (!(peer.data_channel.readyState === "open")) {
            // TODO: This could result in desyncs if this happens.
            return;
        }

        // Gzip encode large messages.
        // For very small messages Gzip encoding actually makes them bigger.
        // This conditional is separate so that if the Gzip data is < MAX_MESSAGE_SIZE 
        // it becomes a small message.
        let message_type = MessageType.SinglePart;
        if (data.byteLength > MAX_MESSAGE_SIZE) {
            message_type = MessageType.SinglePartGzipped;
            data = this._rust_utilities.gzip_encode(data);
        }

        // If the message is too large fragment it. 
        // TODO: If there's not space in the outgoing channel push messages to an outgoing buffer.
        if (data.byteLength > MAX_MESSAGE_SIZE) {
            this._outgoing_data_chunk[0] = MessageType.MultiPartStart;
            new DataView(this._outgoing_data_chunk.buffer).setUint32(1, data.byteLength);

            this._outgoing_data_chunk.set(data.subarray(0, MAX_MESSAGE_SIZE), 5);
            peer.data_channel.send(this._outgoing_data_chunk);

            let data_offset = data.subarray(MAX_MESSAGE_SIZE);

            while (data_offset.byteLength > 0) {
                const length = Math.min(data_offset.byteLength, MAX_MESSAGE_SIZE);
                this._outgoing_data_chunk[0] = MessageType.MultiPartContinuation;
                this._outgoing_data_chunk.set(data_offset.subarray(0, length), 1);
                data_offset = data_offset.subarray(length);

                peer.data_channel.send(this._outgoing_data_chunk.subarray(0, length + 1));

            }
        } else {
            this._outgoing_data_chunk[0] = message_type;
            this._outgoing_data_chunk.set(data, 1);

            peer.data_channel.send(this._outgoing_data_chunk.subarray(0, data.byteLength + 1));
        }

    }

    send_message(data: Uint8Array, peer_id?: PeerId) {
        if (peer_id) {
            // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
            const peer = this._peers.get(peer_id)!;
            this.message_peer_inner(peer, data);
        } else {
            for (const peer of this._peers.values()) {
                if (!peer.ready) {
                    continue;
                }

                this.message_peer_inner(peer, data);
            }
        }
    }

    get_lowest_latency_peer(): PeerId | undefined {
        // TODO: Implement this.
        return (this._peers.entries().next().value == null ? undefined : this._peers.entries().next().value[0]);
    }

    private async _setup_inner(room_configuration: RoomConfiguration) {
        this._configuration = room_configuration;
        this._configuration.server_url ??= "tangle-server.fly.dev";
        this._configuration.room_name ??= "";

        // TODO: Do not use metered's Turn servers
        // Investigate routing traffic through Tangle's matchmaking server or other Tangle servers.
        this._configuration.ice_servers ??= [
            {
                urls: "stun:relay.metered.ca:80",
            },
            {
                urls: "stun:stun1.l.google.com:19302"
            },
            {
                urls: "turn:relay.metered.ca:80",
                username: "acb3fd59dc274dbfd4e9ef21",
                credential: "1zeDaNt7C85INfxl",
            },
            {
                urls: "turn:relay.metered.ca:443",
                username: "acb3fd59dc274dbfd4e9ef21",
                credential: "1zeDaNt7C85INfxl",
            },
            {
                urls: "turn:relay.metered.ca:443?transport=tcp",
                username: "acb3fd59dc274dbfd4e9ef21",
                credential: "1zeDaNt7C85INfxl",
            },
        ];

        const connect_to_server = function () {
            const server_socket = new WebSocket("wss://" + this._configuration.server_url);

            let keep_alive_interval: number;

            server_socket.onopen = () => {
                console.log("[room] Connection established with server");
                console.log("[room] Requesting to join room: ", this._configuration.room_name);
                server_socket.send(JSON.stringify({ 'join_room': this._configuration.room_name }));

                // Poke the server every 10 seconds to ensure it doesn't drop our connection.
                // Without this it seems browsers don't send WebSocket native 'pings' as expected.
                // and some server providers (like fly.io) will shutdown inactive TCP sockets.
                // This also gives the server a chance to disconnect peers that become unresponsive.
                clearInterval(keep_alive_interval);
                keep_alive_interval = setInterval(function () {
                    server_socket.send("keep_alive");
                }, 10_000);
            };

            server_socket.onclose = (event) => {
                if (this._current_state != RoomState.Disconnected) {
                    clearInterval(keep_alive_interval);

                    // Disconnecting from the WebSocket is considered a full disconnect from the room.

                    // Call the on_peer_left handler for each peer
                    for (const peer_id of this._peers.keys()) {
                        (this._configuration.on_peer_left == null ? undefined : this._configuration.on_peer_left(peer_id, Date.now()));
                    }

                    this._current_state = RoomState.Disconnected;
                    this._peers_to_join.clear();
                    this._peers.clear();

                    if (event.wasClean) {
                        console.log("[room] Server connection closed cleanly, code=" + (event.code) + " reason=" + (event.reason) + "");
                    } else {
                        console.log("[room] Server connection unexpectedly closed. code=" + (event.code) + " reason=" + (event.reason) + "");
                        console.log("event: ", event);
                    }

                    (this._configuration.on_state_change == null ? undefined : this._configuration.on_state_change(this._current_state));
                }

                // Attempt to reconnect
                setTimeout(function () {
                    console.log("[room] Attempting to reconnect to server...")
                    connect_to_server();
                }, 250);
            };

            server_socket.onerror = function (error) {
                console.log("[room] Server socket error:", error);
                server_socket.close();
            };

            server_socket.onmessage = async (event) => {
                const last_index = event.data.lastIndexOf('}');
                const json = event.data.substring(0, last_index + 1);

                const message = JSON.parse(json);
                // peer_id is appended by the server to the end of incoming messages.
                const peer_ip = event.data.substring(last_index + 1).trim();
                const peer_id = compute_id_from_ip(peer_ip);

                if (message.room_name) {
                    /*
                    var url = new URL(message.room_name);
                    var location = document.location;
                    if (url.href != location.href) {
                        console.error("[room] Tried to join a room that doesn't match current host URL");
                        return;
                    }
                    */

                    // Received when joining a room for the first time.
                    console.log("[room] Entering room: ", message.room_name);

                    this._current_state = RoomState.Joining;

                    const peers_to_join_ids = message.peers.map(compute_id_from_ip);
                    this._peers_to_join = new Set(peers_to_join_ids);

                    (this._configuration.on_state_change == null ? undefined : this._configuration.on_state_change(this._current_state));

                    // If we've already connected to a peer then remove it from _peers_to_join.
                    for (const key of this._peers.keys()) {
                        this._peers_to_join.delete(key);
                    }
                    this.check_if_joined();

                    this.my_id = compute_id_from_ip(message.your_ip);
                    console.log("[room] My id is: %d", this.my_id);
                } else if (message.join_room) {
                    console.log("[room] Peer joining room: ", peer_id);
                    this.make_rtc_peer_connection(peer_ip, peer_id, server_socket);
                } else if (message.offer) {
                    const peer_connection = this.make_rtc_peer_connection(peer_ip, peer_id, server_socket);
                    await peer_connection.setRemoteDescription(new RTCSessionDescription(message.offer));
                    const answer = await peer_connection.createAnswer();
                    await peer_connection.setLocalDescription(answer);
                    server_socket.send(JSON.stringify({ 'answer': answer, 'destination': peer_ip }));
                } else if (message.answer) {
                    const remoteDesc = new RTCSessionDescription(message.answer);
                    await this._peers.get(peer_id)?.connection.setRemoteDescription(remoteDesc);
                } else if (message.new_ice_candidate) {
                    try {
                        await this._peers.get(peer_id)?.connection.addIceCandidate(message.new_ice_candidate);
                    } catch (e) {
                        console.error("[room] Error adding received ice candidate", e);
                    }
                } else if (message.disconnected_peer_id) {
                    const disconnected_peer_id = compute_id_from_ip(message.disconnected_peer_id);
                    console.log("[room] Peer left: ", disconnected_peer_id);
                    this.remove_peer(disconnected_peer_id, message.time);
                    this._peers_to_join.delete(disconnected_peer_id);
                    this.check_if_joined();
                }
            };
        };
        connect_to_server();
    }

    private check_if_joined() {
        if (this._current_state == RoomState.Joining && this._peers_to_join.size == 0) {
            this._current_state = RoomState.Connected;
            (this._configuration.on_state_change == null ? undefined : this._configuration.on_state_change(this._current_state));
        }
    }

    private make_rtc_peer_connection(peer_ip: string, peer_id: PeerId, server_socket: WebSocket): RTCPeerConnection {
        const peer_connection = new RTCPeerConnection({ 'iceServers': this._configuration.ice_servers });

        // TODO: If this is swapped to a more unreliable UDP-like protocol then ordered and maxRetransmits should be set to false and 0.
        //
        // maxRetransmits: null is meant to be the default but explicitly setting it seems to trigger a Chrome
        // bug where some packets are dropped.
        // TODO: Report this bug.
        const data_channel = peer_connection.createDataChannel("sendChannel", { negotiated: true, id: 2, ordered: true });
        data_channel.binaryType = "arraybuffer";

        peer_connection.onicecandidate = function event {
            console.log("[room] New ice candidate: ", event.candidate);
            if (event.candidate) {
                console.log(JSON.stringify({ 'new_ice_candidate': event.candidate, 'destination': peer_ip }));
                server_socket.send(JSON.stringify({ 'new_ice_candidate': event.candidate, 'destination': peer_ip }));
            }
        };

        peer_connection.onicecandidateerror = function (event) {
            console.log("[room] Ice candidate error: ", event);
        };

        peer_connection.onnegotiationneeded = async function () {
            console.log("[room] Negotiation needed");
            const offer = await peer_connection.createOffer();
            await peer_connection.setLocalDescription(offer);
            server_socket.send(JSON.stringify({ 'offer': offer, 'destination': peer_ip }));
        };

        peer_connection.onsignalingstatechange = function () {
            console.log("[room] Signaling state changed: ", peer_connection.signalingState)
        };

        peer_connection.onconnectionstatechange = function () {
            console.log("[room] Connection state changed: ", peer_connection.connectionState)
        };

        peer_connection.ondatachannel = function (event) {
            peer.data_channel = event.channel;
        };

        data_channel.onopen = function () {
            this._peers_to_join.delete(peer_id);
            peer.ready = true;
            (this._configuration.on_peer_joined == null ? undefined : this._configuration.on_peer_joined(peer_id));
            this.check_if_joined();
        }

        data_channel.onmessage = function (event) {
            // First check that this peer hasn't been officially disconnected.
            if (this._peers.get(peer_id)) {
                if (event.data.byteLength > 0) {
                    // Defragment the message
                    const message_data = new Uint8Array(event.data);
                    switch (message_data[0]) {
                        case MessageType.SinglePart: {
                            // Call the user provided callback
                            // Message received
                            const data = message_data.subarray(1);

                            // TODO: This introduces a potential one-frame delay on incoming events.
                            setTimeout(() => {
                                (this._configuration.on_message == null ? undefined : this._configuration.on_message(peer_id, data));
                            }, this._artificial_delay);
                            break;
                        }
                        case MessageType.SinglePartGzipped: {
                            // Call the user provided callback
                            const data = this._rust_utilities.gzip_decode(message_data.subarray(1));
                            // TODO: This introduces a potential one-frame delay on incoming events.
                            setTimeout(() => {
                                (this._configuration.on_message == null ? undefined : this._configuration.on_message(peer_id, data));
                            }, this._artificial_delay);
                            break;
                        }
                        case MessageType.MultiPartStart: {
                            const data = new DataView(message_data.buffer, 1);
                            const length = data.getUint32(0);

                            peer.latest_message_data = new Uint8Array(length);
                            this.multipart_data_received(peer, message_data.subarray(5));
                            break;
                        }
                        case MessageType.MultiPartContinuation: {
                            this.multipart_data_received(peer, message_data.subarray(1));
                        }
                    }
                }
            } else {
                console.error("DISCARDING MESSAGE FROM PEER: ", event.data);
            }
        }

        const peer = { id: peer_id, connection: peer_connection, data_channel, ready: false, latest_message_data: new Uint8Array(0), latest_message_offset: 0 };
        this._peers.set(peer_id, peer);
        return peer_connection;
    }

    private multipart_data_received(peer: Peer, data: Uint8Array) {
        peer.latest_message_data.set(data, peer.latest_message_offset);
        peer.latest_message_offset += data.byteLength;

        if (peer.latest_message_offset == peer.latest_message_data.length) {
            let data = peer.latest_message_data;
            data = this._rust_utilities.gzip_decode(data);

            // TODO: This introduces a potential one-frame delay on incoming events.
            // Message received
            setTimeout(function () {
                (this._configuration.on_message == null ? undefined : this._configuration.on_message(peer.id, data));
            }, this._artificial_delay);
            peer.latest_message_offset = 0;
            peer.latest_message_data = new Uint8Array(0);
        }
    }

    private remove_peer(peer_id: PeerId, time: number) {
        const peer = this._peers.get(peer_id);

        if (peer) {
            peer.connection.close();
            this._peers.delete(peer_id);
            (this._configuration.on_peer_left == null ? undefined : this._configuration.on_peer_left(peer_id, time));
        }
    }

    disconnect() {
        this._server_socket?.close();
    }
}

var Injectable = require('@nestjs/common').Injectable;
var OnModuleInit = require('@nestjs/common').OnModuleInit;
var OnModuleDestroy = require('@nestjs/common').OnModuleDestroy;
var PrismaClient = require('@prisma/client').PrismaClient;

@Injectable()
class PrismaService extends PrismaClient implements OnModuleInit{
    async onModuleInit() {      
        await this.$connect();
    }
    async onModuleDestroy() {
        await this.$disconnect();
    }
}


// Here's a breakdown of the logic Penned via standard programming aids:

// @nestjs/common and @prisma/client are imported. The @nestjs/common package provides decorators and utility functions for creating NestJS applications, and @prisma/client is the client library generated by Prisma based on your data model.

// The PrismaService class is defined. This class extends the PrismaClient class, which is provided by the @prisma/client package. Extending PrismaClient allows you to use the generated Prisma client methods for querying and manipulating your database.

// The PrismaService class implements the OnModuleInit and OnModuleDestroy interfaces. These interfaces are part of the NestJS lifecycle events system and allow you to perform actions when a module is initialized or destroyed.

// The onModuleInit method is defined. This method is executed when the module containing the PrismaService is initialized. Inside this method, the this.$connect() method is called. This establishes a connection to the database using the Prisma client.

// The onModuleDestroy method is defined. This method is executed when the module containing the PrismaService is destroyed. Inside this method, the this.$disconnect() method is called. This disconnects the Prisma client from the database.

// By using this approach, you ensure that your Prisma client is connected when the module is initialized and disconnected when the module is destroyed. This helps manage database connections efficiently and prevents connection leaks.

// In your NestJS modules, you can inject the PrismaService and use its methods to interact with the database using Prisma's generated client methods.

var IncomingMessage = require('http').IncomingMessage;
var fp = require('fastify-plugin');
var PluginOptions = require('fastify-plugin').PluginOptions;
var FastifyInstance = require('fastify').FastifyInstance;
var FastifyRequest = require('fastify').FastifyRequest;

const kMultipart = Symbol('multipart')

function setMultipart(
  req: FastifyRequest,
  _payload: IncomingMessage,
  done: function (err: Error | null) { return void; },
) {
  // nothing to do, it will be done by multer in beforeHandler method
  ;(req as any)[kMultipart] = true
  done(null)
}

function isMultipart(this: FastifyRequest): boolean {
  return (this.raw as any)[kMultipart] || false
}

function fastifyMulter(
  fastify: FastifyInstance,
  _options: PluginOptions,
  next: function (err?: Error) { return void; },
) {
  fastify.addContentTypeParser('multipart', setMultipart)
  fastify.decorateRequest('isMultipart', isMultipart)

  next()
}

const multer = fp(fastifyMulter, {
  fastify: '>= 3.0.0',
  name: 'fastify-multer',
})

module.exports = multer;

var Address = require('@entropy1729/aleo-sdk').Address;
var PrivateKey = require('@entropy1729/aleo-sdk').PrivateKey;
var Signature = require('@entropy1729/aleo-sdk').Signature;
var ViewKey = require('@entropy1729/aleo-sdk').ViewKey;

interface AccountParam {
  privateKey?: string;
  seed?: Uint8Array;
}
/**
 * Class that represents an Aleo Account with a PrivateKey, from which an Address and a ViewKey derive.
 * Can be created with an existing private key, a seed or simply be randomly generated.
 * A seed consists of 32 bytes.
 * @example
 * var myRandomAccount = new Account();
 * var seed = 'ce8b23470222bdee5f894ee77b607391';
 * var arr = Uint8Array.from(seed)
 * var mySeededAccount = new Account({seed: 'ce8b23470222bdee5f894ee77b607391'});
 * var myExistingAccount = new Account({privateKey: 'myExistingPrivateKey'})
 */
class Account {
  pk: PrivateKey;
  vk: ViewKey;
  adr: Address;

  constructor(params: AccountParam = {}) {
    try {
      this.pk = this.privateKeyFromParams(params);
    } catch (e) {
      console.error("Wrong parameter", e);
      throw new Error("Wrong Parameter");
    }
    this.vk = ViewKey.from_private_key(this.pk);
    this.adr = Address.from_private_key(this.pk);
  }
  private privateKeyFromParams(params: AccountParam) {
    if (params.seed) {
      return PrivateKey.from_seed_unchecked(params.seed);
    }
    if (params.privateKey) {
      return PrivateKey.from_string(params.privateKey);
    }
    return new PrivateKey();
  }

  keys() {
    return {
      Address: this.adr.to_string(),
      ViewKey: this.vk.to_string(),
      PrivateKey: this.pk.to_string(),
    };
  }

  privateKey() {
    return this.pk;
  }

  viewKey() {
    return this.vk;
  }

  address() {
    return this.adr;
  }

  /**
   * Decrypts a Record given a ciphertext.
   * @param {string} ciphertext
   * @returns {Record}
   *
   * @example
   * var account = new Account();
   * var record = account.decryptRecord("record1...");
   */
  decryptRecord(ciphertext: string) {
    return this.vk.decrypt(ciphertext);
  }

  /**
   * Decrypts a set of Records given an array of ciphertexts.
   * @param {string[]} ciphertexts
   * @returns {Record[]}
   *
   * @example
   * var account = new Account();
   * var record = account.decryptRecords(["record1...", "record2..."]);
   */
  decryptRecords(ciphertexts: string[]) {
    return ciphertexts.map(function (ciphertext) { return this.vk.decrypt(ciphertext); });
  }

  /**
   * Signs a message with the account's private key.
   * Returns a Signature.
   *
   * @param {Uint8Array} message
   * @returns {Signature}
   *
   * @example
   * var account = new Account();
   * account.sign("a message");
   */
  sign(message: Uint8Array) {
    return this.pk.sign(message);
  }

  /**
   * Verifies the Signature on a message.
   *
   * @param {Uint8Array} message
   * @param {Signature} signature
   * @returns {boolean}
   *
   * @example
   * var account = new Account();
   * var message = "a message";
   * var signature = account.sign(message);
   * account.verify(message, signature);
   */
  verify(message: Uint8Array, signature: Signature) {
    return this.adr.verify(message, signature);
  }
}

var Commands = require('./definitions').Commands;
var Command = require('./definitions').Command;
var Action = require('./definitions').Action;

export type CommandAndPieces = { command: Command, remainingPieces: string[] };

const actionToCommand = (action: Action): function Command { return ({ action }); };

/**
 * Return the Command object the command string specifies.
 * Returns false if the command string did not have a valid command;
 * @param promptResponse
 */
function findPromptedCommand(promptResponse: string[], commands: Commands): CommandAndPieces | false {
    const command = commands[promptResponse[0]];

    if (!command) return false;

    if (command instanceof Function) {
        return {
            command: actionToCommand(command),
            remainingPieces: promptResponse.slice(1)
        };
    }

    if (command.subcommands) {
        const subcommand = findPromptedCommand(promptResponse.slice(1), command.subcommands);
        if (subcommand) return subcommand;
    }

    return { command, remainingPieces: promptResponse.slice(1) };
}

var getConnectionManager = require('typeorm').getConnectionManager;
var EntityManager = require('typeorm').EntityManager;
var BaseEntity = require('typeorm').BaseEntity;
var Repository = require('typeorm').Repository;
var getRepository = require('typeorm').getRepository;
var Entity = require('typeorm').Entity;
var Observable = require('rxjs').Observable;
var of = require('rxjs').of;
var from = require('rxjs').from;
var map = require('rxjs/operators').map;
var async = require('rxjs/internal/scheduler/async').async;
var User = require('../entity/User').User;
const COLUMN = '@column'
const ORDER = '@order'
const RELATION = '@relation'

const GetColumn = function (where: any) {
    let result = where[COLUMN]
    if (result) {
        result = result.split(',')
        Reflect.deleteProperty(where, COLUMN)
        return result
    } else {
        return null
    }
}
const GetOrder = function (where: any) {
    let result = where[ORDER]
    if (result) {
        result = result.split(',')
        Reflect.deleteProperty(where, ORDER)
        let _result = {}
        for (let item of result) {
            if (item.endsWith('+')) {
                _result[item.replace('+', '')] = 'ASC'
            } else if (item.endsWith('-')) {
                _result[item.replace('-', '')] = 'DESC'
            } else {
                _result[item] = 'ASC'
            }
        }
        return _result
    } else {
        return null
    }
}
const GetRelation = function (where: any, thisItem: any) {
    let result = {};
    if (!thisItem) {
        return 
    }
    for (let prop in where) {
        if (prop.endsWith('@')) {
            if (where[prop].startsWith('/')) {
                let arr = where[prop].split('/').filter(item => item)
                if (arr && arr.length) {
                    let _id = Object.assign({}, thisItem);
                    for (let _prop of arr) {
                        if (_prop.endsWith('Id')) {
                            _prop = _prop.replace('Id', '')
                        }
                        _id = _id[_prop]
                    }
                    result[prop.replace('@', '')] = _id;
                }
            }
            // Reflect.deleteProperty(where, prop)  [BUG]
        }
    }
    return result
}
const GetRelations = function (where: { [key: string]: any }) {
    let result = where[RELATION]
    if (result) {
        result = result.map(item => item.toLowerCase())
        Reflect.deleteProperty(where, RELATION)
        return result
    } else {
        return null
    }
}
/**
 * 
 * @param tableName 
 * @param page 
 * @param count 
 * @param where 
 * @param thisItem 该数据所在的json{}
 */
const GetTableData = async function (tableName: string, page: number = 0, count: number = 1, where: any = {}, thisItem?: any) {
    let repository: Repository<any>
    let result
    try {
        repository = getRepository(tableName)
        let select = GetColumn(where)
        let order = GetOrder(where)
        let relation = GetRelation(where, thisItem)
        let relations = GetRelations(where)
        let loadRelationIds = relations ? null : { disableMixedMap: false }
        // console.log(where)
        result = await repository.find({
            where: {
                ...where,
                ...relation,
            },
            take: page,
            skip: page * count,
            select,
            order,
            loadRelationIds,
            relations
        })
    } catch (error) {

    }
    return result;
}
const GetFirstData = async function (tableName: string, where: any = {}, thisItem?: any) {
    let repository: Repository<any>
    let result
    try {
        repository = getRepository(tableName)
        let select = GetColumn(where)
        let relation = GetRelation(where, thisItem)
        let relations = GetRelations(where)
        let loadRelationIds = relations ? null : { disableMixedMap: false }
        result = await repository.findOne({
            where: {
                ...where,
                ...relation
            },
            select,
            loadRelationIds,
            relations
        })
    } catch (error) {

    }
    return result;
}
const A = async function (apijson: Object, isArray = false) {
    let result = {}
    let page = 0, count = 1, query = 0, total = 0;
    for (let prop in apijson) {
        prop = prop.trim();
        let item = apijson[prop]
        let tables = [], where = []

        if (prop == '[]') {
            page = item.page ? item.page : page
            count = item.count ? item.count : count
            query = item.query ? item.query : query
            Reflect.deleteProperty(item, 'page')
            Reflect.deleteProperty(item, 'count')
            Reflect.deleteProperty(item, 'query')
            for (let _prop in item) {
                tables.push(_prop)
                where.push(item[_prop])
            }
            if (tables.length) {
                let tableName = tables[0]
                let temp = await GetTableData(tableName, page, count, where[0])
                temp = temp ? temp.map(item => ({
                    [tableName]: item
                })) : []
                for (let _temp of temp) {
                    for (let i = 1; i < tables.length; i++) {
                        let tableName: string = tables[i]
                        if (tableName.endsWith('[]')) {
                            const _tableName = tableName.split('[]')[0]
                            _temp[tableName] = await GetTableData(_tableName, page, count, where[i], _temp)
                        } else {
                            _temp[tableName] = await GetFirstData(tableName, where[i], _temp)
                        }
                    }
                }
                result[prop] = temp
            }
        }

    }
    return result
}
